INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p988-engl101', 'tg-u913230683', 'ENGL 101', 'info', '{"desc":"الرايتنق لازم تكتب 5 ايساي \nواحد Cc واحد CE\nواحد Argu\nويبقى عندك اثنين تختار اي ثنين يعجبوك من الي فوق وتكتب عنهم\nطريقه الكتاب تكون درافت ون يعطونك عليه فيد باك بعدين درافت تو وفيدباك واخر شي الفاينل درافت \nتعيد هذي العمليه ع الخمس ايسايز\nوقت تسليم الرايتنق تقريبا اخر الترم","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/988","user":"","ts":1664482670000,"mid":988}}', 1664482670000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p1005-engl101', 'tg-zso15', 'ENGL 101', 'info', '{"desc":"اللي سويته انا \nاكتب واحد بعدين اصححه \nطبعًا بالملف الاول هو يكون فيه الكومنتات والحذف وكذا \nالملف الثاني احط الرايتنق الاول بعد التعديلات \nبعدين اخذ فيدباك من احد الاصدقاء ويكون في نفس الملف \nوالثالث هو يكون بعد تعديلات الثاني","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/1005","user":"zso15","ts":1664530199000,"mid":1005}}', 1664530199000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p3742-engl101', 'tg-u1987683805', 'ENGL 101', 'info', '{"desc":"القرامر تدربت من التدريبات اللي كانت في الملف ولاحظت إن عندي ضعف في بعض القواعد بحثت في اليوتيوب عن شرح لها وفهمتها وراجعت آخر صفحات من الهيدواي حق ٠٤ اللي تكون ملخص لكل الوحدات أم الريدنق ما ذاكرت له بس أو ما استلمت ورقة الاختبار بديت بالفوكاب والقرامر وحاولت أخلصهم بسرعة عشان يكون عندي وقت للريدنق وكل ما خلصت الفوكاب والقرامر بسرعة بتقدر تجيب درجة أعلى في الريدنق لأنه ما كان صعب بس يحتاج وقت","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/3742","user":"","ts":1666286038000,"mid":3742}}', 1666286038000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p3770-engl101', 'tg-someone_i4', 'ENGL 101', 'info', '{"desc":"بالنسبه للريدنق مااظن فيه طريقه لمذاكرته احسن من الريدنق بورتفوليو ، بيعودك عالقراءه و بيجيك واحد من النصوص اللي فيه فالاختبار ف مب تتعب وانت تحل اسألته \n\nواتوقع ذا الهدف من الريدنق بورتفوليو اساسا\n\nالريدنق بورتفوليو يخلي جزء الريدنق اخف بكثير\nالAWL اغلبها كان سهل لكن برضو دكتورنا عطانا موقع تدريب طقطقت عليه شوي وفرق معي\n\nالقرامر اخذت فكره عن القواعد اللي بتجي بس\n\nالقرامر دكتورنا عطانا ملف فيه شرح لهم كلهم \nالفوكاب المطلوب هو ال academic word list وتقدر تلقى له تدريبات كثيره\nالريدنق تتدرب عليه بالريدنق بورتفوليو\n\nسالت دكتورنا عنها قالي لاتشيل هم انك تجاوب كلشي صح 100% فهالاساله هذي و اساله الصح والخطا والغير مذكور لان التقييم مب يركز على الحل قد مايركز على انك تبين انك قاري باهتمام\n\nبتتكلم عن 3 انوع رايتنق : compare and contrast - cause and effect - argumentative\n\nالكورس ٦٠٪ رايتنق\n١٥ ميد \n١٥ فاينل \n١٠ بورتفوليووز\n\nالميد والفاينل فيه جزء منها قرامر وفوكاب\nوالرايتنق يحتاج قرامر وفوكاب\n\nالريدنق بس اقرا وبين انتبهاة وتركيزك بالنص جد يعني\n\nحدد الاشياء المهمه واكتب تعليقات و اراء و اعد صياغه بعض الجمل وجيب معاني الكلمات و اسال اساله و وضح ليش هالمعلومه مفيده وووو الخ الخ\n\nفيه اساله بالريدنق بورتفوليو بعد او قبل كل نص \n\nاللي عليك انك تحلها حسب فهمك للنص، وتكتب جمل كامله و اجابات فيها تفصيييل\n\nبالنسبه لي الفيدباك علمني كل شي انا احتاج اتطور فيه ونبهني ع اغلاط دايم اطيح فيها \n\nو اللي صار ان كل رايتنق تاسك كان يرتفع قريدي  \n\nبس برضو الفيدباك ماكان بس اللي يعطون بعد البراكتس تيست، انا كنت دايم اروح واساله عن اشياء معينه انا ضايع فيها ومايقصر\n\nالتحضير مره متساعد، عندك ١٠ دقايق  وبعدها ليت ٢٠ دقيقه وبعدها ابسنت ومرات يسمح تحضر سكاشن ثانيه\n\nالكتابه بشكل عام هي شيئين رئيسين برايي من ناحية التطبيق، وعدة اشياء من الناحية الذهنيه\n\nكتطبيق انت لازم يكون عندك تمكن من الكتابه بالقلم بوضوح و سرعة ممتازة وهذي تيجي بالتدريب\nلازم تكون مرتب لما تكتب بحيث ماتنقز كثير وتخرب السلسه\nوهذي الاشياء تجيك ببساطه لما تمارسين الكتابه وتصير عادات \n\nبالنسبه لذهنيا \n\nبكل بساطة حافظي ع هدوئك طول ماانتي تكتبين وارسمي خطه ببالك قبل تبدين كتابة \n\nتعلمي كيف تنتجين اكبر قدر ممكن من المعلومات بوقت قصير","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/3770","user":"someone_I4","ts":1666293576000,"mid":3770,"mids":[3770,5464,7200,7556,15724,16663,22534,40603,45940]}}', 1666293576000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p5721-engl101', 'tg-rrriim', 'ENGL 101', 'info', '{"desc":"خمسه رايتنق \nاقل شي ايساي واحد من كل نوع واكثر شي اثنين من كل نوع\n\nكل واحد ٣-٤ درافتات \nالاول يكون فاضي بدون ولا كومنت\nالثاني والثالث مع الكومنتات\nالرابع النهائي بدون كومنت\n\nاتوقع مفروض عندك اقل شي ٢ فيد باك من دكتورك \nواقل شي ٣ بيير فيد باك\n\nالدكتوره تقول بشوف درافت ون والاخير ولازم يكون في بينهم تطور كبير\n\nمدري اذا في شي زياده شوف السلايدات حقت الرايتنق بورتفليو","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/5721","user":"RRRIIm","ts":1669745977000,"mid":5721}}', 1669745977000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p6395-engl101', 'tg-idcistg', 'ENGL 101', 'info', '{"desc":"لا تفكر برأيك بالجواب\nارجع للمكان يلي تتوقع تلاقي فيه الجواب واقرأ \nلازم يكون كل بارت بالجملة تاع السؤال يتوافق مع النص\nاو الجملة تاع السؤال نقدر نستنتجها بشكل واضح من النص(هذه في حال ذكر ارقام واحصائيات)\n\nالفوكاب تاخذه لست تذاكرها ما بتقدر تجهزها من بكير لانو احتمال تتغير\nالريدنغ هو الريدنغ بورتفوليو يلي عندك تذاكر منه عشان seen اما ال unseen ما يمديك تضمنه بس يمديك تفتح كتاب التوفل تتمرن هناك\n\nوالله شوف\nفعلا شوي مصادرها قليلة لكن انا عن نفسي\nكنت اخذ عناوين القرامر ادخل اختبر اي كويز مع حلول(بفايلات الميد والفاينل بحطوا لكم روابط حلوين شوفوهم مع السلايدات)\nواشوف مستواي بالتوبك هذه لو كويس انتقل ل يلي بعده\nلو غلطت كثير اضل اتمرن اكثر وعادي اي موقع افهم منه اتمرن فيه\n…………..\nالفوكاب اكتفيت باللست حفظتها وحاولت اني اتدرب شوي عالروابط يلي عطونا ياها بس ما كان في وقت\n………..\nالريدنغ فهمت قطع البورتفوليو ورحت حرفيا حليت بالاحساس (:\n………..\nالرايتنغ \nاحاول افهم الستركشر واقلده ببعض الجمل او الطريقة\nمرات تصيب ومرات تخيب👍🏻\n\nThe main idea of the paragraph\nاطلع على اول واخر جملة بالبراجراف بعدين خذ نظرة سريعة على ما بينهما لكن غالبا الفكرة الرئيسية فيهم\nThe purpose of the paragraph\nغالبا اخر جملة فيه\nThe paragraph is mainly about\nاطلع على كل الجمل بسرعة الجواب لازم يكون يشملهم بشكل عام لا خاص كثير ولا برضو عام كثير (هنا يجي دور التوازن)\nWhat does the writer suggest\nغالبا غالبا بحط لك رأيه اخر النص باخر براجراف او اول النص باول البراجراف\nنااادرا ما يحط رأيه ضمن النص بالنص ومرات حتى ما بذكر رأيه بشكل مباشر انت بدك تستنتج من طريقة كلامه\n\nالخيارات قسمها ل ٣ اقسام\nخيار صحيح\nخيار خاطئ\nخيار لم يذكر\n…..\nيمكن اغلبنا بنخلط بين الخيار يلي لم يذكر  والصحيح\nلانه غالبا بجيبوه معلومة صح بس هو مو مذكور بالنص فحتى لو صحيح هو ستل ما انذكر بالتالي خيار خاطئ\n…….\nالخيارات عشان تحدد هي تابعة لاي فئة بدك تقسم كل خيار لاقسام\nبدك تتاكد كل قسم بالجملة وبالخيار يتوافق مع ما ذكر بالنص ضروري\nوبدك تنتبه لحروف الجر تلعب دور\nوبدك تحاول تفهم النص كويس عشان بعض الخيارات مبنية عالاستنتاج\nوأسئلة القراف جاوب عالسؤال اعتمادا عالقراف وفقرته فقققط\nعمرك بأي سؤال تجاوب عليه اعتمادا على فقرة ثانية\nلانه هما بحاولوا يوقعوك\nمثلا عندك نص مقسم لفقرات عن price-size\nيوم يسالك عن المقاس بترجع لفقرة المقاس غالبا\nلا تبني جوابك على معلومة ذكرت بفقرة السعر حتى لو انذكر بهديك الفقرة معلومة عن المقاس ستل يوم بدك تاخذ جواب على انه صحيح ١٠٠٪؜ خذه من فقرته هو فقط\n\nهو بس ارجع السكن من عيوني برسلك كل شي كتبته للستركشرز🙏🏻\nباقي الاشياء سهلة وبسيطة\nريدنغ:\nكنت افهم قطع البورتفوليو كويس وانتبه مع الدكتورة وقت تسوي لنا تمارين بالكلاس\nفوكاب:\nكنت احفظ اللست ومرات لما كان يكون عندي وقت كنت ارجع للتمارين يلي بحطوا رابطها ب bb +كنت افرق بين الكلمات المتشابهة عشان لو جابوها بالخيارات سوا\nقرامر:\nاكتفيت بسلايدات bb والروابط يلي بحطوها بفايل التعليمات بتاع الاختبار\n………..\nالريدنغ والرايتنغ بورتفوليو اخذتهم فيهم قريد لان صدق حليتهم باهتمام كبير\nالريدنغ كنت امسك كل قطعة افصفصها فصفصة واحط نوتات ورأيي على كل شي \nالرايتنغ كنت اول باول احط ال essays بتاعي فما ضغطني \nوكنت الفاينل درافت اشتغل عليها بتركيز واحاول قد ما اقدر اطورها واعطيها اي احد يديني فيدباك عشان طورها\n……….\nكنت اروح الاوفس اور كتير وهالشي أقنع الدكتور اني بجد مهتمة وحريصة (: وهي حبت هالشي\nاساسا اساسا لا اراديا بتحتاجي للاوفس اور بشكل اسبوعي\n\nنختبر اختبارات رايتنغ تست خلال ٥٠د مطلوب منك تكتبي ٤ برجرافات حسب نوع ال essay وبعدد كلمات معينة وعن توبك معينة انت ما تعرفيها غير وقت الاختبار\nعدا الفاينل معك ٧٥د تكتبي ٥ برجرافات\n\nهذا زي ملف\nحتحطي فيه ٤ essays \n٣ رئيسين و١ من اختيارك(مكرر من ال ٣)\nال ٣ رئيسين هما \nCompare and Contrast \nCause and Effect \nArgumentative \nكل essay له ٣ درافتات\nلازم درافت٢ تكون متطورة ومحسنة عن درافت ١\nودرافت ٣ لازم تكون أحسن من درافت ٢ \nيعني ضروري توري التطور\nوحتوريه اما عن طريق هايلايت-نوتات-كومنت بوكس -فيدباك من الدكتور/ة\nضروري يكون في عندك بالملف عالأقل ٢ فيدباك من الدكتور/ة على 2 different essays\nومسموح لك essay واحد بدون أي فيدباك ومسموح بحالات الضرورة إنك تدي نفسك فيدباك\nوعادي أي أحد يديك فيدباك ما دام ملتزم بمعايير انجلش ١٠١\n\nالفوكاب حيعطوكم لستات\nادرسوهم كويس وفرقوا بين الكلمات المتشابهة\nلستة للميد ولستة للفاينل\n\nالقرامر قبل الميد بفترة حيحطوا لكم فايل فيه توبكس القرامر وروابط تدرسوا منها\nبس موجود بالقروب لو حابين تبدأوا من بكير\n+قرامر الاختبار سهل بنحل بالاحساس والله\n\nتعاريف نسخ لصق\nاكمال جمل\nاو بجيبوا براقراف عن موضوع معين وفيه فراغات تحط فيها انسب كلمة\n\nالريدنغ من البورتفوليو \nوالفوكاب من اللستة\nوالرايتنغ تست وفاينل الرايتنغ من السلايدات ونصائح وفيدباك الدكتور\n\nاول درافت كنت اكتبها حرفيا بدون مراجعة بدون قراءة\nاكتب جمل جنب بعض\nابعد شوي عن ال essay شغلة ساعة \nارجع له اعدله\nويكون سهل التعديل لانه اولريدي احسو غبي كيف كتبت هيك!!😂\nبعد ما اعدل \nابعد ساعة او حتى يوم كامل عن ال درافت ٢\nثم ارجع اطالع فيها \nغالبا تجيني افكار افضل فاعدل\nبالمرة ما جاني شي اكتبه بدرافت ٣ كزيادة او تعديل\nارجع لدرافت ٢ واخربها😭😭\nعارفة طريقتي غبية بس جد ما كنت لاقي فيدباك وتعبني الموضوع \nبعد ما اخرب درافت ٢ اعدل عليها عشان ترجع حلوة زي اول واخليها درافت ٣\nطبعا لما آخذ من الدكتورة فيدباك هالشي كان يسهل علي كثيييير\nبس تقريبا 2essays ما خذيت عليهم فيدباك فياه هيك سويت فيهم\n\nطيب الرايتنغ كيف ندرسه؟\nحيعطوكم سلايدات من اول الترم لآخره وهما بشرحوا عليهم\nضروري ضروري تفهموا مع دكتوركم ايش هما نظامهم بالرايتنغ تمام؟ لأنه التست يلي بصححه هو دكتوركم فلازم تكتب زي الستركشر يلي بعجبه وتوريه إنك فاهم وسامع بالكلاس\n……..\nيلي كنت اسويه قبل البراكتس تست(ايام كنت اسويها قبل التست زاتو بالليل😭) افتح السلايدات تاع الessay يلي عنا تست فيه واصير اجهز لي قالب للكتابة\nمع مراعاة الستركشر يلي بالسلايدات والتنبيهات وتنبيهات الدكتورة\nبرضو كنت اطلع فوكاب اعتقد اني ححتاجه واكتب قائمة ب فوكاب ال essay يلي عنا يعني مثلا ce له كلمات خاصة فيه تميزه عن cc (حتعرفوهم بالكورس سهلين وحلوين وبرفعوا من قريدكم بخانة الفوكاب🙏🏻)\nوكنت اجهز جمل كثير عشان اقدر اركبها على اي فكرة\nحصورلكم الان قصدي\n……… \nيوم البراكتس تست فرصة ذهبية اغتنموها\nوانتوا بالبراكتس اي كلام حسيتوا انكم كررتوه اي مشكلة واجهتكم سجلوها عجنب عشان لما ترجعوا من الدوام قبل التست الفعلي تحلوا المشكلة\nكنت اسجل الكلمات يلي اكررها عشان اطلع فوكاب\nاكتب مشاكلي بالقرامر او وين علقت بالelaboration \n……….\nوقت التست الحقيقي اول ما تمسكوا الورقة اكتبوا القالب يلي جهزتوه بالوجه الخلفي للورقة\nبعدين اختاروا التوبك يلي تناسبكم وسووا خريطة مفاهيم بسيطة للفوكس بوينتس يلي حتحكوا عنها وضروري تكون دقيقة وواضحة\nوسعوا هذه الخريطة بحيث تحت كل فوكس بوينت تحطوا قالب البودي\nيعني اول شي التوبك بعدين اكزامبل بعدين امبليكيشن وهيك لحد ما تكتبوا حول ٦ جمل\nنفس الشي للفوكس الثانية\nحوريكم صورة برضو\nما ودي اكثر كلام زيادة لان الباقي حتعرفوه من دكاترتكم\nواعذروني عالخط يلي حتشوفوه كتبته وقت الزنقة😂🙏🏻\n\nصحيح المفروض قبل كل تست يرسلوا لكم زي guide فيه فوكاب وافكار رايتنغ رهيب رهيب بس تأكدوا انه كل شي فيه يتوافق مع كلام دكتوركم\n\nاول اسبوع طبيعي تحسي هيك بأي مادة\nبس ايش تسوي ؟\nحبة حبة مري عالسيلابس شوفي ايش وضع المادة؟\nبعدين مري عالبيسر يا حلوههه يخليك مطمنة وعارفة وين انت كل يوم وايش مطلوب منك بعد شهر جد جد لايف سيفر يفهمك ايش عليك الان وايش عليك بعدين وديدلاين كل شي\nوبعدين افتحي السلايدات يلي اخذتوها هالاسبوع وافهميها ولو حابة لخصي النقاط المهمة عدفتر صغير ولا ملف وورد لانه خلال الترم حتتراكم شوي ملاحظات الدكتورة\nوهي المادة خذيها بالكلاس انها سوالف و tips فسجلي كل التيبس يلي تقولها \nولما ترجعي افهمي السلايدات \nبعدييين قبل التست الاول بتعرفي ايش عليك\nجد لا تشيلي هم اي شي هلأ\nاللهم لو حابة ابدي ريدنغ في حال نزل البورتفوليو عندك ما نزل يا ستي خلص اعتبريها هدية♥️\n\nساعة لكل تكست...الفوكاب سهل بنلم بيوم ولا يومين بس خلينا نقول اسبوع عشان تمخمخوا عليه في حال مضغوطين بباقي المواد...القرامر حسب مستواكم وصدق صدق سهل أسهل من التوفل بكثييييييير...الرايتنغ خليكم منتبهين مع دكاترتكم بالكلاس وسجلوا نوتات ولما يفتحوا مجال للفيدباك اكتبوا essayوارسلوه وحطوه بعدين ب wp وقبل التست بيوم افتحوا سلايدات ال essay وشوفوا الستكشر ودنن\n\nصباح النووور✨\nيا جماعة\nاحنا صح حكينا الاوفس اور بالانجلش مفيدة وحلوة\nبس مش معناها اشوف ناس شايلين هم انهم ما يقدروا يروحوا ٤ ايام بالاسبوع!\nقلنا روحوا مرة بالشهر حلو\nبس مش كل ما زانت الجلسة رحتوا عند مكتب الدكتور/ة!\nلانه مافي فايدة للدرجة هذه\nالهدف من الاوفس اور بس تجاوب على أسئلتكم ولو عندكم أستفسار عالبورتفوليوز او كيف تذاكروا للتست بشكل عام..\nما توصل والله كل يوم.. لا ترهقوا نفسكم للدرجة هذه رجاء🙏🏻 ولا عليها درجات ترا\nمافي جائزة لاكثر واحد يروح الاوفس اور ولا هو معيار لل A+\nDeal?\n\nبعد ما تكتب حطها بقرامرلي وشوف ايش في أخطاء \nلا تزعل لو طلع عندك أغلاط كثيرة بالبداية كلنا حتى الدكاترة للآن مرات يغلطوا بالقرامر\nمهو احفظ وانسخ لا لا لا\nهو يجي بكثرة التدريب\n\nملاحظة: آخر مرة قرأت رواية او كتاب انجليزي كان صف ثاني متوسط بعدين توجهت لقراءة الكتب العلمية بالانجليزي\nيعني كتب الجامعة زي الكمستري والفزكس تراها حلللوة تعطيك حصيلة فوكاب وقرامر \"بطلين\"😂🤍\nيمكن صح ما تطور مهارات الريدنغ زي ما يبغوا هما باختبارات دولية بس انا اعتمدتها ٣ سنين واقدر اقول مستواي فرق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/6395","user":"idcistg","ts":1670354411000,"mid":6395,"mids":[6395,7155,7192,13098,13099,16271,16694,20555,21151,21152,22239,22480,22729,23012,23022,23419,25346,27078,52900,52903]}}', 1670354411000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p8964-engl101', 'tg-deeemzzz', 'ENGL 101', 'info', '{"desc":"يعني الحين مثلا موضوعك كان انه يسمحون للجوالات في المدارس وانت مع هذي الفكرة\nفي الكاونتر تقول انه يمكن فيه ناس يقولون ان الجوالات تسبب distraction او شي\nبعدين تقول انه صح عليهم بس كذا كذا كذا تزيد كلام يعني ضد فكرتهم ذي","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/8964","user":"deeemzzz","ts":1671635573000,"mid":8964}}', 1671635573000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p9836-engl101', 'tg-engx1', 'ENGL 101', 'info', '{"desc":"سهله للي فاهم الرايتنق من اول ولكن هالشيء م يضمن لك تاخذ درجات عاليه، لان عندهم آلية ان الدرجات محدوده\nونادرا تحصل احد ياخذ فيها توتل قريد A\n\nانتبه لتعليمات دكتورك + روح الاوفس اووز واجد شوي + اكتب كل اسبوع واحد essay عن الموضوع اللي يجي ف التاسك الفلاني","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/9836","user":"engx1","ts":1671783067000,"mid":9836,"mids":[9836,17324]}}', 1671783067000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p38307-engl101', 'tg-spacloud', 'ENGL 101', 'info', '{"desc":"ليت أقدر أقول طريقتي بس سمعت كثير يقولون قراءة ترا قصص الأطفال عن تجربة تفيد جدااااااا اكتشف كلمات بحياتي ما شفتها + قناة كوكوميلون والله حلوة 😭😭","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/38307","user":"spacloud","ts":1678563006000,"mid":38307}}', 1678563006000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p39475-engl101', 'tg-jeff3028', 'ENGL 101', 'info', '{"desc":"focus on the basic parts: grammar and vocabulary. build these by communicating with others in English","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/39475","user":"jeff3028","ts":1679423878000,"mid":39475}}', 1679423878000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p45117-engl101', 'tg-xxxxxxsiveintitres', 'ENGL 101', 'info', '{"desc":"الدرافت الاولى (الاورجنال على قولتك) \nالدرافت الثاني \nبيير فيدباك \nالدرافت الثالث\nفيد باك من التيتشر \nالدرافت الرابع(الفاينل)","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/45117","user":"xxxxxxSiveintitres","ts":1681273306000,"mid":45117}}', 1681273306000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p50331-engl101', 'tg-u644262619', 'ENGL 101', 'info', '{"desc":"الاختبار من ثلاثين \n١٥ على الكتابة \n١٥ على الاختبار \n-٣٠٪؜ الريدنق يساوي ٤.٥\n-٣٥٪؜ الفوكابلري يساوي ٥.٢٥\n-٣٥٪؜ جرامر يساوي ٥.٢٥\nوإذا فيه خطأ صححوا لي","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/50331","user":"","ts":1684524537000,"mid":50331}}', 1684524537000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p51741-engl101', 'tg-lrvmvr', 'ENGL 101', 'info', '{"desc":"بتعرفهم اول كلاس بتنشرح لك\n\nبس هو اسايمنت ريدنق قطع وعليها اسئلة\nو الرايتنق تكتب درافتات","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/51741","user":"Lrvmvr","ts":1684938870000,"mid":51741}}', 1684938870000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p53143-engl101', 'tg-ear8700', 'ENGL 101', 'info', '{"desc":"وصح نصيحة عامة الروحة عند الدكتور المكتب شي مهم عند اغلب الدكاترة ويبين لهم انك طالب مهتم فضلًا عن انك بتتجنب الاشياء الي تزعجهم في الكتابة وهذا الشي بيرفعك قريد على الاقل \n\nلذلك لاتتهاون في الاوفس اور في المادة ،فايدتها اعظم من غيرها من المواد وشكرًا 🌹","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53143","user":"EAR8700","ts":1686091132000,"mid":53143}}', 1686091132000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p53469-engl101', 'tg-fa_55555', 'ENGL 101', 'info', '{"desc":"مادة انقلش ١٠١ اعتقد ٦٠٪؜ رايتنق \nرايتنق ١ و ٢ و٣ كل واحد ١٥ \nورايتنق الفاينل ١٥ \n\nوعندك الريدنق فيه كتابه ملفين هذي ٥ \nوعندك الرايتنق برتفليو عليه ٥ \n\nتقريبا كل الماده رايتنق ف مهمه بتاثر على قريدق النهائي \n\nوعليها ٣ كريدت ( من رايي سوو الي عليك لان عندك غيير مواد الانقلش ١١٩ كريدت ، ماث فزكس مواد تخصص )","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53469","user":"Fa_55555","ts":1686939863000,"mid":53469}}', 1686939863000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p54602-engl101', 'tg-u857916727', 'ENGL 101', 'info', '{"desc":"المادة ميد مو ميجر \nالميد ريدنق وقرامر وفوكاب \nالفاينل يتكون من قسمين، قسم نفس الميد والقسم الثاني رايتنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/54602","user":"","ts":1692432265000,"mid":54602}}', 1692432265000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p58860-engl101', 'tg-hiolau', 'ENGL 101', 'info', '{"desc":"شيء تشتغل عليه طوال السمستر \nمثلا الرايتنق  بروتفو\nالدكتور راح يعطيكم تكتبوا \nويقولك خذ فيدباك من صاحبك \n\nوترجع البيت تعدل الي قاله صاحبك \nبعدين الدكتور يعطيك فيدباك\nوترجع البيت تسويه \nوهكذا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/58860","user":"HiolaU","ts":1693716290000,"mid":58860}}', 1693716290000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p66627-engl101', 'tg-hw1405', 'ENGL 101', 'info', '{"desc":"حسب كلام اكثر من واحد خلص المادة يقولون اصعب شي بكل المادة هو الwriting task(اختبار الكتابة) عشان كذا استغل الميد والفاينل عشان ترفع درجتك","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/66627","user":"HW1405","ts":1696318849000,"mid":66627}}', 1696318849000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p66980-engl101', 'tg-u1497484979', 'ENGL 101', 'info', '{"desc":"اذا انت مرا مضغوط و موقادر تستوعب احفظ هيكل حق نوع الرايتنق الي تبغاه و انسخه و عدل عليه اكثر من مره و راح تتحسن باذن الله","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/66980","user":"","ts":1696500097000,"mid":66980}}', 1696500097000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p66984-engl101', 'tg-iiiee61', 'ENGL 101', 'info', '{"desc":"اقرا الامثله الي مكتوبه واستفيد من الفوكاب وطريقة كتابتهم \nوتدرب على لستة التوبيكات الموجوده ع امثله مشابهه \nمثلا اجهزه ، صحه ، سفر يعني لو تدربت ع موضوع واحد فيهم بتستفيد لو جاك مشابهه\n\nلو قلت كذا فعلا مارح تجيب قريد \nروح على كل خانه بالقريدات واقرا المتطلبات هل انت منجد سويت زي الي يبون ؟ اذا لا حسن من نفسك فيها للرايتينق الثاني وبتجيب درجه باذن الله كويسه ، وافضل طريقه انك كل مره تكتب كثير وتروح للدكتور الاوفس الاور توريه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/66984","user":"iiiee61","ts":1696504609000,"mid":66984,"mids":[66984,84556]}}', 1696504609000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p68492-engl101', 'tg-ali4_44', 'ENGL 101', 'info', '{"desc":"المهم لو حسيت نفسك بايعها في كل الرايتنق \nتذكر عندك ميد وفاينل سهالات شد فيهم وتنجح","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/68492","user":"Ali4_44","ts":1696925815000,"mid":68492}}', 1696925815000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p69457-engl101', 'tg-bestofem25', 'ENGL 101', 'info', '{"desc":"A multiple-choice examination based on 2 TOEFL-like readings followed by questions relating to the vocabulary contained in the Academic Word Lists 1-3 and common grammatical errors associated with academic English.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/69457","user":"Bestofem25","ts":1697066997000,"mid":69457}}', 1697066997000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p69788-engl101', 'tg-mmmanarrr', 'ENGL 101', 'info', '{"desc":"احس الڤوكاب والريدينق السين هم المضمونين ذاكريهم اول بعدين القرامر تدربي على سامبل ميد تيرم اقزام وحطي لك وقت وشوفي اللي انتي ضعيفة فيه وراجعيه مع شرح ، بعدين حلي القرين فايلز للڤوكاب والقرامر","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/69788","user":"mmmanarrr","ts":1697134999000,"mid":69788}}', 1697134999000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p76461-engl101', 'tg-miivs', 'ENGL 101', 'info', '{"desc":"من ١٠٠ نقطة\n٤٠ للريدنق كل سؤال نقطتين ( تأثير اكبر )\n٦٠ للفوكاب والقرامر كل سؤال فيهم نقطة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/76461","user":"Miivs","ts":1697477026000,"mid":76461}}', 1697477026000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p78859-engl101', 'tg-ra_934', 'ENGL 101', 'info', '{"desc":"A+: 93–100% B+: 85–89%\nA: 90–92% B: 80–84%\n C+: 75 –79% D+: 65–69%\nC: 70–74% D: 60–64%\nF: 0–59%\nحق الميد☝️","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/78859","user":"ra_934","ts":1697642260000,"mid":78859}}', 1697642260000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p80558-engl101', 'tg-u846435662', 'ENGL 101', 'info', '{"desc":"انا اشوف اللي يبي درجة قوية فالكتابة\nاهم شي التنوع (بدون اخطاء)\n\nلاتسوي نفس القرامر والفوكاب الفين مره وتقول الدكتور عطاني c\nيخوي زين عطاك اياها😭. \nانا ما اقول ان جامعتنا مافيها شوي شدة ف القريدات\nلا صدق فيها شدة و بقوة\nلكن احيانا السبب الطالب مو المصحح\n\nشباب ترى لا حد يتسرع ويحذف الكورس من بدري ولله العظيم عندي واحد من اصحابي المقربين مرههه\nكان جايب c ف واحد من الرايتنقز وبعدين نهاية الكورس B+ \nترى عادي ولله بس شدو ع نفسكم♥️.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/80558","user":"","ts":1697651812000,"mid":80558,"mids":[80558,82348]}}', 1697651812000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p83581-engl101', 'tg-sasaa80', 'ENGL 101', 'info', '{"desc":"لا بس الباقي سهالات انشاءالله المد نفس الاوريا قرامر وفوكاب وريدنق بس الفرق انه سلف ستدي محد بيجي ويشرح لك زي الاوريا، الرايتنق عليه جزء كبير من الدرجات","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/83581","user":"Sasaa80","ts":1697733978000,"mid":83581}}', 1697733978000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p86929-engl101', 'tg-u825588525', 'ENGL 101', 'info', '{"desc":"بشرح عالسريع للي ضايع:\nأول ما نستلم ورقة الاختبار نقرأ المواضيع كويس بعدها نسوي عصف ذهني نتذكر إن المقال أختار شيء ما بين الكوز والايفيكت يعني ممنوع نكتب الاثنين طيب كيف أعرف وش اختار بعد العصف الذهني للأفكار الي طلعت معكم شوفوا وش الشيء الي تقدرون تكتبون عليه بأريحية وتبدعون فيه. \nعلى سبيل المثال الكوزس عند شخص طلعت ممتازة ويقدر يكتب عليها خلاص يصير الايسي حقه كوزس شخص آخر صار الايفكتس عنده أحسن فيكتب عن الايفكتس وهكذا.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/86929","user":"","ts":1699451405000,"mid":86929}}', 1699451405000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p87914-engl101', 'tg-xnor_912', 'ENGL 101', 'info', '{"desc":"نصيحة للي لسه ما بدأو بالريدينج بورتفوليو يبدون لان ذا اطول واحد و مليان اسئله مقالي","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/87914","user":"xnor_912","ts":1699633204000,"mid":87914}}', 1699633204000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p90737-engl101', 'tg-m0h2mmd', 'ENGL 101', 'info', '{"desc":"هو صدق الي اجتهد وضل اسبوعين ثلاث او حتى اربع يجهز لرايتنج يحق له  يطمح اما الشباب يقولوا زينه يحسبون انكك خاش الاختبار على الله او مركز على ماده ثانية \nالدرجه الكويسة تعتمد على انت وش عطيت عشان تشوف \nاما تشق نفسك واخرتها D ولا c اي مو كويسة ونص بعد","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/90737","user":"M0h2mmd","ts":1700158602000,"mid":90737}}', 1700158602000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p91076-engl101', 'tg-dreeaaamer', 'ENGL 101', 'info', '{"desc":"امسكي سلايدات القسم قدامك لكل جزء من ال essay وشوفي الصيغ المختلفه اقراي كل براقراف خمسين مليون مره لين تعرفين وش التسلسل اللي المفروض تتبعينه وتعرفين ترتبين افكارك وتنتقلين بمنطقيه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/91076","user":"Dreeaaamer","ts":1700170754000,"mid":91076}}', 1700170754000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p91122-engl101', 'tg-moshimoshixxxx', 'ENGL 101', 'info', '{"desc":"انتبهت على كل شئ يقوله الدكتور\nوركزت على كيف اطلع الاسباب والاثار\nوتدربت على التخطيط \nوسويت تامبلت وكتبت عليها و وريتها دكتوري قبل الاختبار\nوحاولت اطور فوكابي لنوع الرايتنق حقنا\nوتوكلت على ربنا👍","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/91122","user":"moshimoshixxxx","ts":1700196523000,"mid":91122}}', 1700196523000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p91165-engl101', 'tg-zz_np', 'ENGL 101', 'info', '{"desc":"احس اكثر شي افادني اني قريت نص سامبل بالسلايدات وشفت الستركشر حقه وكيف يربط الجمل مع بعض، عاد الفوكاب عندي كويس، وبرضو الموضوع الي جاني كنت فاهم فيه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/91165","user":"Zz_np","ts":1700221368000,"mid":91165}}', 1700221368000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p91186-engl101', 'tg-mohammadxx9771', 'ENGL 101', 'info', '{"desc":"انا اعرف اكتب بالعربي الفصحة ، فلما اجي بكتب بالانجلش اقعد اترجم اللي بقوله من العربي الفصحة الى الانجليزي ، وفي غالب الاحيان تزبط \n\nالصراحة اني انا كنت اتدرب من ايام الاوريا كنت اكتب كثير ، دخلت من 01 وكان عندي 8 اختبارات رايتنق كل لفل وكل واحد تدربت عليه كثير \n\nوكذلك ابحث عن فوكاب عالي واحاول استخدمه\n\nف انجلش الاوريا سواء قرامر او فوكاب جاب اثره الحين","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/91186","user":"Mohammadxx9771","ts":1700226787000,"mid":91186}}', 1700226787000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p96858-engl101', 'tg-omar_coe', 'ENGL 101', 'info', '{"desc":"حسب سياق الجملة ممكن لها ترجمات مختلفة، هم ما يبون الكلمات ذي لأنها عامة وتقدر ترميها مع أي شي، يبون كلمات دقيقة توصف المعنى \n\nيعني بدل لا تقول \nBad food\nتقدر تقول \nWasn\u0027t delicious \nThe food was overcooked / salty\nExpensive compared to the small portion they gave\n\nالفوكاب اقرا اللست أكثر من مره وحل الكويزات اللي بيعطيك اياها القسم أكثر من مرة لين ترسخ، القرامر كنت أحل مباشرة الكويزات وأراجع اللي أغلط فيه بس","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/96858","user":"OMAR_COE","ts":1702400673000,"mid":96858,"mids":[96858,113447]}}', 1702400673000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p97093-engl101', 'tg-sosoal0', 'ENGL 101', 'info', '{"desc":"درافت ون هو الاساس اول شيء سويتيه\nدرافت تو هو الي تعدلين عليه سواءً بنفسك او بالبير فيد باك\nدرافت ثري الي عدل عليه دكتورك\nدرافت فور الشكل النهائي للأساي، التعديل النهائي ومع اضافة الباراقرافات الي ماكتبتيها قبل\n\nالدرافت الاول تكتبه بالكلاس، بعدين درافت ٢ راح تاخذ فيدباك من اي أحد معاك بالكلاس وبناءً عليه تعدل اغلاطك الي بدرافت 1، وآخر شيء درافت ٣ راح يجيك فيدباك من الدكتور نفسه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/97093","user":"sosoal0","ts":1702460969000,"mid":97093,"mids":[97093,154428]}}', 1702460969000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p98907-engl101', 'tg-mnmyui', 'ENGL 101', 'info', '{"desc":"تدرب اولًا عالرايتنق \nالفوكاب احفظه\nالقرامر راجعه من السلايدات وشوف الي مطلوب منك \nالفوكاب احفظه زييين\nالريدنق لا عرفت علمني","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/98907","user":"mnmyui","ts":1702657740000,"mid":98907}}', 1702657740000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p103463-engl101', 'tg-ararbody17', 'ENGL 101', 'info', '{"desc":"في اللي ممكن يذاكر السلايدات والستركتشر ويكتب ويتدرب وبالنهاية ياخذ قريد سيء وفيه اللي يقرأ الستركتشر ويروح يكتب هناك ويجيب قريد عالي \nفهي كلها توفيق من رب العالمين وعلى حسب انت بدعت بالكتابة ولا لا وغير كذا الدكتور بعد \nفسوو اللي عليكم والباقي على رب العالمين\nأهم شيء حتى لو لا سمح الله كتابتك سيئة حاول تمشي عالستركتشر ولا تنسى شيء هم طالبينه على أساس ما يمسكون عليك شيء \nموفقيييين جميعا الله يفكم من هالكورس :)\n\nفي النهاية بتمشين على الستركتشر اللي يعطيك الدكتور/ة ونصيحتي تسوين تيمبليت او سكيليتون قبل الاختبار","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/103463","user":"ararbody17","ts":1702878804000,"mid":103463,"mids":[103463,114577]}}', 1702878804000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p111547-engl101', 'tg-anoymous55', 'ENGL 101', 'info', '{"desc":"تمشي عالستركتشر المحدد لكل اساي + تركز على على ال response to question + تكتب وتتدرب كثيييير وتروح توري دكتورك اللي كتبته وتاخذ فيدباك وتبين له انك مهتم + تدور اكبر قدر من المواضيع وتسوي عصف ذهني للافكار الرئيسيه اللي ممكن تكتب عنها\n\nB وطالع ان شاء الله يمديك\n\nالريدنق بورتفوليو \nمطلوب منك ٤ بالترم كل واحد فيه قطعتين وعليها اسئلة، مطلوب منك تسوي هايلايتنق وتكتب نوتات عليها وتحل الاسئله\n\nالرايتنق بورتفوليو\nالرايتنقز اللي تنطلب منك تكتبه خلال الترم نهاية السمستر بتجمعهم ب وورد واحد وتسلمهم للدكتور (اكثر من درافت لكل رايتنق حسب دكتورك)\n\nالريدنق بورتفوليو\nملف يكون عندك 2texts كان مطلوب مننا نقرا ونسوي هايلايتنق ونكتب نوتس عليها بعدين نجاوب الاسئله بطريقه كأنك تكتب رايتنق وفوكاب كويس وقرامر صحيح وكل ما كان المربع اكبر كل ما كنت مطالب تكتب اكثر\nبالميد كانت تجي قطعه مشابهه لوحده من قطع الريدنق بورتفوليو والفاينل كذلك\n\nالرايتنق بورتفوليو\nملف وورد تجمع فيه الاسايز اللي مطلوبه منك خلال الترم وكل اساي له عدة درافتس حسب دكتورك والدرافتس تشمل ( الاساي الاصلي، درافت فيه فيدباك من زميلك، درافت فيدباك من الدكتور، فاينل درافت) ، والهدف منه يظهر تطورك خلال الترم بالرايتنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/111547","user":"anoymous55","ts":1704076555000,"mid":111547,"mids":[111547,114627,117984]}}', 1704076555000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p115746-engl101', 'tg-im_the_neon', 'ENGL 101', 'info', '{"desc":"حصه يوم الاربعا يحضرون فيها ناس معينين حسب جدول يرسل بيوم الاربعا \nاللي يسوونه باللاب كان حسب الدكتور \nبعضهم كانت كتابة بالانجلش على الكيبورد بعضهم سبيكنق بعضهم كان يفتحون نقاش بموضوع وهكذا\n\nReading portfolio \nماعليه درجات ولا يدخل بالابقريد ولا يوجد اي ضرر من ناحية الدرجات في عدم حله \nولكن القطع الموجودة فيه وحده منها بتجي بالميد تيرم (text (1-4 ووحدة منها بالفاينل text (5-8)\nورح يصحح من الدكتور ويعطيك عليه فيد باك \nلذلك فهمك لطريقة القراءة الصحيحه وتطبيقها مرتبط بحلك له \nليه ماصار عليه درجات؟ \nلانه الطلاب كانوا يرسلون حل مو لهم وحلول من تشات جي بي تي \nفالان صار ماعليه درجات علشان الدكتور يتفرغ للطلاب اللي يبون يحلونه منجد وياخذون فيد باك ويستفيدون منه\n\nعموما يجماعه لا تشغلون نفسكم الحين باللي فات \nفي ناس بالكورس هذا جابت بالبداية C وطلعت بA ماشاء الله \nركزوا على الجاي وافهموا طريفة دكاترتكم ووش يبون بالضبط وانشبوا لهم بالاوفيس اورز وبينوا لهم انكم مهتمين \nوباذن الله تطلعون بدرجة ترضيكم\n\nدكتورنا قال نخلص الغرامر والفوكاب سريع ونعطي باقي الوقت وكامل تركيزنا للريدينق \nلانه لو بديت فيه ممكن تطول ويروح الوقت على الفوكاب والغرامر\n\nذاكرت السلايدات وراجعت فيد باك الدكتور قبل مااكتب كل واجب علشان اتحسن \nوكنت اسمع الدكتور وش يقول بالمحاضرة هو يحب والامثلة اللي يضربها بالكلاس تحدد لك هو وش يركز عليه بالضبط بالتصحيح \nوبرضو تفاعلك مع الدكتور يعطيه ايحاء انك مهتم وهذا كلام دكتورنا بنفسه وبرضو بنفس الوقت تفاعلك واسئلتك تخليك تتذكر اللي اخذته بالكلاس \nحاجه ثانية بديت اسويها بهذا التاسك اني اخذت نوتات لكلام الدكتور علشان اذاكرها قبل مااكتب الواجب وقبل الرايتينق تيسيت\n\nلو رفع الطالب طلب اعادة تصحيح ومعاه اثبات لدكتوره انه يستحق درجة اعلى \n+الكورد يراجع لكل الدكاترة بعد التصحيح علشان مايصير في ظلم ويكونوا الكل يصححوا بنفس الشده \nواذا السكشن درجاتهم عالية مو شرط ينزلهم \nسكشنا درجاتنا عالية وراجع وشاف دكتورنا مصحح حسب الروبريك وماغير ولا حاجه بالدرجات \nلو كان في دكتور معطي درجات عالية سبهللة لسكشنه وقتها اوكيه هذا اللي ينزل الدرجات بالتصحيح الكورد\n\nتلخيص للثيسيز\nتلخيص للبودي بارغراف \nجملة اغلاقية تكون تصريح قوي او افتراض للمستقبل او تبين ماذا سيحصل لو اتخذت اجراءات معينه \nراجعي سلايدات القسم\n\nبالعكس \nيضيع وقت ولا يضيع درجات \nانت خلص الغرامر والفوكاب اول بعدين روح للريدنق وركز فيه \nوبعد ما تخلص الريدنق راجع الغرامر والفوكاب \nكذا بتكون فصفته\n\nاخذ ثلاث فيد باك من دكتورك على الاقل بالاوفيس اور قبل اختبار وتركيزك وتفاعلك معاه كفيل ان شاء الله تجيب قريد كويس بالماده\n\nالرايتينق على حسب دكتورك \nافهم طريقته وهو وش يبي وقبل كل اختبار خذ فيد باك على ثلاثة ايساي على الاقل \nروح له الاوفيس اور ولا تهمل هالشي ابدا لانه بيفرق معاك\n\nReading portfolio \nماعليه درجات ولا يدخل بالابقريد ولا يوجد اي ضرر من ناحية الدرجات في عدم حله \nولكن القطع الموجودة فيه وحده منها بتجي بالميد تيرم (text (1-4 ووحدة منها بالفاينل text (5-8)\nورح يصحح من الدكتور ويعطيك عليه فيد باك \nلذلك فهمك لطريقة القراءة الصحيحه وتطبيقها مرتبط بحلك له \nليه ماصار عليه درجات؟ \nلانه الطلاب كانوا يرسلون حل مو لهم وحلول من تشات جي بي تي \nفالان صار ماعليه درجات علشان الدكتور يتفرغ للطلاب اللي يبون يحلونه منجد وياخذون فيد باك ويستفيدون منه ㅤ\n\nنصيحه مهمه للريدينق:\nhttps://t.me/KFUPM_ENG101/145031\n\nبعد ما تخلص السلايدات حقت القسم او الروابط اللي راسلينها بالفورمز راجع الملخص الموجود هنا بعدين افتح تدريبات عليه الموجوده بالبلاك بورد وحل وسجل اخطاءك وليش غلطت فيها\n\nالمده اقل \nمايحتاج منك متابعه بقدر انجلش الاوريا \nمافي منهج تمشين عليه، الاعتماد الاكبر في التدريب وانك تروحين دكتورك الاوفيس اور، فهنا تقريبا كل الشغل عليك \nاهم شي فيه واكبر مقدار من الدرجات على الريدنق والرايتينق، وهم اللي بكملون معك ل١٠٢","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/115746","user":"im_the_neon","ts":1705020252000,"mid":115746,"mids":[115746,120174,128249,130462,131073,131394,131974,137768,140732,143309,145050,188927,250755]}}', 1705020252000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p117221-engl101', 'tg-axizl', 'ENGL 101', 'info', '{"desc":"٥ بالمية ريدنق بورتفوليو و٥ بالمية رايتنق بورتفوليو كلها راحت للفاينل\n\nصار ٤٥ بالمية","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/117221","user":"axIzl","ts":1705230683000,"mid":117221}}', 1705230683000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p118813-engl101', 'tg-fa74ll', 'ENGL 101', 'info', '{"desc":"حنا الدكتور قال لنا مثلا موضوع \nReducing air pollution \n\nالمقدمة :\n-تعطي background \nوتتكلم بشكل عام عن المشكلة \n-وب اخر جملة تذكر حلين للمشكلة \n\nالbody paragraph 1 : \nتتكلم بالتفصيل عن الحل الاول \n\nو الbody paragraph 2 : \nتفصيل الحل الثاني\n\nالمقدمة :\n-خلفية خارج الموضوع \n-ربطها بالموضوع\n-سبب المقارنه \n-الفئة المستهدفة \n-الthesis \n\nالخاتمة :\n-اعادة صياغة الthesis بطريقة مختلفة \n-ملخص \n-اقتراح الأفضل للفئة المستهدفة\n\nوعليكم السلام والرحمه \n\nافهم دكتورك وايش الاشياء اللي يركز عليها ويكررها والاشياء اللي ينبهكم عليها ويحذر منها هالشي جدًا بيساعدك بالرايتنق واحضر الاوفس اورز للدكتور ووريه كتاباتك وخذ ملاحظاته ،هالشي فادني كثير و شفت نتايجه بقريدات الرايتنق الحمدلله .\n\nالقرامر لاتستهين فيه وتسلك له وحاول تفهمه وتفرق بينهم ( فيه ملخصات وشروحات تفيدك )\n\nالفوكاب : حاول تضمنه خصوصا بقسم التعاريف مايحرّفون فيها ف احفظها زين وحاول تستخدمها بالرايتنق بترفع درجتك \n\nالريدنق : لاحول ولا قوة الا بالله😭😭\n\nايوه ، الريدنق هو اللي شوي يحتاج لذلك حاولوا تخلون له الوقت الاكثر .\nحاولوا تضمنون الفوكاب لان التعاريف تجي نفسها نسخ لصق ف مايحتاج بالاختبار تضيعون وقت عليها ماتاخذ 5 دقايق، افهموا وفرقوا بمعانيها عشان تعرفون تحلون  الامثلة اللي تختارون الكلمه المناسبة.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/118813","user":"FA74ll","ts":1706261288000,"mid":118813,"mids":[118813,121785,143277,161021]}}', 1706261288000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p119048-engl101', 'tg-mono571', 'ENGL 101', 'info', '{"desc":"الكورس مخربط اصلا مافي اشياء محددة تذاكريها المفروض تذاكري كل شي بس الفوكاب عطونا لسته محددة اما القرامر تذاكري كل شي والريدينق تذاكري الريدينق بورتفوليو لان يجي منه قطعه والقطعة الثانية خارجية\n\nالاختبارات في هذا الكورس ما يعطوك بضبط كم جبت في الاختبار يعني مثلًا الميد بعد ما تطلع النتايج ما بتطلع لك الدرجة حقت الاختبار بيطلع لك قريد c, b وكذا وحتى الرايتنق نفس الشي","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/119048","user":"Mono571","ts":1706503698000,"mid":119048,"mids":[119048,120002]}}', 1706503698000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p121675-engl101', 'tg-ra9_55', 'ENGL 101', 'info', '{"desc":"يعني مثلا موضوع يتكلم عن الكاش والبطاقة الائتمانيه، جيب كلمات زي transactions او Financial data الخ ونفس الشي مع باقي المواضيع عشان ما تنشب مع الفوكاب وقت التيست\n\nطريقتي ان شفت الملخص حق القرامر كامل بدون ما اشوف السلايدات لاني احسها مضيعة وقت وبعدها تدرب كثيير من Resources عشان تشوف اغلاط ونقاط ضعفك وتركز عليها بالذات\n\nاذا بتبدين بباست ايفينت قولي بعدها however واوصفي الوضع الحالي ووش تغير، بعدها توضحين قد ايش الموضوع مهم ولمين واستخدمي كلمات زي serious, seriously وبعدها توضحين وش ممكن يصير اذا انحل الموضوع او مدى صعوبة حله وبعدين الثيسس\n\nلما تكتبين عن الكوز مثلا وتبدين تتكلمين عن الافيكت\nلما تجيبين اكزامبل وتفصلين فيه بعدها\nطبعا لما كلامك في البودي ما يكون له صله او علاقه بالتوبيك الي في البدايه\n\nالريدنق يفضل تتدرب على الريدنق برتفوليو. تحاول تحلل النص وهايلايت على الكلمات الجديده وهايلايت على الافكار الرئيسية وتحاول تجاوب على الاسئلة وتطلعها من التيكست الخ\n\nهو اصلا مافي شي يتذاكر له اهم شي تراجع الستركتشر وتتعلم كلمات جديده وتتدرب (نصيحه لا تكتب ايسيات واجد لانها ما ما بتفيد او ممكن حتى تضر لانها تغير في اسلوبك فا سوي ايسي او اثنين ويكفي ان شاء الله)\n\nوفيه حركة حلوه انك تمر على التوبيكس كلها وتسوي لها برين سترومنق وتطلع لها افكار وشوف بعد ايش اكثر بارقراف انت ضعيف فيه وحاول تتدرب فيه بالذات","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/121675","user":"RA9_55","ts":1708800759000,"mid":121675,"mids":[121675,131045,132154,132277,134548,138091]}}', 1708800759000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p122863-engl101', 'tg-ilio_0ili', 'ENGL 101', 'info', '{"desc":"غالبا بيعطيكم الايام الجية عن الميد لكن كبداية ممكن تعدي على قائمة الكلمات وتتأكد انك عارف كل معاني الكلمات فيها وايضا قطع الريدينق بروتفوليو اتأكد انك فاهمها كلها","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/122863","user":"IlIo_0IlI","ts":1708889768000,"mid":122863}}', 1708889768000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p124135-engl101', 'tg-lyi_13', 'ENGL 101', 'info', '{"desc":"تدرب ع التست الي ينزلها لكم الدكتور وشوف الاولد ميد جرب تحل الريدنق حقتهم واذا تبي تمر ع البورتفوليو مر","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/124135","user":"lyi_13","ts":1709301944000,"mid":124135}}', 1709301944000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p124912-engl101', 'tg-s8ali8', 'ENGL 101', 'info', '{"desc":"حلي البورتفوليوز التكسرات الاربعه في واحد سين بيجي منها واذا دكتورك منزل براكتس سويه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/124912","user":"s8ali8","ts":1709377735000,"mid":124912}}', 1709377735000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p127338-engl101', 'tg-odyss_us', 'ENGL 101', 'info', '{"desc":"المعروف في ذي المادة انه من المواد الي تحاول تخلصها باقدر كم من الخسارات عشان شبه مستحيل تجيب درجة كاملة في اي رايتنج تاسك، لذلك خلي هدفك A+ ولكن لا تتفاجأ إذا جبت اقل مثل A او B بس إذا شفت نفسك بتجيب C او اقل بالمادة دردبها","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/127338","user":"Odyss_us","ts":1709538223000,"mid":127338}}', 1709538223000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p128612-engl101', 'tg-ll2_8l', 'ENGL 101', 'info', '{"desc":"شوفي انا احس افضل شيء واللي اسويه بالاوريا\nاعطي نص ساعة للقرامر والفوكاب\nو ٥٥ دقيقة للريدينق\n٥ دقايق اراجع القرامر والفوكاب","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/128612","user":"ll2_8l","ts":1709635423000,"mid":128612}}', 1709635423000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
