INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p131135-engl101', 'tg-rai2v', 'ENGL 101', 'info', '{"desc":"التدرييب\nكل المواضيع اللي بالسلايدات ابحث عن كويزات واكسرسايز لها بقوقل ويطلع اكثر من موقع واحل واشوف اغلاطي وافهم ليش هي غلط\n\nحسب اللي فهمته من دكتوري الشيء اللي المفروض يكون ممتاز هو السببين نفسهم، يعني لو كانوا مقنعين هذا يكفي\nصياغه الthesis تكون نفس اللي بالسلايدات، مثلا\nIn order to ...... and ........ , Kfupm should ............... .\n\nكل شيء يصير مقدور عليه مع التدريب حتى الريدنق، الموضوع بس يحتاج انك تطور قراءتك بمصادر غير الدراسه ولما نجي للدراسه لاتهمل البورتفوليو حتى لو ماعليه نسبه لأنه يعطيك فكره ويفيد مره","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/131135","user":"Rai2v","ts":1709815434000,"mid":131135,"mids":[131135,138672,143374]}}', 1709815434000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p131455-engl101', 'tg-wqwqpool', 'ENGL 101', 'info', '{"desc":"تأكد من دكتورك بس الخصم يجي مع الغياب الخامس يعني لو غبت اربعة و تأخرت مرتين بيبدأ الخصم","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/131455","user":"wqwqpool","ts":1710195998000,"mid":131455}}', 1710195998000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
