INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p133037-engl101', 'tg-looolo_olovol', 'ENGL 101', 'info', '{"desc":"انترودكشن : اعطي باك قراوند للموضوع وبعدين اربطها بالتوبك \nفالنهايه الثيسس لازم تختار تتكلم عن 2effects او 2causes ماتقدر تتكلم عنهم كلهم مع بعض \nBody1: تكلم عن الeffect  او الcause  اللي اخترتيه اول شي توبك سينتينس بعدها explanation فصل بال effect  او cause بس بالنهايه اربطه بالتوبك الاساسي واذا تبغا تعطي مثال لاتفصل بزياده \nBody2: نفس الشي \nConclusion : سو ريفريز للthesis وبعدين لخط البودي باراقرافس ب جملتين وبعدها اقتراح","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/133037","user":"lOoOlO_OlOvOl","ts":1710835879000,"mid":133037}}', 1710835879000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p134466-engl101', 'tg-i4kcm', 'ENGL 101', 'info', '{"desc":"عن نفسي ذاكرت السلايدات وفهمت القواعد زين و وحليت الكويزات اللي موجودة بالمثبته بس بففهمم\n\nوالله احط تايمر واكتب، احاول كذا ما يجي الاختبار الا وانا قد كتبت ٤~٣ \nبس ترا ذا مب مفيد بدون فيدباك\nولأني غثيت دكتوري، كنت انا اكتب draft 1 بتايمر\n\nبعدين اذا حسيت ان كتابتي للموضوع كانت هبده او حسيت اتي ما قدرت اوضح فكرتي او الفوكاب، اروح اقرا عن الموضوع \nبعدين اسوي درافت ٢ واعدل عليه بس حاول انك تعدل وليس تغير الافكار، لان بالاختبار الافكار وطريقة كتابتك الاولى هي اللي بتجي ببالك مو اللي زرفتها.\n\nكنت اطلب فيد باك من اللي معي ( مو شرط يكون قد اخذ الكورس بس يكون فاهم) واشوف وش اكثر الاشياء اللي تجلط بكتابتي\n\nلاحظت انهم يعانوا بسب خطي، ف صرت انتبه للخط وانا اكتب.\n\nوكانوا يعلقوا على اني اكرر فوكاب واجد، صرت ادور لها مفردات، وممكن هم بنفسهم بقترحوا عليك طريقة كتابة اخرى.\n\nوكمان اسألهم وش فهموا من كتابتك عشان تعرف اذا كلامك وافكارك واضحة او تحتاج توضحها.\n\nوبس حط ذي الاشياء بعين الاعتبار وانت تعدل درافت ٣ لو تبي \n\nيصير الرايتنق اللي بعده تنتبه لهم وبإذن الله تشوف فرق\n\nموضوع انه يكون عندك ستركتشر ثابته ومرنه مره كويس ويحفظ وقت بالاختبار.\n\nيعني بالاختبار بدل ما افكر كيف اكتب الثيسس وكيف اكتب التوبيك سنتنس، اكون قد جهزتها من البيت ويصير بالاختبار اركز مرههه عالافكار والاابوريشن\n\nلازم تكتب وتاخذ فيد باك ع كتابتك عشان تتأكد ان اللي تكتبه صحيح\nلأن احيانا تسوي ارقيومنت والمطلوب مثلا كومباير بالغلط\n\nف لازم تاخذ فيد باك من دكتورك\nوانا اسوف ان الواحد اذا يبي يفهم التاسك زيين لازم يكتب عالاقل ٣ مقالات وياخذ عليها فيد باك\n\nواحيانا اادكتور يعطي فيد باك زي وجهه واحيانا مو مفهوم\nاحيانا تكتب شي تحس انه واو وتروح للدكتو ويسفل فيك…\nواحيانا تكتب شي عادي ويمدح\nوتحس انك ضايع مو عارف وش قاعد تسوي انت\n\nوهذا سبب غثاثته، ما تقدر تعتمد ع نفسك وتسوي كل شي لحالك لازم تروح لدكتورك….  \nبس عن نفسي كنت اخذ كم فيدباك من الدكتور وبعدين اكتب لحالي واصحح لنفسي بناء عالفيدباك حقه\n\nالترم : 232\nالقريد: A+ \nالدكتور : عادل محمود\n\nمستواي : بدأت من ٠٣ وكنت اواجه صعوبة شوية ولكن طورت نفسي خلال اللفلين ٠٣ و ٠٤\n\n • الرايتنق :\nلازم قبل كل اختبار اكون كاتب ٣ اسسايز \nعلى الاقل وماخذ عليهم فيدباك\n\nبالبداية ممكن تواجهون صعوبة في فهم الكورس وطريقة الكتابة لكن انشب للدكتور لين تفهم\nكنت اسوي ثلاث درافتات: - \n\n~ الدرافت الاول : اختار موضوع عشوائي واحط مؤقت واكتب كأني في اختبار ( مهم عشان تتدرب ع تنظيم الوقت). \n\n~الدرافت الثاني:  اقرأ اللي كتبته  وانقده، احيانا اقرأ عن الموضوع قبل الدرافت الثاني عشان اتأكد اني ما قعد اهبد. وغير كذا لما تقرأ عن الموضوع وتتبحر غالبا بتلقى مفرادت افضل من اللي كاتبها وبتلاقي صيغ احلى للجمل( لا تنسخها تماما بس اعد كتابتها ).\nف لما اجي انتقد اللي كتبته انا اركز عالمنطق وتسلسل الافكار، هل الانترو كويسة؟ هل شرحي كان كفاية؟ كيف اقدر اكتب كلام افضل يقنع الكاتب؟\nوبعدين احاول اعدل ال paraphrasing واشوف لو اقدر اضيف قواعد احلى تحسن من اللي كتبته غالبا تكون بسيطة بس ترفعك في قسم القرامر. واصحح كمان الاخطاء اللي في القرامر والسبلنق وعلامات الترقيم. ( مهم تلاحظ اخطائك وتعدلها بنفسك اذا قدرت)\n\n~ الدرافت الثالث:  اوديه للدكتور واشوف رايه( اهم خطوة)\nركز عاللي يقوله واذا قالك لا تسوي ذا الشي حاول تفهم ليش اخطأت وكيف اقدر اصحح الخطأ؟\nغالبا الدكتور بيلاحظ مشاكل مهمه انت ممكن تغفل عليها زي انك تطلع اوف توبيك، او البرقراف يكون ما يكون unified، وذي تخسف قريدك.\n\n\nفي نهايات اللفل قدرت استغني عن الدكتور لان حسيت اني فهمت الكورس وفهمت ابرز المشاكل، صرت اعطي نفسي فيدباك واطلب من احد الاصدقاء يعطيني فيدباك. \n\n • الريدنق : \nاشياء ما سويتها بس ودي اني سويتها\nاقرا الريدنق بورتيفوليو وفصفص النص، حدد الكلمات اللي ما تعرفها ابدا وافهم معناها وشوف كيف استخدمت في النص. حاول تفهم كل سطر في النص واذا علقت عند جملة او عند فكرة، عادي ابحث بقوقل واقرأ اكثر.\nوعشان تزيد الفايدة، وانت تقرأ لاحظ كيف الكاتب صاغ جمله، كيف يسوي paraphrasing ، حدد الكلمات اللي تعجبك وتحس انك تقدر تستخدمها في \nالرايتنق وإلخ.\n\nوبيعطونكم تدريبات للريدنق حلوها وحطوا تايمر. \n\n•القرامر والفوكاب :\nانصح بحل كويزات الفوكاب وبشدة الاختبار مشابه لها👌🏾\nكمان كويزات القرامر عشان تعرف اخطائك وتعرف اي قاعدة تركز عليها\n \n• قبل الاختبار : \nحل اختبار كامل عشان تتعلم كيف تقسم وقتك، كم بتعطي دقيقة للريدنق؟ كم \nبتعطي دقيقة لباقي الاقسام؟ (حط الزمن الضائع في تقليب الاوراق بعين الاعتبار )\nمين بتبدا ليه اول الريدنق او القرامر او الفوكاب؟\nشوف اللي يناسبك وسوي زيه في الاختبار.\n\n • تقييمي للدكتور :\nما كنت افهم منه علطول بالاول بس بعدين صار كويس مره ويشرح بالتفصيل\nمتعاون بالاوفسس اورز بس احيانا يفصل لو كان فيه زحمة.\nبس احيانا يعطي فيدباك من قلب لدرجة يمسك الورقة ويقعد يكتب ويعلمني كيف ممكن افكر بطريقة افضل ( higher order thinking )\nيعصب لما اعطيه برقراف بدون ما اسأل، يقول اعطيني اسئلة محددة زي مثلا هل الانترو كويسة؟ مثلا مشكلتي في التوبيك سنتنس كيف اقدر اعدلها؟ مثلا الابوريشن كيف اقدر اطوره؟ والخ\n\n • ابي استعد للفل قبل اخذه كيف؟\nانصح بالكتابة عشان تطور افكارك وتتعود ع صياغه الجمل والparaphrasing وتعود نفسك عال academic tone، حاول تتخلص من بعض المشاكل قبل لا تدخل اللفل، مثلا تعود نفسك ما تكتب ضمائر  (I you, she he). تعلم كيف تخلي كتابتك مرتبة وانك تركز على فكرة وحدة وتشرحها زين بدل ما تهبد ستين فكرة مختلفة في برقراف واحد. \nتعلم كيف تسوي panning كويس قبل ما تبدا تكتب لانها مهارة مههممة. \nواحرص انك تاخذ فيدباك جرب ارسل في القروب وان شاء الله تحصل من يساعدك.\nاعرف نقاط ضعفك وطورها مثلا انت سيء جدا بالقرامر تلخبط في ابسط القواعد؟ حاول تشوف سلايدات القرامر وتتدرب عليها واحرص انك تستخدمها في الرايتنق.\nباختصار في الرايتنق طور ثلاث مهارات اشياء :\n ⁃ higher order thinking \n ⁃ Organisation \n ⁃ Paraphrasing \n ⁃ Reading ( good writers are good readers)\nوزي ما قلت من خلال القراءة بتكتسب مفردات اكثر =\u003e\u003e درجة محترمة  في قسم الفوكاب 👌🏿\n\n🛑مدة دراستك وطريقة دراستك تعتمد بشكل كبيير على مستواك باللغة لذلك احرص على معرفة مستواك ونقاط ضعفك اولا 🛑\n\nTask 3 بيكون رايك\nالاول بيعطونك موضوعين مثلا تيك توج ويوتيوب وتقعد تقارن بينهم  تقريبًا نقدر نقول حقائق\nوالثاني cause and effect\nيعطونك موضوع وتكتب الاسباب له او النتائج له\nمثلا الاحتباس الحراري \nالاسباب ممكن تقول قطع الاشجار واحتراق الوقود الاحفوري\nتقريبا كمان حقائق\n\nاما اخر رايتنق يعطونك جملة والمفروض تكتب رايك عنها، هل تتفق او ما تتفق مع ذكر اسبابك\n\nمثلا\nKfupm should allow all students to cook while living on campus\n\nالحقيقة اخلي البورتيفلويوز واحل التدريبات اللي يحطها دكتورنا ( عشان اتدرب عالوقت) \nواخر شي احل اختبار كامل بتايمر وبس والله","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/134466","user":"i4kcm","ts":1711580751000,"mid":134466,"mids":[134466,134538,134539,134858,145115,145122,162516]}}', 1711580751000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p136149-engl101', 'tg-aseora', 'ENGL 101', 'info', '{"desc":"انت تختار \nFor or against \nويصير عندك ٢ باراقرافز على حسب وش خترت وبراقراف عكس الي خترته","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/136149","user":"aseora","ts":1715349869000,"mid":136149}}', 1715349869000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p137498-engl101', 'tg-asma_matar', 'ENGL 101', 'info', '{"desc":"شوفي الثمانية قطع وتدربي على مواضيعها على كلام دكتورنا احتمال يجي موضوع يشبه لها فالرايتنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/137498","user":"asma_matar","ts":1716295515000,"mid":137498}}', 1716295515000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p138247-engl101', 'tg-refah_am', 'ENGL 101', 'info', '{"desc":"البودي الأول والثاني بتتكلم عن النقاط اللي اخترتها الي بالثيسز ، بيكون نفس الرايتينقز اللي قبل مافي شي جديد \nبالنسبة للكاونتر ارقيومنت بتبداه اماً بفكرة معارضة لاحد افكارك اللي اخترتها بالثيسز أو فكرة جديدة وتبدا ترد عليها ان ليه هي خطا وأنت صح","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/138247","user":"Refah_am","ts":1716384535000,"mid":138247}}', 1716384535000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p138281-engl101', 'tg-moalhaqbani', 'ENGL 101', 'info', '{"desc":"بعدين نفس نظام القديم بس الفرق اغلبه بيكون في البرقراف الرابع انك تسوي ريبوتل \nالي هو تجيب كلام يضعف الرايتنق حققك وبعدين ترد على هذا الكلام \nمثال:\nنقول انك انت مع الطاقة المتجددة \nفي البرقراف هذا تجيب كلام يضعف كتابتك وتقول مثلا في بعض الناس يقولون ان الطاقة المتجددة غالية \nبعدين انت ترد عليهم وتقول  تقول ان كلامهم صح نسبيا لكن اذا استثمرنا الأن في الطاقة المتجددة بعدين بنوفر اكثر من الي استثمرناه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/138281","user":"MoAlhaqbani","ts":1716386627000,"mid":138281}}', 1716386627000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p138304-engl101', 'tg-u5265950047', 'ENGL 101', 'info', '{"desc":"احفظ الفوكاب \nالقرامر الموجودين ف القايد ذاكرهم \nاقر 5-8 ريدنق تاكس بجيب واحد يشبهم \n\nوالكتابة شوف الستركشز حق التاسك","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/138304","user":"","ts":1716388168000,"mid":138304}}', 1716388168000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p139343-engl101', 'tg-u1425644925', 'ENGL 101', 'info', '{"desc":"لا، سألت دكتوري (الكورد) في وقت الاختبار قال \"Doesn\u0027t matter it is not gradable\"","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/139343","user":"","ts":1716452243000,"mid":139343}}', 1716452243000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p140721-engl101', 'tg-u1678860602', 'ENGL 101', 'info', '{"desc":"الرايتنق بياخذ وقت واجد فإذا انت موادك تسمح لك.. عطه وقته.. ااما اذا لا.. ف خله بآخر يومين من اختبارك..\nلان جدا صعب انك تغير شي بالكورس هذا بالذات يعني لو ثبتت ع شي مح تقدر تغيره + لو بتغير فحتمال كبير راح تاخذ الوقت من مواد ثانية\n\nخصوصا ان ترا المدرسين مايشرحون قرامر ولا فوكاب ولا ريدنق بالكلاس.. بس رايتنق.. فراح مايصير عندك وقت حق الريدنق بالكلاس للتدريب.. الا مع الاوفس مع مدرسك لو تبي تسأله","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/140721","user":"","ts":1716731937000,"mid":140721,"mids":[140721,143368]}}', 1716731937000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p142755-engl101', 'tg-lphr8', 'ENGL 101', 'info', '{"desc":"7. The ENGL 102 midterm exam and the essay portion of the ENGL 101 final exam are double-marked. The grades assigned to students are determined by at least two teachers marking independently. The section teacher also checks any exam grades that differ significantly from writing grades awarded during the semester. Therefore, no exam essays will be re-graded.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/142755","user":"lphr8","ts":1716981126000,"mid":142755}}', 1716981126000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p143236-engl101', 'tg-kmmaq_509', 'ENGL 101', 'info', '{"desc":"شف رغم ان الأسلوب يختلف لكن بشكل عام اشوف افضل شيء تسويه تكتب كل يوم one essay that is well structured","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/143236","user":"kmmaq_509","ts":1717179457000,"mid":143236}}', 1717179457000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p143252-engl101', 'tg-hass1071', 'ENGL 101', 'info', '{"desc":"ازعج دكتورك في الاوفس اور اي شي ما فهمته روحله + اي براكتس خذه بجدية لا تقعد تقول ما عليه درجات","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/143252","user":"Hass1071","ts":1717185018000,"mid":143252}}', 1717185018000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p145031-engl101', 'tg-juayli', 'ENGL 101', 'info', '{"desc":"جزاك الله خير، حاب اكرر على موضوع الريدنق\n\nالريدنق والله هو الي لعب بالحسبه\n\nصحيح ان الريدنق بورتوفوليو ما كان اجباري هالسمستر\nلكنه كان مهم بشكل رهيب. كونه غير اجباري لا يعني تسحب عليه وانا الصراحة سحبت عليه بشكل كامل لان شفت مهو اجباري ولا عليه شي يرجااال اسحب اسحب.\n\nالنتيجة كانت C في ريدنق الميد وراجعت عالسريع في الفاينل جبت B\nلو على المستوى الاولي يفرق وما يفرق في الاوريا كنت اطلع بحول ال٢٠ نسبة عن الافرج لكن وقتها كان الريدنق جزء اساسي من يومنا.\nفالكلام بشكل عام تدربوا عالريدنق وخلوكم قريبين منه عشان لا تفقدوا المهارة او تقل عندكم. الريدنق يمثل اكثر من 20% من الدرجات، لا تخلونها تضيع منكم.\n\nما حبيت اكتب تجربتي لان الاخوان ما قصروا فوق كفوا ووفوا، وبعد دكتوري هذا اخر سمستر له بالجامعة فما اعتقد فيه فايدة كبيرة، بس حبيت انوه وأاكد على اهمية الريدنق لان جد فرق معاي.\n\n\nبالتوفيق جميعاً","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/145031","user":"juayli","ts":1717555809000,"mid":145031}}', 1717555809000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p145456-engl101', 'tg-icjzj', 'ENGL 101', 'info', '{"desc":"نفس نظام القطع الي كانوا يحددونها ويقولون وحده منها رح تجي بالميد او الفاينل ، اللهم القطع معها أسئلة منها مقالي ومنها خيارات ولازم له وقت مخصص عشان يمديك تستوعبين الفكرة كاملة . يجيك ٤ ممكن تجي بالميد و ٤ ممكن تجي بالفاينل","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/145456","user":"icjzj","ts":1719412465000,"mid":145456}}', 1719412465000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p146205-engl101', 'tg-iixk11', 'ENGL 101', 'info', '{"desc":"السلام عليكم و رحمة الله و بركاته \nتجربتي بـ English101 \nTerm: 232 \nGrade: A+\nInstructor: Keith Arnolds \nأولًا، كنصيحة لا تبدأون بالكورس بسمعته الشائعة، صدقًا الكورس يحتاج تطور نفسك و تتقبل التجديد بستايل الرايتنق و لكنه مب مستحيل\nبدايةً فلاش باك سريع قبل آخذ الكورس بترم الأوريا بدأت من 03\nو لڤل 04 أكثر لڤل اهتميت فيه بالرايتنق لدرجة أسبوعيًا أكتب 2-3 Essays و أعطي دكتوري و يعطيني عليهم فيدباك و هذي من أكثر الأشياء اللي فادتني لذلك Pay Attention يا أوريات \nبدأت 101 الترم اللي بعده، أولاً أخذنا كيفية كتابة الـ General Essay \nهذا النوع اعتبروه تعريف و من خلاله تتعودون على ستايل الكتابة الأكاديمية \nثم الـ Compare and contrast \nثم الـ Cause and effect\nهالنوعين كل واحد فيهم عليه تاسك خلال الترم \nو أخيرًا الـ Argumentative \nهذا النوع هو اللي تختبرون فيه بالفاينل \nلا تشرهون على أنفسكم بالبدايات، بالنسبة للرايتنق بـ 101 مهارة تُكتسب مع مرور الوقت \nالطريقة مع دكتوري و أغلب دكاترة القسم كان إننا نسلم الـ Essay برقراف تلو الآخر \nبمعنى بداية الأسبوع نتعلم كيف نكتب Introduction ثم يعطينا فرصة يوم أو يومين نسلمه في Turnitin و يكتبون عليه الفيدباك \nو نهاية الأسبوع مثلًا Body paragraph و يعطونكم الويكند و هكذا \nهذي الطريقة الوحيدة تقريبًا عند أغلب دكاترة القسم اللي تقدرون تأخذون فيها فيدباك لأن البعض و الأغلب ما يقبلون تكتبون رايتنق إضافي و تأخذون فيدباك منهم بحكم ضيق الوقت و كثرة الطلاب و الطالبات و ما إلى ذلك \nلذلك اهتموا و انتهزوا هذي الفرصة بحكم إنها الوحيدة اللي تقدرون تأخذون فيها فيدباك و تطورون من مستواكم و تعرفون دكاترتكم وش يبغون بالضبط \nبالكلاس كنت أنتبه و أركز على طلبات دكتوري و آخذ ملاحظات للأشياء اللي ينبّه عليها \nو أثناء كتابتي أكتب اللي يبيه بالضبط و ما أتفنن و أكتب على نظرتي و ستايلي الخاص زي ما كنت أسوي سابقًا، بمعنى مافيه مرونة كبيرة بهذا الكورس لأن لازم تحاول قدر الإمكان تكتب بالضبط على طلب دكتورك و إرشاداته \nقبل التاسكات كنت أراجع المطلوب بكل نوع رايتنق و أسوي Template بسيط للمطلوب بكل برقراف ( مهم و مفيد جدًا ) \nركزوا على الأفكار المبتكرة و ركزوا على الـ Paraphrasing و إنكم تستخدمون قرامر مستواه عالي لأن هذا وقت استعمال الـ Complex language و انتبهوا تستعلمون Non-academic language و هذي الأشياء بتعرفونها خلال الكورس و مع الممارسة - إن شاء الله- \nبالنسبة للريدنق كنت أقرأ و أفهم و أحلل القطع اللي بالـPortfolios و أحل تمارينها ( مهم لأن أحد القطع تجي بالاختبارات )\nبالنسبة للقرامر و الڤوكاب كنت أدرس القرامر من ملف بالتلقرام و أتدرب من اختبارات التلقرام برضو و الكورد كان يرسل بالبلاك بورد اختبار براكتس قبل الميد و الفاينل و كنت أختبرهم \nالڤوكاب من الـ AWL أفهم معنى كل كلمة و أحفظ تعاريفهم عشان الميد و أستفيد و أوظفهم بالرايتنق حقي ( مهم ) \nاستفيدوا من الأوفيس آورز و استغلوها و اطلبوا المساعدة إذا احتجتوها، و استفسروا عن أغلاطكم و اعرفوا كيف تصححونها من خلال إرشادات دكاترتكم \n اهتموا اهتموا اهتموا و اجتهدوا بشكل عام بهذا الكورس و الاهتمام يبين من خلال كتابتك مع الوقت \nشخصيًا اهتميت بتطوير مستواي بالرايتنق لأنها أكثر مهارة أحبها و ركزت على التعلم أكثر من القريدات و الدرجات و الحمد لله هذا النهج اللي المفروض يُتبع بكل الكورسات حقيقة \nبتمر عليكم أيام مستواكم فيها مو الأفضل\nكنت أطلع من الPractice tests و حاسة إني ما أديت و مرت علي قريدات متنوعة و لكن بالتاسكات و الفاينل تعلمت من أغلاطي و صبيت كل تركيزي و الحمد لله نلت","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/146205","user":"iixk11","ts":1723975323000,"mid":146205}}', 1723975323000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p149444-engl101', 'tg-powerr1947', 'ENGL 101', 'info', '{"desc":"وبيقولون لكم لو ما قالوا اوريدي ان كورسات انقلش الجبل مش تعليم ولا بناء لغه من ذي النواحي\nالهدف تعرف تقرا وتستخلص + تكتب اكاديميًا بشكل كويس \nاما قواعد وفوكاب ذي تطورها بنفسك للميد والفاينل والكتابه برضو عشان تتحسن","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/149444","user":"powerr1947","ts":1724871059000,"mid":149444}}', 1724871059000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p150181-engl101', 'tg-rd9085', 'ENGL 101', 'info', '{"desc":"اول مره تكتب اسمه درافت ١ لما تعدل عليه ويصير احسن وتروح اخطاء الفوكاب والقرامر اسمه درافت ٢ وكذا كل مره تعيد الessay ويكون احسن تقول درافت جديد ٣ وبعدين ٤ وكذا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/150181","user":"rd9085","ts":1725115721000,"mid":150181}}', 1725115721000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p151687-engl101', 'tg-phc_om', 'ENGL 101', 'info', '{"desc":"اكتب لك واحد وخل الدكتور يصحح لك واعرف اخطائك ووش الي يبيه الدكتور ووش الي ما يبيه وتعلم منها وحاول تجنب اخطائك\n واهتم للي مطلوب منكم تسوونه في الرايتنق لأن هو الأساس","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/151687","user":"PHC_OM","ts":1725706973000,"mid":151687}}', 1725706973000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p151906-engl101', 'tg-spontaneous_r', 'ENGL 101', 'info', '{"desc":"عشان تكونوا ف الصورة\nالاختبار الأول مقارنة بين حاجتين\nتختار two factors فقط تقارن فيهم\nلو\n قلنا مثال مقارنة بين سفر ب سيارة وطيارة\nتختار حاجتين الي بتتكلم عنهم مثلا الوقت والتكلفة\nبتذكرهم نهاية الانترو\nوكل برقراف راح تتكلم عن فاكتور واحد فقط\nالأول الوقت وتقارن والبرقراف الثاني التكلفة وتقارن ف تكونون محصورين\n\nAWL 1-3\n+ريدنق بوتفوليو من الأولى إلى الرابعة اظن\n\nMore words doesn\u0027t mean more grades\n\nJust write what is in your head\nand it\u0027s ok if you wrote over 270\nbut don\u0027t think that you have to go more than 270 by a lot\n\nhow you wrote is more important than how much you wrote","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/151906","user":"Spontaneous_R","ts":1725733540000,"mid":151906,"mids":[151906,152728,218720]}}', 1725733540000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p154857-engl101', 'tg-wfag530', 'ENGL 101', 'info', '{"desc":"من ناحية المقارنة هذا شيء يرجع لك اذا ودك تذكرين اشياء ايجابية أو سلبية \nأهم شيء البودي حقك يكون Well elaborated + unified\nوابعدي عن ذكر أكثر من مثال بس \nخلي كل detail تكتبينه يكون له علاقة بالtopic sentence\n\nاي لازم اصلاً في الconclusion حقتك تحددين الأفضل منهم للAgent حقك \nهذا لو كان Stated approach\n\nلو كان Revealed approach رح تذكرين two agents \nيعني مثلًا مقارنتك بين أبل وسامسونج \nبتختارين الفئة المستهدفة حقتك اللي هم ال Reason of comparsion \nSamsung = For KFUPM students\nApple = For Aramco employees\n\nRephrasing the thesis\nSummary\nAnd the last sentence you can write a recommendation, strong statement, or a future possibility ( Only one )\n\nفي الكورس هذا حاول ما تشوف مصادر خارجية مرة ولا تخلي الAi يكتب لك شيء لأن تراهم مرة مدققين على هالشيء \nوحتى لو فيه مثلًا امثلة على essay ممتاز ستل بيكون فيه اخطاء فوكاب او قرامر يعني مثلًا المس حقتنا كانت تورينا امثلة لessay قديمة لطالباتها وتكون ممتازة وكذا بس بنفس الوقت تطلع لهم اغلاط وتخلينا ننتبه لها ..\nلذلك اشوف ما فيه شيء بيرفكت ١٠٠٪؜ \nوك نصيحة امانةً اكتب بنفسك كل شيء وخذ تعليقات من الدكتور على كتابتك هذه اشوفها تفيد اكثر بكثير من لمن تقرأ امثلة سابقة\nممكن هالامثلة تفيدك تتعلم فوكاب جديد، واسلوب كتابة مختلف لكن حاول تاخذ المعلومة من الدكتور افضل واحسن\n\nENGL101 - T241\nاسم الدكتور: TAISEER\nالسلام عليكم ..\nحبيت أتكلم شوي عن تجربتي خلال هذا الكورس وإن شاء الله تفيد الطلاب اللي بيأخذون المادة لاحقًا ..\n\nقبل كل شيء بتكلم عن تجربتي مع المس :\nالمس صراحة شرحها للستركتشر واضح مرة وترحب بالكل في الاوفس أور والفيدباك حقها مفيييد مرة. بالنسبة لتصحيحها أشوفه كويس وعادل للأمانة وهي تمشي على الrubric بالحرف ف دائمًا شيكوا عليها واقروه زيين!\n\nطبعًا الكورس يعتمد بشكل كبير على الSelf-study ف لازم تشتغل على نفسك كويس عشان تجيب فيه درجات. خلال المحاضرة التركيز بيكون على الرايتنق فقط وأحيانًا ممكن شرح لبعض القواعد اللي يغلطون فيها الطلاب في كتاباتهم. \nرح أقسم تجربتي لقسمين :-\n١- الرايتنق\n٢- باقي الأقسام ( الميد والفاينل )\n\n🔸 الرايتنق :\nأول وأهم خطوة سويتها صراحة كنت أركز على ستركتشر المس كانت تنزل السلايدات بالبلاك بورد فيها كل المتطلبات اللي هي تبغاها. وساعات كانت تكتب أشياء معينة بالبورد ف كنت أصورها عندي. بعد كذا كنت ألخص الستركتشر حقي بناءً على الأشياء اللي خذيتها مع المس في الكلاس. وفي نهاية التلخيص كنت أخلي مساحة فاضية أكتب فيها الفوكاب اللي أشوفه بيفيدني ( أبدأ أكتب اللي عندي من معرفتي السابقة وبعدين أشوف الفوكاب اللي يعجبني من السلايدات ). \nبعدها أبدأ أكتب رايتنق من المواضيع اللي موجودة في السلايدات ( وضروري أحط تايمر عشان أضبط وقتي ) هالخطوة مرة فادتني والحمدالله ما حسيت أني انزنقت ب ولا اختبار.\nدائمًا كان فيه optional homework على البلاكبورد عبارة عن رايتنق كنت أسويه لازم عشان أخذ فيدباك.\nبالنسبة للفيدباك كان مرة يفيدني صراحة خاصةً في الرايتنق الأخير فرق معي 180 درجة حتى في القريد. ضروري تأخذون ملاحظات ترا الأوفس اور ممتازة مرة وحتى الفيدباك اللي يجيكم بعد ما تسلمون الoptional homework بيخليكم تتطورون أكثر وأكثر.\nوكنت بعد كل رايتنق أشيك على الrubric أشوف هل كل المتطلبات موجودة لأن هالشيء ضروري مرة وطبعًا المس حقتنا قد شرحته لنا بكلاس كامل لأنه مهم جدًا.\n🔺ملاحظة :- مواضيع الReading protofilo رهيبة رهيبة رهيبة فادتني مرة فيها فوكاب مرة ممتاز وبنفس الوقت استفدت من أحد المواضيع في رايتنق الفاينل.\n\n🔸الميد والفاينل :\nالميد والفاينل كانوا بسيطين مرة بالنسبة للريدنق ختمت الReading protofilo وحليت أسئلتهم. وبرضو فيه additional practice كانت تحطهم لنا المس بلاكبورد الحلو فيها مؤقتة على 20 دقيقة بحيث رح تقدرون تتدربون على الوقت وما تنسون نفسكم بالاختبار، حاولوا تحلون اللي تقدرون عليه أنا عن نفسي خلصت ٢ منهم بس.\nالفوكاب كان مرة سهل بيكون عندكم 6 sublists من الAWL أول 3 للميد وآخر 3 للفاينل، وصراحة جزء كبير جدًا منها مرّ علي مسبقًا ف من هالناحية الفوكاب بسيط يكفي تفهمون الdefinitions كويس وسووا براكتس على الكويزات الموجودة هنا رااائعة صراحة مع الQuizlet.\nبخصوص القرامر ف شفت الguideline حق الاختبار وحددت بالضبط ايش القرامر اللي معنا. ما عندي لها مصدر مذاكرة محدد شوفوا اللي يناسبكم أنا عن نفسي راجعت بعض القواعد من كتبي في الأوريا - قناة Engvid رح أرفق رابطها والقرامر صراحة مصادره كثيرة مرة شوفوا اللي يناسبكم منها وأهم شيء تدربوا \nتدربت عليها من كويزات القروب مرة كويسة وفيه ملف خاص بستركتشر التوفل حليت منه بعض أسئلة الfind the mistake وايضًا موقع Perfect English \nآخر شيء يوم الاختبار حليت الpractice test.\n\nموقع Perfect English Grammar :\n\nhttps://www.perfect-english-grammar.com/grammar-exercises.html\nالرابط اللي فيه كل كويزات الميد والفاينل :\n\nhttps://t.me/KFUPM_ENG101/168616\n\nوبس والله .. \nبالتوفيق للجميع ..\n\nيا جماعة هذه الملفات سويتها لكم قبل براكتس تاسك 3 الأول فيه الستركتشر والثاني حطيت لكم فيه مواضيع مقترحة من الريدنق لأن واحد من المواضيع اللي بتجيكم بيكون من مواضيع الريدنق ، عندي بس كم نصيحة ودي أضيفها : \n\n▫️اقروا الريدنق مرة كويس، لو فيه فكرة ما فهمتوها أبدا ترجموها ترا مرة مهم وحتى في الاختبار بيسهل عليكم تطلعون reasons وتشرحون أكثر وتفصلون فيها وكمان بيفيدكم بالفوكاب \n\n▫️اكتبوا كثير وتدربوا عالتاسك مرة زييين لأكثر من سبب أهمها طبعًا عشان ترفع قريدكم في المادة وثانيًا لأن هذا اللي بتسوونه بEngl102 مع اختلافات بسيطة مثل إضافة دراسات واحصاءات وكذا لكن بشكل عام نفسه بالضبط فإذا تأسستوا في هذا صح بيسهل عليكم في 102 \nوبالتوفيق للكل\n\nالانستركتر حقك بيعطيك الستركتشر زي ماهو موجود في السلايدات مارح يطلع عنه ابدًا \nانت طبّق الموجود في السلايدات بالضبط افهم الستركتشر\nسوي براكتس كثير خذ فيدباك من الدكتور قد ما تقدر ..\nانا (عن نفسي) طبقت اللي كانت تقول عليه المس بالكلاسات + خذيت فيدباك كثييييير منها وحتى اكثر من التاسكات اللي قبل وكان اعلى قريد رايتنق عندي التاسك ٣\nفالمقصد هو امشي على كلام السلايدات واعتمد عليها وعشان تطور كتابتك خذ ملاحظات من الدكتور\nالتصحيح ما اشوفه صراحة يفرق مرة لا تفكر فيه\n\nالصدق كلها نفس الشيء\nالثالث بس طويل واضافوا بارقراف جديد\nرايتنق الفاينل حتى الوقت حسيت فيه بركة الصدق اول شيء اخترت موضوع واسباب وسويت بلان بوقت مرة قياسي والسبب انّي كنت قارية الريدنق ..\nعشان كذا قلتلكم الريدنق اقروه مرة ومرتين و٣ \nكان مفيد من جميع النواحي حتى في الفوكاب صار عندي تنوع عكس التاسكات اللي قبل\nالشيء الثاني لأنّي سويت خطة وخلصت منها بسرعة قدرت اراجع اللي كتبته اكثر من مرة ..\nفأنا اقول نصيحة\n\nشوفوا الستركشتر وراجعوه\nبعدين اكتبوا وخذوا فيدباك \nوتدربوا مرة او مرتين على كم موضوع من مواضيع الريدنق \nولو ما قدرتوا عالاقل اقروها القراءة لحالها تساعد مرة وهذا اللي سويته امانةً\n\nاقروا البروتوفيلو وربي مهم وبيخدمكم ويوفر عليكم وقت","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/154857","user":"wfag530","ts":1727457919000,"mid":154857,"mids":[154857,154871,183944,215660,215912,239455,239574,239577,244491]}}', 1727457919000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p156508-engl101', 'tg-a17uss', 'ENGL 101', 'info', '{"desc":"اخر رايتينق حنسويه حيكون\nArgumentative essay\n\nوالي موضوعه حيكون مقارب من الريدنقز الي كنا نقراها ف حتستخدم المعلومات والفوكابز الي فيها عشان تساعدنا نكتب رايتنق مزبوط على الموضوع","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/156508","user":"a17uss","ts":1727992481000,"mid":156508}}', 1727992481000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p156740-engl101', 'tg-huzmh555', 'ENGL 101', 'info', '{"desc":"اول شي حدد aspect بعد ما تحدده حدد التركيز فال aspect نفسه اذا حددت نقطه التركيز لازم تكتب بشكل موحد عنها .\nمثال لو اختارنا aspect عن الفلوس أو المبلغ \nتقدر تركز على القيمه و المميزات/ القيمه والعمر الي يعطيك اياه / غلاء السعر / و كذا \nولافي شي أفضل من انك تقعد و تتدرب على توبيك البراكتس الي فوق حاول تحدد بنفسك","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/156740","user":"huzmh555","ts":1728104238000,"mid":156740}}', 1728104238000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p161323-engl101', 'tg-fr1889', 'ENGL 101', 'info', '{"desc":"ذاكر سلايدات القرامر وحل تدريبات شوف مقاطع اذا مافهمت\nالفوكاب نفس الشي الملف وتدريبات \nوالريدينق بورتفوليو","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/161323","user":"Fr1889","ts":1728650091000,"mid":161323}}', 1728650091000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p164690-engl101', 'tg-z7_z13', 'ENGL 101', 'info', '{"desc":"السلايدات\nشوفي التوبيك اللي تحسيه صعب او ماتعرفيه دوري شرح له\nحلي كويزز من هنا وأولدز وراجعي اللي تغلطي فيه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/164690","user":"Z7_Z13","ts":1728836130000,"mid":164690}}', 1728836130000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p169594-engl101', 'tg-srrhho_o', 'ENGL 101', 'info', '{"desc":"الحين مواضيع الreading portfolio\nLab grown meat\nSoft skills and hard skills\nLab grown meat2\nElectric vehicles\nصح؟؟؟","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/169594","user":"srrhhO_O","ts":1729000500000,"mid":169594}}', 1729000500000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p175063-engl101', 'tg-isllu', 'ENGL 101', 'info', '{"desc":"قال لي الدكتوري ان خانة الميد بيكون فيها 3 قريدات ، كل قريد يمثل كل قسم \nوخانة الرايتنق بيكون فيها 4 قريدات كل قريد يمثل روبريك\n\nاذا جاء نهاية الترم وافرج الكورس تحت الـ C+ \nيتحول الكورس لافرج فممكن بتلاحظ فيه زيادة في قريدك النهائي من قريد الى قريدين مع الأبقريد \n\nباستثناء الطلاب الي قرديهم تحت الـ C مايشملهم الافرج ولا لهم ابقريد\n\nهذا الي فهمته من السيلابس","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/175063","user":"isllu","ts":1729156114000,"mid":175063,"mids":[175063,188853]}}', 1729156114000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p177666-engl101', 'tg-lf2zsl', 'ENGL 101', 'info', '{"desc":"Midterm results will be in the grade centre for your classes soon  before 4pm\nthey will look like this \nAB+D=B\nA- Reading\nB+ -vocab\nD- grammar\nOverall based on percentage on the different weight of each section (B)\n\nThe writing:\nAC+D+B=C+\nA-Response\nC+ - Structure\nD+ Vocab\nB- Langauge Use\nOverall is C+ is based on the average  letter score among sections\n\nكذا الطريقة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/177666","user":"lf2zsl","ts":1729167134000,"mid":177666}}', 1729167134000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p179494-engl101', 'tg-bskswoiw', 'ENGL 101', 'info', '{"desc":"لااا ايش تدردب!!، بعدين ترا الريدينق المفروض انه اصعب شي  ، الفوكاب يمديك تتقنه بسهوله من الفلاش كاردز سو لك عليهم تيست من نفس البرنامج كويزليت واقعد عيد اكثر من مره حتى لو عندك اغلاط و بتتقنه بسهوله حتى لو بيوم ( بس الافضل ما يكون بيوم ) ، القرامر يمكن يبغالك تسال الدكتور عليه وبس","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/179494","user":"bskswoiw","ts":1729171705000,"mid":179494}}', 1729171705000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p181166-engl101', 'tg-if6amr', 'ENGL 101', 'info', '{"desc":"انا جبت فيه A  ومادرست الريدنق بورتفوليو لضيق الوقت بس قريته عشان لو  في فوكاب مااعرفه اترجمه \n\nعن نفسي مااقرا الريدنق فالبدايه اقرا بس عن وش الموضوع واروح للاسئله على طول \n\nمهاره الريدنق لازم تصير تقرأ واجد بكثره لين تصير تقرا بشكل سريع بس بنفس الوقت انت مستوعب عن وش النص  يعني تكون عندك مهاره ال skimming \n\nاروح للاسئله واشوف ال key word فالسؤال وادور عليها بالبرقراف واحاول اطلع الجواب واحصر الخيارات احاول الغي الي احسه غلط وبس كذا\n\n+ بديت بالريدنق وعطيته وقت اكثر بحكم انه عليه النسبه الاعلى","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/181166","user":"if6amr","ts":1729198510000,"mid":181166}}', 1729198510000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p181971-engl101', 'tg-ismailcpp24', 'ENGL 101', 'info', '{"desc":"MTE grades\n\nA+ / 23.25-25\nA / 22.5-23\nB+ / 21.25-22.25\nB / 20-21\nC+ / 18.75-19.75\nC / 17.5-18.5\nD+ / 16.25-17.25\nD / 15-16\nF / 15-","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/181971","user":"ismailcpp24","ts":1729278120000,"mid":181971}}', 1729278120000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p187707-engl101', 'tg-muathm10', 'ENGL 101', 'info', '{"desc":"والله شوف انا امشي على استراتيجية مرة اسطووورية ونفعتني في الرايتنق الاول وذا وهي انك تخلي ١٢ دقيقة او اذا مرة ١٣ دقيقة لكل براقراف وصدقني عقلك الباطني بينجز ذا الشيء ومن كثر التوتر حتخلص والوقت باقي له كثير انا خلصت وباقي ٥ دقايق كذا وراجعت","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/187707","user":"MuathM10","ts":1730803218000,"mid":187707}}', 1730803218000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p189453-engl101', 'tg-u645539369', 'ENGL 101', 'info', '{"desc":"لا مو صعبه، اشوف مايحتاج لها مذاكره يوميه بس اذا فاضيه وماعندك الا هي تقدري تذاكري الفوكاب والقرامر من البداية اول بأول \nغيرها في رايتينق وذا احس على حسب مستواك بشكل عام اهم شي تكوني فاهمه الستركجر","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/189453","user":"","ts":1732172001000,"mid":189453}}', 1732172001000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p190212-engl101', 'tg-x7ktl', 'ENGL 101', 'info', '{"desc":"Writing grades\n\nA+ /  13.95-15\nA / 13.5-13.8 \nB+ / 12.75-13.35 \nB / 12-12.6\nC+/ 11.25-11.85\nC/ 10.5-11.1\nD+/  9.75-10.35\nD/ 9 - 9.6\nF/0-8.9","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/190212","user":"x7ktl","ts":1732196055000,"mid":190212}}', 1732196055000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p191316-engl101', 'tg-aj0ad', 'ENGL 101', 'info', '{"desc":"كل الثنتين :\nستاندرد لان القريدات ثابتة ما تتعدل في الحالة الطبيعية والجدول حق القريدات هو نفسه ما يتغير \n\nلكن كم شرط تخلي المادة تصير افرج ولها كم شرط:\n١. افرج قريدات الطلاب اقل من 2.75 يعني بين +B-C \n٢. قريدك يكون فوق ال+D\n\nمثلا لو الافرج C وقريدك D درجتك ما بترتفع وما بتستفيد من الافرج شيء \n\nواذا مثلا قريد خويك +C فبترتفع درجته \n\nفالطلاب في نفس الكلاس بعضهم بيستفيد من الافرج وبعضهم لا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/191316","user":"aj0ad","ts":1732521855000,"mid":191316}}', 1732521855000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p191406-engl101', 'tg-mii7xm', 'ENGL 101', 'info', '{"desc":"٦٠ دقيقة: ١٥ سؤال ريدنق ، ١٧ سؤال فوكاب ، ١٨ سؤال قرامر . وبعدها بريك ما ادري كم دقيقة وبعدها ٧٥ دقيقة للرايتنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/191406","user":"MIi7xm","ts":1732529341000,"mid":191406}}', 1732529341000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p194092-engl101', 'tg-o_q7t', 'ENGL 101', 'info', '{"desc":"١ احفظ الawl ثم تدرب عليها\n٢ ذاكر سلايدات القرامر وافهمها زين ثم تدرب عليها\n٣ احفظ البورتفوليو حفظظظ","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/194092","user":"o_q7t","ts":1733585123000,"mid":194092}}', 1733585123000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p196278-engl101', 'tg-voqcn', 'ENGL 101', 'info', '{"desc":"هذا الصح\nلانه غير منطقي انك مثلاً تكتب مقال كامل عن ان الجامعات يجب انها تستعمل الذكاء الاصطناعي\n\nوتجي في الكاونترارقمنت اللي راح تكتب فيه سبب يعارض مقالك (لا يجب على الجامعات انها تستعمل الذكاء الاصطناعي)\n\nفا لما تكتب الكاونتر ارقمنت في الكونكلوجن انت كذا خالفت كل اللي بناه مقالك، واصلاً وجوده في الكونكلوجن غير منطقي","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/196278","user":"voqcn","ts":1734098222000,"mid":196278}}', 1734098222000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p203569-engl101', 'tg-interoperability', 'ENGL 101', 'info', '{"desc":"اذا مذاكر القرامر و الفوكاب بشكل ممتاز ابدا فيهم بتخلصهم باقل من عشر دقايق، اذا تحس بتاخذ وقت فيهم ابدا بالريدينق لانه عليه نفس درجة القرامر و الفوكاب مجتمعين تقريبا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/203569","user":"interoperability","ts":1734410080000,"mid":203569}}', 1734410080000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p206268-engl101', 'tg-ja18yj', 'ENGL 101', 'info', '{"desc":"لا ماله علاقة\nبالبداية لكل سكشن في افرج بعدين ياخذون افرج كل السكاشن ، اذا مثلًا سكشنك طلع افرجه اقل من الافرج العام ترتفع درجاتكم واذا اقل تبقى زي ماهي (ماتنفص)\nبعدها يصير الابقريد\nوكل هذا والقريبات ثابته","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/206268","user":"ja18yj","ts":1734637268000,"mid":206268}}', 1734637268000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p206539-engl101', 'tg-ice_ninja', 'ENGL 101', 'info', '{"desc":"تعيدها\nلكن تروح مرتبة الشرف ال١ وال٢\nوتاخذ ٠ بالمعدل للمادة سواء الفصلي او التراكمي\n\nالسلام عليكم ورحمة الله كيفكم جميعا؟\nبديكم Structure مختصر جدا امشوا عليها بالاختبار عشان ما تضيعوا\n\n5-7 Minutes of Brainstorming on an extra piece of paper = Write anything that comes to your mind.\n\nIntroduction (10 min):\n1- General Sentence\n2- Background using the Funnel Technique (2-3 Sentences)\n3- Thesis Statement (Make sure to include the prompt + the two factors)\n\nBody Paragraphs (15+10 min):\n1- Topic Sentence (Prompt + Reason)\n2- Compare and Explain\n3- Brief Conclusion / Recommendation (اعتقد اختياري الا لو تغيرت)\n\nConclusion (7 min):\n1- Rephrase the Thesis\n2- Summarise Body Paragraphs main ideas in 2 sentences briefly\n3- Closing Sentence and Recommendation\n\nتجربة 🐳N:\n\nENGL 101\nTerm : 242 🐳\nGrade : A \nInstructor : Ross Martin \n\nبسم الله الرحمن الرحيم\n \nبدايةً بتكلم عن موضوع شائع عن الكورس \n\nالكورس له سمعة منتشرة و هي كيف إن صعب تجيب فيه قريد و ما إلى ذلك\nما باقول إن الكلام هذا غلط تماماً بس بعد مو صح بشكل كامل \nممكن سبب هذا الكلام إن نصف الكورس أو أكثر يعتمد على الرايتنق مما يخليه فعلاً ممكن ما يكون القريد فيه سهل \nلكن مع الكتابة و التدريب بشكل مستمر و التعلم من الأخطاء اللي تسووها  إن شاء الله بتقدروا تطلعوا بقريد جميل من الكورس\n\nالآن بتكلم عن الكورس و تقسيمه\n\nالكورس مقسم إلى ثلاث تاسكات للرايتنق\n\nالأول: compare and contrast و هو عبارة عن مقارنة بين شيئين\n \nالثاني: cause or effect بتكتب عن السبب أو التأثير بخصوص شيء معين\n \nالثالث ( و هو الأعلى وزناً ) : Argumentative في هذا التاسك بكون عندكم برومبت  يا تكون معاه أو تكون ضده \n\nطبعاً أول تاسكين بكون عندكم two prompts تختاروا بينهم أما الثالث بكون عندكم ثلاثة\n   \nطريقة التدرب على الرايتنق:\nفي طرق متعددة كثيرة يعني ما في طريقة تناسب الكل لكن راح أذكر بعض النقاط المهمة\n\nمهم إنكم تحاولوا تستفيدوا من الدكتور سواءً في الاوفيس اور أو ترسلوا له ال essays اللي تكتبوهم و بعد الفيد باك تعلموا من الأخطاء اللي سويتوها و عدلوا ال essay حقكم مرة ثانية بناءً على هذي الفيد باك بعد ذلك اعطوا الدكتور الرايتنق حقكم مرة ثانية بعد التعديل لين ما يكون ما عنده ملاحظات عليه بهذا الشكل بتطوروا \nالعبرة مو بعدد ال essays بقد ما هي بجودة السامبل الواحد اللي تكتبوه و تحاولوا تطوروه \n\nفي نقطة كذلك مهمة و هي استخدام ChatGPT وقت ما تكتبوا في البيت\nأنا ما باقول لا تستخدموه نهائيا لكن استخدموه صح \nبمعنى لما تكتبوا سامبل مثلاً لا تكتبوا الموضوع فيه و بس تنسخوا الكلام بهذا الشكل ما بتستفيدوا شي و وقت الاختبار بتعلقوا\n \nممكن في البداية يعني لما تكتبوا أول سامبل لكم على تاسك معين تكتبوا اسم الموضوع و تاخذوا أفكار منه يعني ما تنسخوها بالضبط لكن تحاولوا تستوحوا من الأفكار هذي أفكار تقدروا تبنوا عليها \nهذا الكلام ممكن ما أرجحه بعد أول سامبل عشان لا تقللوا فعالية ال brainstorming حقكم\n \nممكن بعد و هذا الشي أشوفه مفيد هو بعد ما تخلصوا كتابة باراقراف مثلاً تعرضوها عليه و تقولوا له يخليها smoother الهدف من هذا الشي هو إنكم تعرفوا كيف تزيدوا الفلو حق ال essay يعني ممكن يكون عندكم جملتين ركبتوهم مع بعض بشكل جيد لكن ممكن يعطيكم طريقة أفضل و أوضح و تسهل على القارئ القراءة كذلك فتقدروا تصيروا تستخدموها في بعض المواضع المناسبة في المرات الجاية \n\nو بعد ممكن تستفيدوا منه في إعطائكم synonyms للكلمات و كيف تستخدموها مما يؤدي إلى زيادة حصيلة الكلمات اللي عندكم\n\nآخر شي بتكلم عنه هو ال rubric هذا يعلمكم معايير التقييم للرايتنق حقكم \nحاولوا وقت كل تاسك إنكم تاخذوا نظرة عليه لأن فيه بعض الأمور المهمة و ممكن لو ال essay حقكم كان خالي منها تسبب تأثير جدا سلبي على قريدكم في التاسك   \n   \n الميد و الفاينل: \n  \nالميد مكون من قطعتين ريدنق أقل شي وحدة بتكون من البورتفوليو\nو فوكاب \nو قرامر \n\nالفاينل نفس الشي لكن بتكون قطعة واحدة فقط و بتكون من البورتفوليو \n\n* ملاحظة لما أقول من البورتفوليو مو يعني إنها بتكون نفس القطعة \nالموضوع بكون مقارب له لكن القطعة بتكون مختلفة \n\nطريقة التدريب:\n\nالريدنق يُفضل التدرب عليه من البداية لأن وزنه كبير في الميد و الفاينل تقريباً يمثل نص الاختبار كدرجة لذلك تدربوا عليه زين \nممكن تحلوا البورتفوليوز مو شرط كل الأسئلة بس يعني خلوا عندكم استراتيجيات لحل الأسئلة في وقت قصير\n\nالقرامر \nما بكون فيه شي جديد عليكم عن الاوريا \nلذلك في البداية راجعوه و تأكدوا إنكم فاهمينه زين و لو في نقطة ما فهمتوها من السلايدات ممكن إنكم ترجعوا لها من كتاب التوفل بكون ممتاز \nبعد ذلك تدربوا على القواعد بشكل كافي \n\nالفوكاب \nللميد بكون عندكم\nAWL ( 1 - 3 ) \nو الفاينل \nAWL ( 4 - 6 ) \nبالنسبة للكثير الفوكاب هو القسم الأسهل في الاختبارين \nاللي تحتاجوه تذاكروا ملفات AWL و تعرفوا تعاريف الكلمات بعدين تدربوا عليهم\n\nالمصادر:\nطبعاً ما تنحصر في هذي لكن هذولا ممتازين كانوا \n\nقناة واحد من الطلاب الله يجزاه خير الرد حقها في القروب ( قناة مفيدة ) \n\nعندكم كذلك مصادر آيس الرد حقها \n( مصادر ايس ) \n\nو الدكتور بنزل لكم بعد إن شاء الله في البلاك بورد بعض الأمور تقدروا تدربوا منها\n\nموفقين يا رب\n\nتجربة رايتنق Engl101 للأخت Y\nW1: A\nW2: A\nFW: A ما شاء الله تبارك الله\nبسم الله الرحمن الرحيم والسلام عليكم ورحمة الله وبركاته، بكتب لكم تجربتي وان شاء الله تكون مفيدة لكم ولو قليل. الرايتنق في هذا الكورس جدًا يشبه الرايتنق في Engl04 حق الاوريا بس فيه نقطة مختلفة في هذا الكورس وهي ان فيه ستركتشر معينة للكتابة والجميع مقيد فيها عكس الاوريا تعتبر كتابة شبه مفتوحة ويمديك تكتب اللي يجي على بالك، اضافة ان فيه تركيز كبير في تقييم الافكار وتنظيم الافكار وطريقة طرحها وايضًا على التفكير العميق والمنطقي. \n\nالرايتنق تاسك 1\u00262:\nتقريبًا نفس الستركتشر مقال من اربع فقرات، مقدمة وفقرتين رئيسيتين وخاتمة. الفرق الوحيد بينهم ان الاول مقارنة بين شيئين والثاني تكتبوا عن سبب او نتيجة لموضوع معيّن. وتصحيحهم يكون غالبًا يعتمد على دكتوركم/دكتورتكم بعكس الفاينل رايتنق اللي يكون تصحيحه في لجنة بشكل عشوائي، لذلك key idea هي انكم مهم جدًا تتبعوا تعليمات الدكتور الخاصة فيه وحاولوا تسألوه دائمًا حتى تفهموا تفكيره ووش يبغى وبذلك تمشوا على كلامه تمامًا، اضافة الى انكم لازم تمشوا على الستركتشر الاساسي ومقالكم لازم يتضمن على: (thesis statement, topic sentence, restate your thesis in the conclusion, summaries your two body paragraphs in the conclusion and add a closing sentence). اول شيء لازم تفكروا فيه لما تستلموا ورقة الاختبار انكم تسألوا انفسكم: انا كيف اقدر اميّز ورقتي ومقالي عن مقالات زملائي عند الدكتور؟ حاولوا تخلوا افكاركم مميزة وابداعية لان هالشيء يأثر تأثير كبير على انطباع المصحح عن كتابتكم وممكن يخليه يتغاضى عن بعض الاخطاء البسيطة عندكم بس لان افكاركم مميزة. ولكن، انتبهوا انتبهوا ما تطلعوا عن الموضوع يعني لا تفكروا بعمق لدرجة تصيروا out of topic لان في هالحالة لا قدر الله تاخذوا F تلقائياً في قسم الرد على السؤال. كذلك ركزوا على القرامر والڤوكاب لان شيء حلو وبسيط تضمنوا قريدهم، تعلموا كلمات اكاديمية جديدة ونوعوا في استخدام القرامر عشان تاخذوا الceiling في قسم القرامر والڤوكاب.\n\nالفاينل رايتنق:\nالفاينل رايتنق هو argumentative essay مكون من خمس فقرات، مقدمة وفقرتين رئيسيتين وcounter argument وخاتمة، وفيه تركيز كبييير على الcounter argument في هذا النوع من المقال. يعطوكم موضوع وتكتبوا مقال جدلي مع او ضد الموضوع، نصيحتي اختاروا الشي اللي يسهّل عليكم الكتابة مو شرط يكون رأيكم الحقيقي اهم شي يساعدكم تبدعوا اكثر خصوصاً ان مهم يكون الrebuttal قوي واقوى من الclaim. اتبعوا نفس اسلوبكم في الرايتنق اللي قبل مع تركيز كبير على ستركتشر الفقرة الخامسة وتدربوا زين لين ما تتقنوا الفكرة تماماً. \n\n- لان المواضيع غالبيتها متكررة في هذا الكورس، التدريب راح يفيدكم جداً تدربوا واااجد نصيحة اقرأوا اقرأوا قد ما تقدروا مقالات مستواها A خذوا عنها افكار وكونوا انتقاديين في القراءة. \n- اذا جيتوا تتدربوا حطوا لكم تايمر اول وثاني رايتنق 50د والفاينل رايتنق 75د لان كثير من الطلاب يشوف الوقت تحدي ولان اذا كان عدد الفقرات اقل من المطلوب يصير القريد F تلقائياً مهما كانت الكتابة ممتازة، فعودوا نفسكم من البداية تكتبوا ضمن الوقت المحدود. \n- استغلوا واستفيدوا من chat gpt بدون مبالغة قادر بعد الله يطلعكم من الظلمات الى النور، اسألوه وتناقشوا معاه اعطوه مقالاتكم وخليه يعطيكم فيدباك مفصل وخليه يساعدكم في تحسين كتابتكم. \n- لا تفوتوا اي فيدباك من الدكتور لان بيساعدكم تحسنوا كتابتكم واحضروا كل الpractice tests حتى لو كانت فترة مياجر لانهم بينفعوكم مرة ويهيئوكم على جو الاختبار فيقل التوتر. \n- لازم تخلوا آخر خمس دقايق للمراجعة، اوقات من التوتر او سرعة الكتابة نغلط في السبيلنق او قرامر فالمراجعة مهمة لتفادي مثل هذه الاخطاء.  \nوبس اتمنى قدرت افيدكم لا تنسوني ووالديّ من الدعاء ♥️","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/206539","user":"Ice_Ninja","ts":1734883283000,"mid":206539,"mids":[206539,222970,250768,332119]}}', 1734883283000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p210821-engl101', 'tg-kawtharmoh04', 'ENGL 101', 'info', '{"desc":"نصيحة للي بياخذو الكورس، من اول رايتنق بدعو لأن لو جبتو العيد بالاول مابيغيرو ليكم القريد الا اذا شافو تطور واو","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/210821","user":"kawtharmoh04","ts":1735042221000,"mid":210821}}', 1735042221000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p210848-engl101', 'tg-u939297715', 'ENGL 101', 'info', '{"desc":"تدربي على البورتفوليو كويس و تدربي ريدنق بشكل عام، و تدربي رايتنق لان حسيته طور لي الريدنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/210848","user":"","ts":1735042340000,"mid":210848}}', 1735042340000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p214876-engl101', 'tg-u1207539838', 'ENGL 101', 'info', '{"desc":"كل شوي خذ فيدباك من الدكتور \nلا تستهين وتذاكر على آخر لحظه للمد\nإذا تحس نفسك ضعيف بالريدنق تدررب","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/214876","user":"","ts":1735342573000,"mid":214876}}', 1735342573000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p215031-engl101', 'tg-u1823708596', 'ENGL 101', 'info', '{"desc":"انقلش ١٠١ سمعت كلام كثير عنه من ناحية الصعوبه ولكن ما أشوف الكلام كله واقعي ، الي أشوفه كل ما اجتهدت الواحد زياده بيحصل ثمار اجتهاده ، بكتب وش سويت في كل قسم وبعدها بكتب المصادر :   \n\n◾️الرايتنق تيست ✍️ : \nاول شي كنت اسويه اني انتبه للدكتور واشوف هو ايش الي يفضله وايش الي ما يفضله لأن هو اللي بيصحح لي الرايتنق الأول والثاني ( أما الفاينل دكتور غيره ) وهو كان يعطينا مواضيع ويخلينا نكتب عنها بعدين نسلم له اللي كتبناه ويعطينا فيدباك عليه يعني ما بتدخلون الرايتنق تيست الا وانتم عارفين وش اخطائكم + مهم انكم تفتحون الروبريك اللي هو المتطلبات حق كل رايتنق مكتوبة لك بالتفصيل وكل الدكاترة يعتمدون عليها بالتصحيح ف لازم تطبق كل شي مكتوب عشان ما يخسف دكتوركم في قريدكم لأني أشوفه اهم شيء تكتبون كل المتطلبات الي في الروبريك.\n\n◾️الميد والفاينل 🥇: \nسهل إذا تدربنا عليهم من اول وهو عبارة عن قرامر و فوكاب و ريدنق بدون لسننق - أنا ترجمت كل الفوكاب واحفظهم مع المعنى الي جنب كل كلمة ترا مهم لأن في الاختبار يجيبون لك المعنى وتختار المصطلح ، والقرامر في سلايدات ينزلها القسم للكل ذاكروها وإذا ما فهمتوا عليها تابعوا مقطع من اليوتيوب لها أو شوفوا كتاب التوفل إذا كانت نفس السكيلز ممكن يكون أوضح لكم ، بعد ما تخلصون حلوا براكتس لانه يجي نفس الطريقة ومرات يجي من التدريبات الي برسلهم نفسه أو مشابه له لدرجة كبيرة.\n\n◾️الريدنق بروتفوليو 📜: \nهذا كان واجب عليه خمس درجات وفيه بعد رايتنق بروتفوليو عليه خمس درجات بس حالياً شالوا كل الدرجات الي عليه وصار ما عليه درجات وودوا درجاته الى الميد والفانيل ، طبعاً الريدنق بروتفوليو مهم انكم تفهمونه ومفروض دكتوركم يطلب منكم انكم تسوونه وحتى لو ما عليه درجات عشان بيكون فيه 4 قطع وبيجي وحده منها مشابه مره لها في الميد (من text 1-4) والفاينل نفس الشيء (من text 5-8) وبرسلكم حلول له ممكن تساعدكم ، لا تستهينون بأهمية الريدنق بروتفوليو جد مره مره مره مهم تفهمونه قبل تختبرون للميد والفاينل.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/215031","user":"","ts":1735475379000,"mid":215031}}', 1735475379000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p215896-engl101', 'tg-d_s335', 'ENGL 101', 'info', '{"desc":"تجربتي الشخصية بالمادة :\n\nهل فعلا صعب تجيب قريد بانقلش 101 مثل ما يقولون؟ الحقيقة لاء\nصحيح الكورس غثيث شوي بس مع شوية اهتمام تقدر تحصل قريد مُرضي\n\nبشكل عام الكورس ما يحتاج مذاكرة يومية ابدا، بس اوقات الرايتنق تاسكس والميد والفاينل ومافي اي بروجكت او اسايمنت انت مُلزم تسويه(كله اوبشينال)\n\nالرايتنق :\nاساس الكورس طبعا، واهم اهم شي تتبع الstructure المطلوب اهم من افكارك او من القرامر والفوكاب واي شي ثاني\n\n\nقبل الرايتنق براكتس كنت بس امُر على السلايدات عالسريع واشوف ال summary واخذ فكرة عن الي رح اكتبه\nوبعدين قبل ما ارسل draft 3 اعدل عليه كويس واحاول اخليه افضل ما عندي عشان يكون الفيد باك الي بيعطيه الدكتور حقيقي ويفيدني فعلا باشياء ما كنت منتبهة لها، وفيها كلها كنت لما افتح الفيد باك القى الدكتور مو تارك جملة الا وعليها ملاحظات☺️💔 بس شي كويس يعني عشان استفيد  \n\n\nقبل الرايتنق تاسك باسبوع او اقل كنت افتح السلايدات وابدا اشوف الستركتشر حق الرايتنق وايش اهم الاشياء المطلوبة، واشوف ال structure summary\nبعدها ابدا اتدرب على الكتابة، بالغالب اكتب من المواضيع نفسها الي جت بالبراكتس او اقول لشات يعطيني مواضيع، كنت اكتب بالعادة ٤-٥ مقالات\n\n\nمن اكبر الاخطاء الي سويتها بالرايتنق الاول شيئين : \n\n- اني خليت شات يقيم كتابتي،  لا تسوي كذا ابداا لانو شات بيقيم حسب معايير عالية حتى لو ارسلتله ال rubric ، كنت غالبا حسب تقييمه اخذ D وافضل درجة اعطاني ياها C وتحطمت طبعا فلا تسوي كذا ابداا\n\n-اني لما كنت اتدرب غالبا ما كنت اشغل مؤقت، او انو اخلي المؤقت بس للكتابة بدون ما احسب وقت ال planning وهذا برضو شي جدا خاطئ وبالرايتنق تاسك داهمني الوقت للاسف، صح كتبت كل شي مطلوب بس ما لحقت اراجع ولا اعدل على شي، فباختصار وانت تتدرب ضروري تشغل مؤقت وتحسب حساب وقت التفكير\n\n\nالميد والفاينل : \n\nاكثر شيئين ممكن تضمنهم فذاكرهم كويسس\n\nبالنسبة للريدنق كنت اقرا الريدنق بوتفوليوز الي داخلة معنا واحل الاسئلة براسي على السريع(لاني مثل ما ذكرت ما كنت احلهم وارسلهم بوقتهم) واشوف انو هالشي كان كافي بالنسبة لي صراحة، الريدنق بشكل عام مهارة تحتاج وقت عشان تطورها وقراءتي للبورتفوليو كانت بس عشان اخذ فكرة ولا بالاختبار كنت اعتمد على معرفتي السابقة بالريدنق، اما اذا انت شخص تعرف انو مهارة الريدنق عندك ضعيفة فحاول تقرا باستمرار وتطورها خلال الكورس\n\nالقرامر ذاكرت السلايدات كويسس وحليت كويزات القرامر كلها وبس ما حليت اي شي ثاني، وكنت اذا غلطت بسؤال احفظه عندي وارجع اراجعه بعدين واركز على الخطا\nاما قسم تحديد الخطا ما كنت اذاكره بشكل منفصل، كنت اعتمد عالسينس (اكيد مو افضل شي تسويه)\n\nالفوكاب كنت اذاكر ال AWL كويسس ، اغلب الكلمات كنت اعرفها سابقا فما كان صعب كنت بس احفظ الجديد ، وكنت استخذم كويز ليت عشان اراجعه\nواخر شي قبل الاختبار ادخل احل اختبار تجريبي بس عشان اخذ فكرة عن شكل الاختبار\n\nمذاكرة الميد والفاينل (غير الرايتنق حقه) كانت تاخذ يومين-ثلاثة بالكثير\n\nالفاينل اصعب تجيب فيه قريد عالي لانو كل سؤال عليه درجات كثير فسهل تنخسف فيه ، فحاول تضمن قد ما تقدر من الدرجات بانك تذاكر كويس\n\n\nبالنهاية لا تسمع كلام الي يقولك الكورس صعب وصعب تجيب فيه قريد، اكيد لكل مجتهد نصيب\n\nاعتذر على الاطالة، وبالتوفيق جميعا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/215896","user":"d_s335","ts":1736505784000,"mid":215896}}', 1736505784000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p217593-engl101', 'tg-u1919185988', 'ENGL 101', 'info', '{"desc":"تقرين essay وتحددين المعلومات المهمه فيه وتكتبين ملاحظاتك على جنب والخ ،وبعدها تجاوبين على اسئلة موجودة تحته، ما عليه درجات بس الافكار اللي بالقطع يجي مشابه لها بالريدنق حق الميد والفاينل + تستفيدين من المواضيع والمفردات لما تجين تكتبين essays","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/217593","user":"","ts":1737037394000,"mid":217593}}', 1737037394000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p218309-engl101', 'tg-u7321281131', 'ENGL 101', 'info', '{"desc":"للرايتنق ذاكر الريدنق بورتفوليو \nو للفوكاب احفظ اللست \nو القرامر فيه تدريبات تدرب كثير \nالمدة على حسب الشخص\n\nفرق بينهم ما تقدر تقارن يعني\n١٠١ كله يعتمد على الكتابة \nإذا مستواك عالي كتابة بتشوفوه سهل\n لكن ٠٤ قرامر و فوكاب و ريدنق \nفا حتى لو ما تعرف تكتب تقدر تجيب قريد","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/218309","user":"","ts":1737446162000,"mid":218309,"mids":[218309,219672]}}', 1737446162000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p221251-engl101', 'tg-sa9dy', 'ENGL 101', 'info', '{"desc":"اذا كتبت 47 بالانترو غالبا انك ما تكلمت كفاية عن  ال general information وبس دخلت عالموضوع مباشرة بدون ما تسوي تمهيد \nاذا كتبت 47 بالبودي براقرافز غالبا انك ما شرحت كفاية عن السبب حقك او معلوماتك سطحية ومافي افكار اعمق \nاذا كتبت 47 بالخاتمة غالبا انك بزيادة لخصت البودي براقرافز ولخصتهم بجملة وحدة بدل ما تلخص كل بودي بجملة كاملة\n\nالريدنق ما احس يحتاج له وقت كثير بس تحتاج تفهم القطع كويس وتأكد انك فاهم اي فوكاب جديد بالقطع، يمكن ساعتين يعني ما ياخذ يوم حتى من وجهة نظري\n\nاول شي بتختبرون قرامر وفوكاب وريدنق ذول ٦٠ دقيقة، بعدها اعتقد في عشرة دقائق بريك او شي كذا على بال ما يجمعوا الاوراق، بعدها الرايتنق ٧٥ دقيقة لانكم بتكتبوا ٥ براقرافات\n\nالرايتنق تاسكس بذا الكورس ما تفرق بالقريد، تقريبا الميد هو يحدد القريد الي بتجيبه بالنهاية\nانا عيدت بالرايتنق وجبت درجة كويسة بالميد وشديت حيلي بالفاينل وجبت قريد عالي بالنهاية حسبة قريداتي كانت بوسط رينج قريد الميد وبداية القريد الي بعده، اذا تقدرون تشدون حيلكم بالميد تقريبا ثلاث ارباع هم القريد بذي المادة بيروح\n\nالاغلب ينرفع قريده بالفاينل حق الرايتنق عن الرايتنق تاسكس الي بالكلاس \nما دامك مو مسوي غلط كارثي غالبا بتطلع بقريد اعلى من الي بالكلاس","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/221251","user":"sa9dy","ts":1739648043000,"mid":221251,"mids":[221251,222399,236192,322254,322261]}}', 1739648043000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p221379-engl101', 'tg-herolookingforthebest', 'ENGL 101', 'info', '{"desc":"دكتورنا قال عشان تكونوا في الأمان اكتبوا فوق ٣٠٠ كلمة \nلكن كحد ادنى لازم ٢٥٠ كلمة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/221379","user":"herolookingforthebest","ts":1739722894000,"mid":221379}}', 1739722894000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p222142-engl101', 'tg-u873533917', 'ENGL 101', 'info', '{"desc":"انا اذكر دكتورنا قال اذا موضوعك revealed تكلم بالباكقراوند عن الموضوع عمومًا، اذا stated حاول تحصر الموضوع اكثر للايجنت حقك بس برضوا لا زال بإطار العموم\n\nواعتقد هذا الي سويتيه يعني\nshopping له علاقه بالايجنت\nبينما عام بزياده buying مثلا\n\nFor WT1, you will see four letter grades for Response to question, Structure/organization, Vocabulary, and Language Use. The 5th grade on the right is the total.\nFor the MTE, you will see three letter grades for Reading, Vocabulary and Grammar. The 4th grade on the right is the total.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/222142","user":"","ts":1740152981000,"mid":222142,"mids":[222142,232837]}}', 1740152981000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p224865-engl101', 'tg-whmk1', 'ENGL 101', 'info', '{"desc":"الفوكاب من اللستة احفظ التعاريف نسخ لصق بتجي بالمد\n\nالقرامر من 1 الى 8 بالبلاك بورد\n\nالريدينق بورتفوليو الي محددينه لكم، الترم الماضي جانا موضوع اللحم والسيارات الكهربائية\n\nالقرامر تحدد الخطأ بالجملة، بيكون كأنه رايتنق تاسك 1 بس انتم تصححوه واذا الجملة مافيها اي خطأ تختاروا الخيار E\n\nانتبه للوقت، الريدينق اهم من الفوكاب والقرامر لأن نقاطه مدبلة، لكن ذلك ما يعني انك تهمل الفوكاب والقرامر عشان الريدنق لا، قسم الوقت واعطي: \n\nالريدينق 50 دقيقة (كل سؤال دقيقتين) \nالفوكاب والقرامر 40 دقيقة (يمديك تقلل الوقت ذا اكثر وتزيد الريدينق لأن الفوكاب يمديك تخلصه بسرعة لو حفظت اللستة) \n\nهذي كانت طريقتي يمديك تسويها لو تبي ولكن يمديك تقسم الوقت باللي انت تشوفه مناسب لك، اهم شي تعطي الريدينق حقه \n\n🛑 *لا تحقد على اي سؤال قرامر او فوكاب او ريدينق، لو ما عرفته روح اللي بعده*","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/224865","user":"WHMK1","ts":1740710715000,"mid":224865,"mids":[224865,224883,224958]}}', 1740710715000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p229637-engl101', 'tg-uranus_15', 'ENGL 101', 'info', '{"desc":"كيف تحل الريدنق؟ أنا شخصيًّا أشيك عالأسئلة عالسريع وأشوف فقرة a مثلًا كم سؤال عليها، ثم أقرا ذي الفقرة بس، وأحل أسئلتها، وأمشي كذا فقرة فقرة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/229637","user":"Uranus_15","ts":1741099189000,"mid":229637}}', 1741099189000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p230972-engl101', 'tg-liillllililli', 'ENGL 101', 'info', '{"desc":"الريدنق السؤال بدرجتين والفوكاب والقرامر بدرجة وحدة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/230972","user":"liillllililli","ts":1741122164000,"mid":230972}}', 1741122164000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p232343-engl101', 'tg-nxnxc1', 'ENGL 101', 'info', '{"desc":"A+ 24/25 \nA 22/23\nB+ 21\nB 20 \nC+ 18/19\nC 17\nD+ 16 \nD 15\nتحت 15 = F\n\nاعادة صياغة للثيسس\nجملة تلخيص الفكرة الرئيسية لبودي١\nجملة تلخيص الفكرة الرئيسة لبودي٢\nكونكلودنق ريمارك(نصيحة-سترونق-فيوتشر)","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/232343","user":"nxnxc1","ts":1741257619000,"mid":232343,"mids":[232343,236967]}}', 1741257619000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p233886-engl101', 'tg-wonderful_f', 'ENGL 101', 'info', '{"desc":"على حسب الفوكاب والقرامر 1 على كل سؤال والريدنق 2 \n\nA+ /  13.95-15\nA / 13.5-13.8 \nB+ / 12.75-13.35 \nB / 12-12.6\nC+/ 11.25-11.85\nC/ 10.5-11.1\nD+/  9.75-10.35\nD/ 9 - 9.6\nF/0-8.9","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/233886","user":"Wonderful_F","ts":1741273671000,"mid":233886}}', 1741273671000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p236229-engl101', 'tg-y_7iq0', 'ENGL 101', 'info', '{"desc":"موضوع الوقت من أصعب التحديات في اختبار الرايتنق لأن يتطلب منك جودة في وقت محدود\n \nلذلك من الأمور اللي ممكن تساعد التدريب على الوقت حق الاختبار يعني تكتب وقت ما تدرب كأنك في الاختبار  و تحط لك وقت \n\nوقت الاختبار مهم إنك تخطط قبل لا تبدأ تكتب يعني تكون عندك خطة واضحة و عارف وش بتسوي  لأن لو بديت كذا بس بدون ما تخطط و لا شي في الغالب بتوقف في النص و يمكن تضطر تمسح و تضيع وقتك فيُفضّل تكون عندك خطة قبل الكتابة\n\nشي ثاني هو عدم المبالغة يعني نقول مثلا انت في البودي طبعاً تحاول تخلي الجمل متراكبة بشكل صحيح و يكون فيها فلو لكن لا تاخذ وقت واجد في محاولة إيجاد أفضل كلمة مثلا على حساب الكونكلوجن مثلا \nلأن لو ما كملت الكونكلوجن و كتبت كلمات أحسن في البودي في الغالب بتنقص أكثر من لو كتبت كلمات جيدة لكن في أفضل و الكونكلوجن حقك كامل\n\nالقرامر نفسه\nالفوكاب 4-6\nالريدنق تكست واحد من البوتفوليو من 5-8\nالرايتنق أقل شي واحد من 1-8\n\nورقي \n\nالريدنق في الميد بكون عندك نصين \nواحد منهم على الأقل من البورتفوليوز \nطبعاً ما بكون نفسه بالضبط بكون مختلف واجد لكن نفس الموضوع \n\nالفاينل بكون ريدنق واحد بس و من البورتفوليوز\n\nالفاينل رايتنق مكون من ثلاثة برومبتس \nواحد منهم على الأقل من البورتفوليوز ( 8 - 1 )  \nالباقي ممكن يكونوا من برا و ممكن يكونوا منهم","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/236229","user":"y_7iq0","ts":1742053149000,"mid":236229,"mids":[236229,245569,251200,252571]}}', 1742053149000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p239378-engl101', 'tg-le8h0', 'ENGL 101', 'info', '{"desc":"مو شرط يكون قريد واحد يمكن تكون اكثر بعد \nوالسبب الساكشن كلها الطلبة الي مايجيهم ابقريد بسبب انهم خالفوا الشروط الابقريد حقتهم نسبتها تتوزع على بقية الطلاب ففيه احتمالية الابقريد حقك يكون اكثر وفيه ناس اعرفهم فالانجلش بسبب الابقريد طلعوا من B+ الى A+ كانت درجته 89 ودفه الابقريد 3 قريدز زيادة فمعليك راح تنبسطي بالابقريد لاتشيلين همه والابقريد الي يجيك يختلف من ترم لترم على حسب شعبتك وعلى حسب مجموع عدد الطلاب الي يجيهم ابقريد\n\nانا اقصد الابقريد بيزودك درجتين\nبس الافرج ممكن يرفعك لقريد اعلى \nدكتوري يقولي فيه طلاب كانوا B+\nومع الابقريد والافرج على حظهم جابوا A+ قالي نادر تصير بس وارده\nرحت لدكتوري وجلس يوريني درجاتي ووراني اياهم في حال الابقريد والافرج وقالي لو انت محظوظ بترتفع قريدين كله على حسب الافرج\n\nFor your counter argument to sound clear and actually verify that your position is more convincing, you should try to be certain about your position in your sentence. You sounded a bit hesitant and that’s actually made your counter argument a little bit weaker than it should be\n-\nIn my opinion, a better approach would be:\n-\n\nهذي جزئية من احد الدرافتات الي سويتها ودكتوري شافها وقال كويسة واستمر على هالنمط لعلها تفيدك فب كيف تكتبين الكنكلوشن للكاونتر\n-\nSome may argue that students can be creative regardless of the number of exams they have to take. They mention that creativity is inspired through stressful exams where the brain have to challenge itself to extract information. While this is true to some degree, the human body releases certain chemicals, such as cortisol, to manage high levels of stress. Being in a state of stress actually makes it brutally challenging for the brain to function clearly. If the brain were to generate new ideas during intense conditions, it would easily get affected by the hormonal balance caused by stress. Thus, being able to develop advanced thinking under exam conditions is nearly impossible.\nلو تلاحظين بالكنكلوشن كأني انهيت النقاش وحسمت هذا الي الدكاتره يطلبونه منك\nيطلب منك لمن يقرا الكاونتر حقك يقراه ويشوف ان كلامك قاعد ينفي الكلام وبقوة مب ينفيه بس فيه شك بسيط وهالشيء تعرفه من الtone بالرايتنق فحاول تكون لغتك صريحة وقوية كلمات مثل it can be \nهذي جداً كويسة بأماكن ثانية الا الكنكلوشن للكاونتر بالكاونتر مالك الا رفيق دربك should واستعمل معها كلمات تعزز من موقفك مثل inherently \nSignificantly\nمثال لو عندك كاونتر موقفه قوي بس مثالي وصعب يتطبق بالواقع\nThis is only applicable in perfect conditios which is not practical in the real world\nبالطريقة هذي انا اثبت نقطة ضعف في الطرف الاخر وهذا هو اساس الكاونتر اريقومنت\n\nGrammar \nVocab \nزي الاوريا بالضبط\nاللهم فالقرامر بيزيدون عليك انهم يعطونك قطعة طويلة وتبدا تطلع الاخطاء الي فيها ومب ذيك الصعبة غالباً الاخطاء تكون واضحة وتقدر تطلعها لو تدربت عليهم كويس\nReading\nبورتفوليو صديقك الصدوق هو قطعة طويلة ومعها اسئلة كثير يساعدك تبني عندك مهاراة الريدنق والبورتفوليو ماعليه درجاتت بس هو الي بيرفع درجتك بالريدنق لو اعطيته الوقت وفهمته كويس\nWriting\nالكورس كله رايتنق ودرجاتك نصها على ظهر الرايتنق وفهالكورس بتكتب كثييير والرايتنق يحتاج له تدريب وصبر لنه مهارة صعبة ومب بسرعة تتقنها لكن لو مشيت مع السيلابوس والدكتور وجلست تتدرب وتاخذ فيدباك من الدكتور امورك طيبة وبتبدع ان شاء الله بالرايتنق\nاهم شي بهالكورس لاتكسل فيه ولاتشوفه مستحيل بس يحتاج له من يحط الوقت والجهد\nاول رايتنق جبت C وتوقعت الكورس هذا نهايته سيئة وان الكورس مب لي لكن بعد ماتعمقنا بالكورس عرفت كيف اتدرب وعرفت اكيف اطور بكتابتي وبمهارة الريدنق والحمدلله طلعت من هالمادة بقريد A\nعادي تعيد بالرايتنق الاول وتسوي كوم باك اهم شي انك تعطي كل مافيك لهالمادة وصدقني بتنصدم كيف بيثمر تعبك\n-\nاكثر شي تعبني بهالكورس مب الرايتنق ولا الاختبارات\nاكثر شي تعبني مهما اكتب رايتنق واحاول اتطور دايم دايم ااغلط نفس الغلط وارجع للدكتور ونفس الفيد باك وهذا كابوس الرايتنق انك تحتاج تعصر نفسك لين تبدا تجلد فيه وهذا الي سويته بالفاينل كثفت التدريب بشكل مجنون وفرق كثير بالقريدز الحمدلله\n-\nاتمنى كلامي يفيد احد بينزل الكورس الترم الجاي والي عنده اي استفسار لاينحرج يسألني","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/239378","user":"le8h0","ts":1744967757000,"mid":239378,"mids":[239378,243843,245108,250521]}}', 1744967757000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p240097-engl101', 'tg-bo_wso', 'ENGL 101', 'info', '{"desc":"اي \nاول شيء نختبر نفس جزئية الميد  ريدنق فوكاب قرامر\nبعدين بريك ربع ساعة بعدين رايتنق الاخير عليه ٢٥٪؜ \nArgumentative essay\n\nضروري تعرفين دكتورك شنو يحب وشنو يعجبه وما يعجبه في الكتابة وكل شوي تمري عليه الاوفس اور عشان تطلعي بأفضل قريد ممكن","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/240097","user":"Bo_Wso","ts":1745621387000,"mid":240097,"mids":[240097,240103]}}', 1745621387000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p243782-engl101', 'tg-theflopologist', 'ENGL 101', 'info', '{"desc":"مع أو ضد التحول الى السيارات الكهربائية في السعودية \nمع أو ضد العمل مع شركة في البيت \nمع أو استخدام الدراجات بدلاً من السيارات في التنقل او انه كان عن ان السعودية تخلي طرقها صالحة للمشي والتنقل بالدراجات شي كذا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/243782","user":"TheFlopologist","ts":1747141417000,"mid":243782}}', 1747141417000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p244835-engl101', 'tg-writtenbymu', 'ENGL 101', 'info', '{"desc":"الاسئله تجي بالترتيب، حاول تقرا الاسئله الاولى اللي تتعلق ببرقراف A عشان تحطهم ببالك ولو فيه وقت تسوي scanning للخيارات عشان تفهم انت وش قاعد تدور عليه، ثم تبدا تقرا البرقراف وتحاول ماتهوجس بنص القراءه عشان ماتفوت معلومات مهمه ممكن تغير من اختيارك للاجابه الصحيحه\nونفس الشي للبرقرافات الباقيه\nوايضا لو انت شخص يداهمك الوقت، حاول تبدا بالاسئله السهله مثل معاني كلمات وكذا عشان حرام يضيعون عليك لو مابقى لك وقت","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/244835","user":"writtenbymu","ts":1747165701000,"mid":244835}}', 1747165701000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p250753-engl101', 'tg-ghazialharbi_1', 'ENGL 101', 'info', '{"desc":"ثلاث كلاسات بالاسبوع\nتركيز اكبر على الرايتنق من ناحية طرح الافكار وشرحها\nالريدنق اكثر صعوبة فيبيله تدريب \nالفوكاب والقرامر بسيطين بالذات الي درسوا الاوربا على كلام دكتورنا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/250753","user":"GhaziAlharbi_1","ts":1748440812000,"mid":250753}}', 1748440812000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p256144-engl101', 'tg-u5140129757', 'ENGL 101', 'info', '{"desc":"في الميد راح يكون عندك نصين الأول راح يكون من البورتفوليو ( النصوص ألي عطوكم ) و الثاني راح يكون أول مره تشوفه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/256144","user":"","ts":1756302626000,"mid":256144}}', 1756302626000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p256314-engl101', 'tg-enwowlfmne', 'ENGL 101', 'info', '{"desc":"ياجماعة فكروا بالرايتنق انكم تخلون كلامكم انسيابي بالنسبة لكم ، لاتحاولون تتبعون سوالف ٤ جمل ٥ جمل اكتب الي تحسه اضبط وبتجيب قريد احسن \n\nاذكر في رايتنق تو كتبت الكونكلوجن ٩ سطور ( اكثر من البودي والانترو سوا )","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/256314","user":"Enwowlfmne","ts":1756312395000,"mid":256314}}', 1756312395000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p256530-engl101', 'tg-mariya_20051', 'ENGL 101', 'info', '{"desc":"Attendance: Regular attendance is a university requirement; hence attendance will be checked each lecture and lab. Missing more than 6 lectures or three or more unexcused labs will result in a DN grade without prior warning. To avoid being considered as absent, an official excuse must be shown no later than one week of returning to classes.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/256530","user":"mariya_20051","ts":1756363485000,"mid":256530}}', 1756363485000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p257125-engl101', 'tg-ha_730', 'ENGL 101', 'info', '{"desc":"ريدينق \nقبل الميد بيكون فيه ملفين و وحده من الفقرات بتكون مقاربه ل وحده بتجي بالميد \nو نفس الشي مع الفاينل بيكون فيه ملفين جديده \nما عليه درجات بس يفضل تسويه لانه بيفرق ب ادائك بالميد و الفاينل","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/257125","user":"HA_730","ts":1756554133000,"mid":257125}}', 1756554133000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p257749-engl101', 'tg-u7365992466', 'ENGL 101', 'info', '{"desc":"ريدنق بورتفيليو تدرب\nفوكاب شوف البلاك بورد مايخرج عنه يقولون\nرايتنق مع دكتورك تدرب ويعطيك فيدباك\nالقرامر مدري صراحه ماظن بيشرحونه لكن كاني شفت لستة القرامر الي معنا فا تراجعها بس لانها اوريا كلها","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/257749","user":"","ts":1756755475000,"mid":257749}}', 1756755475000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p259655-engl101', 'tg-abo3abdxx', 'ENGL 101', 'info', '{"desc":"الي اعرفة ان WT بيكون اقل شي ٣٤٠ كلمة\nويمديك انك تجيب اشياء بديهه زي ان السيارات الكهربائية فيها فقط نوع واحد وأما البترول فيها انواع كثيره .\nوفيه مقارنات جدا كثيرة تكون بديهه ومب على شرط تكون ١٠٠% صح \nوالأفضل انك ما تكتب حقائق لأن الدكتور قد قال لنا انه لو كتبتوا حقائق عن شيء بنبحث عنها اذا كانت صحيحه او لا وإذا لا يخصمون الأفضل انك تتجنب الحقائق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/259655","user":"Abo3abdXX","ts":1757580954000,"mid":259655}}', 1757580954000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p264135-engl101', 'tg-baylasanmd', 'ENGL 101', 'info', '{"desc":"وعليكم السلام ورحمة الله وبركاته \nيجي في الميد والنهائي من مواضيع شبه الموجودة في البورتفوليو\nفلو حليت البورتفوليو بتكون تدربت على الكلمات او طريقة الحل لشئ مشابه بيجي في الاختبارات\n\nشوفي اكتبي على ورقة الاختبار كل طرق ال elaboration\nمثلا\nExplain\nExample\nCondition\nFurther effects ....\nالخ\nوشوفي الموضوع وشوفي شو الي بناسب موضوع من هدول \nرح تجي ببالك افكار وحتعرفي أنه مثلا هاد الموضوع بقدر اشرح عنه وجيب مثال وجيب condition\nوهيك يعني\n\nبشكل عام المادة تتكون من رايتنغ ورجرامر وفوكاب وريدينغ\nالرايتنغ بتلاقي في الردود Ice Structure فيها ملخص للرايتنغ وشرح عليه فيديو ، وفي ملخص كمان لو رجعت بالرسائل \nالفوكاب تترجم الكلمة وتتدرب على الاسئلة\nالجرامر اليوتيوب مليان اكتب اسم القاعدة والأمور تمشي\nالردينيغ تدريب كمان\n\nوعليكم السلام ورحمة الله وبركاته \nبتقدر تحسب قريدك من حاسبة القريدات\nويعطيك درجتك منمم وماكسمم\n\nوالابقريد له شروط مثلا لو كنت سي بلس ودرجتك فرق درجة وحدة بينها وبين ال بي ترتفع\nلو كانت درجتين ما تنرفع تبقى سي\nفيعني مو شرط الكل يحصل ابقريد\n\nلازم تشوف الستركتشر لكل نوع من انواع الرايتنغ\nوتشوف الروبريك ( الي هو طريقة تقييم وقريد الرايتنغ )\nوبعد هاد تتدرب كتييير وتاخد فيدباك من دكتورك وتطوره\nواستغل البراكتس تيست لانه يكشف نقاط ضعفك\n\nالفوكاب سلف ستدي من ال awl course\nالريدنغ والقرامر ممكن يتطرقوا له بس بشكل بسيط جدا\nفيعني ايوة كله سلف ستدي تقريبا\n\nشوف الهيلب سشن تبع ايس مفيدة\nفكرة الbrain storming تطلع اي شي يخطر في بالك عن الموضوع الي اخترته\nبشكل ما من الافكار الي كتبتها الي بتكون كلمة او كلمتين تقدر تحدد الاشياء الي بتكتبها ك background \nاشياء تنفع أسباب \nاشياء تنفع للelaboration الخ\n\nمو فكرة الدف\nالفكرة انه طالما دكتورك بصححلك فلما تروح اوفس اورز تفهم شو الأشياء الي يركز عليها ونصائحه بحيث الرايتنغ الي بعده تسوي الي يعجبه\n\nالملف تبع الفاينل مكتوب فيه اسم كل قاعدة\nاكتبها في يوتيوب وشوف شرح لها وبعدها اختبر الفورمز الي ينزلوها في بلاك\n\nشوف القائمة تبع القواعد لو بتحتاج تشوف شرح شوف\nوفيه ملخص للقواعد بالردود\nواخر شي حل الفورمز الموجود ببلاكبورد وقناة مفيدة\n\nReading portfolio \nملف فيه قطع reading وعليه أسئلة\nتقدر تدرب منها\n+ تجي نفس المواضيع بالميد والفاينل وواحد من الرايتنغ اذا ما خاب ظني\n\nبالميد بكون معكم من ١ ل ٤ الريدنغ\nوالفاينل من ٥ ل ٨\nالريدنغ الي حيجي بالاختبارين حيكون موضوع من مواضيع الريدنغ\nفانت لو حالل البورتفوليو وفاهمه كويس حتستفيد منه في الاختبار لانك حتكون فاهم المصطلحات وهالأمور\n\nالنقطة التانية انه بالفاينل بكون عندك ٣ مواضيع للكتابة \nوحدة من المواضيع بتجي من الريدنج بورتفوليو من ١ - ٨","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/264135","user":"BaylasanMd","ts":1759473670000,"mid":264135,"mids":[264135,312670,321661,331049,331195,332368,334319,343230,347459,349199,359218,359272]}}', 1759473670000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p264412-engl101', 'tg-lordsavesiraj', 'ENGL 101', 'info', '{"desc":"لاول يجيبو جمل وتحط فوكاب فيها الحين صار بيجيبو لك text كانه ريدنق وتختار الكلمه المناسبه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/264412","user":"Lordsavesiraj","ts":1759505245000,"mid":264412}}', 1759505245000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p265048-engl101', 'tg-alhum1', 'ENGL 101', 'info', '{"desc":"هي مافيه شي كذا تذاكرين و تجيبين a+\nبس الأشياء الاساسيه اهم شي تكونين حافظتها\n\nعدد الكلامات المطلوبه  \nلازم ثيسيس و ووش يتكون منه\nكلامات الربط تعرفين كم وحده عشان تنوعين\nتوبيك الي بالبودي وش يتكون منه و انه لازم ما تغيرين عن الموضوع التوبيك الخ \nو متطلبات الختام\n\nلو فهمتي ذول الباقي يقيمون أفكارك و استعمال الفوكاب و تركيب الجمل و كذا\n\nبالرايتنق تاسك خصوصا صعب ترسب بدرجه نازله مره\n\nلو درجه نازله و راسب معناته ما راجعت الستركشر او ما كملت مثلا 250 كلمه\n\nانا عن نفسي الحقيقه ماكان فيه وقت اعد بس كتبت صفحه و نص و أكثر شوي\n\nلا\nهو فيه حد اذا جبت F في respond to question\nاظن لازم كل شي ثاني أقصى حد D\n\nفا يقولون بعض الدكاتره انهم يشوفون باقي الاقسام ممتازه عند الطالب بس response to question  خايس و يستاهل رسوب بس يعطونه D عشان الباقي يمديهم يعطونه قريد كويس\n\nافتح السلايدات او المخلصات الي بالقروب هنا و حاول تفهم ولو فهم شوي سطحي\n\nبعدها ادخل على البلاك بتشوف يمكن فيه 5 كويزات قرامر ادخل و حلهم كلهم\n\nاي سؤال ما تعرفه اسال ابو جبت على طول\n\nالميد كان حرفيا نصخ لصق أفكار تقريبا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/265048","user":"alhum1","ts":1759693723000,"mid":265048,"mids":[265048,294532,298505,314114]}}', 1759693723000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p268378-engl101', 'tg-sh77nm', 'ENGL 101', 'info', '{"desc":"صراحة النظري كله ما حيفيدك كثير سوي براكتيس و اكتب essays من مواضيع سنوات سابقة مثلا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/268378","user":"Sh77NM","ts":1759956207000,"mid":268378}}', 1759956207000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p268672-engl101', 'tg-d7masx', 'ENGL 101', 'info', '{"desc":"دكتوري اذكر يقول لا تقول رأيك عن شي افضل من الثاني الا بالخاتمه بالبودي فقط اذكر ان ذا الشي اثره إيجابي اكثر ولا فائدته اكبر لا تذكر افضل او اسوء\n\nمو كأنه في منهج كل الموجود فوكاب اعرف تعريفها ومرادفاتها وقرمر مر على الملخص حقه وتدرب عليهم واذا بقى وقت مر على ريدينق بورتفوليو\n\nما اتفق ابدا.\n مهما كان مستواك بالريدينق ماش يفضّل تعطيه حقه خصوصا انه عليه اغلب الدرجات ، والقرمر والفوكاب ترا ما ياخذون ذاك الوقت فيمدي انك تحل الاثنين بدون ما تضطر تشوز واحد منهم\n\nرأيي مو مبني على تيقن لكن اراهن اغلب الدكاتره يميلون للخسف عشان نظام الأفرج فما تقدر تحدد مستواك سيئ او لا ، لكن عموما اذا تبين تطورين كتابتك بأسرع طريقه انا اشوف افضل شي يمكن تسوينه انك تتدربين على موضوع قابل انه يجي مقارب له  ، وطبعا اذا بنتكلم عن مواضيع احتماليه تجي قريبه من افكارها فهي مواضيع الريدينق بورتفوليو تدربي عليها وخلي عندك ستركشر معين فيها وبإذن الله ترتفعين بالفاينل رايتنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/268672","user":"D7MASx","ts":1759963694000,"mid":268672,"mids":[268672,280627,297947,308007]}}', 1759963694000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p268845-engl101', 'tg-jsjiw91', 'ENGL 101', 'info', '{"desc":"✅ لا تكتب أقل من 4 فقرات أبدًا\n✅ استخدم أدوات الربط (first of all, in contrast, however, as a result, in conclusion, while, whereas)\n✅ لا تستخدم “I” أو “you” أو “we” أبدًا\n✅ حافظ على جمل قصيرة وواضحة\n✅ كل فقرة تتكلم عن فكرة واحدة فقط\n✅ استعمل علامات الترقيم صح (، . ; :)\n✅ لا تكرر كلمات كثيرة — استخدم مرادفات بسيطة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/268845","user":"Jsjiw91","ts":1759985155000,"mid":268845}}', 1759985155000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p270511-engl101', 'tg-xl68f', 'ENGL 101', 'info', '{"desc":"الفوكاب والقرامر الي حاطينه بالبلاك بورد كل شي يخص الفوكاب ذاكره مهما توقعت انه اجابتك صح والاختبار سهل الا ومايطلع فيه تريك بالسؤال والريدينغ تدرب برضو","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/270511","user":"Xl68f","ts":1759999509000,"mid":270511}}', 1759999509000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p270778-engl101', 'tg-ayx8s', 'ENGL 101', 'info', '{"desc":"ركزوا على ال agent حاولوا تغيروا عن kfupm students عشان يعطيكم اعلى بالنسبة الى ال critical thinking","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/270778","user":"ayx8s","ts":1760002078000,"mid":270778}}', 1760002078000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p273424-engl101', 'tg-r482838', 'ENGL 101', 'info', '{"desc":"مرات الجملات تكون واضحه جدًا انها قصيرة وترا نص اسئلة القرامر يجيب لك قطعه ويسالك وش الغلط في اغلب الاحيان تكون الجملة طويلة جدًا ومافيها فاصلات ف بتصير واضحه انها غلط ، والنوع الثاني من الاسئلة يجيك برضو بتكون في اغلب الاحيان جملة متوسطة الطول ووقتها تشوف اذا في داعي نضيف فاصلة ولا لا","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/273424","user":"R482838","ts":1760096012000,"mid":273424}}', 1760096012000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p273559-engl101', 'tg-u8465610952', 'ENGL 101', 'info', '{"desc":"ويت الفوكاب بيكون قسمين \n\nالاول. - يعطينا براقرافين كاملين وفيه فراغات وحنا نختار وش الكلمه المناسبه - ١٦ سؤال\n\nالثاني - يعطينا جمل منفرده وخيارات ونختار الكلمه المناسبه - ٩ اسئله \n\nمجموع الاسئله ٢٥ \n\nيعني مافيه شي زياده صح مو لازم احفظ تعريف كل جمله","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/273559","user":"","ts":1760099716000,"mid":273559}}', 1760099716000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p275141-engl101', 'tg-u8091994922', 'ENGL 101', 'info', '{"desc":"امسك ملفات القرامر وReading Portfolio والفوكاب من (Term 251: ENGL101 AWL In Action Course) . وسوي براكتس من Midterm exam and practice materials. كلهم في البلاك بورد","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/275141","user":"","ts":1760145513000,"mid":275141}}', 1760145513000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p275216-engl101', 'tg-r2nnl', 'ENGL 101', 'info', '{"desc":"ياخوان\nالقرامر ذاكرو ال8 ملفات اللي بالبلاك بورد\nبالاضافه الى القواعد اللي بالملف هذا ومب موجوده فالبلاك بورد\nتوي ارسلت للكورد وقال كلها معكم\n\nالريدنق قطعتين\nقطعه مختلفه كليًا بكلماتها وبكل حاجه\n\nاما القطعه الثانيه بتكون كلماتها والجمل اللي فيها مُشابهه لواحد من الاربع قطع في الريدنق بورتفليو\nماراح تجي نسخ لصق من البورتفليو كامله\nراح تكون مشابهه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/275216","user":"r2nnl","ts":1760164471000,"mid":275216,"mids":[275216,275272]}}', 1760164471000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p276071-engl101', 'tg-ke130666', 'ENGL 101', 'info', '{"desc":"عموما الميد الريدنق تذاكرون ال Reading portfolio\nالقرامر تذاكرون كل ال٨ ملفات بالبلاك وتدريبات البلاك والملف الي بالمثبتة \nالفوكاب من لست ١ للست ٣ وتدريباتها موجودة بالبلاك \n\nتقريبا ذا كلشي للميد اذا نسيت شي احد يضيف","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/276071","user":"ke130666","ts":1760197428000,"mid":276071}}', 1760197428000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
