INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p278146-engl101', 'tg-movsarevolv', 'ENGL 101', 'info', '{"desc":"من تجربة \nجمع الملفات كله و عطه جبت \nوقله اجمع كل الكلمات مع المعاني الموجودة في الملف و رقمها \n\nثم افتح المايك حقه وقله يحذف ارقام الكلمات الي انت عارفه\n\nغالبا بتصفى على عدد بين ٣٠ إلى ٥٠ بالكثير","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/278146","user":"Movsarevolv","ts":1760349911000,"mid":278146}}', 1760349911000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
