INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p300514-engl101', 'tg-mnmy1', 'ENGL 101', 'info', '{"desc":"العنوان يجيك بشكل عام وانت تقدر تحط ايجنت فيه ،، إذا حطيت فيه فئة معينة لازم تلتزم فيهم بكامل الرايتنق تقريبا ،، ممكن تقدر تعطي أمثله على ايجنت ثاني لكن بالأصل يكون الرايتنق عندك على ايجنت واحد ،، او تقدر تتكلم بشكل عام","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/300514","user":"mnmy1","ts":1762444644000,"mid":300514}}', 1762444644000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
