INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p309204-engl101', 'tg-kfupm_11', 'ENGL 101', 'info', '{"desc":"فيه ملف كانو  مجمعين فيه القواعد ذاكري منه وكل قاعده حطيها بجبت وخليه يشرحها وشوفي افهمي  التدريبات الي في الفورمز  \nشفت الاختبار زي مستواها \nارجعي حليهم وحطي السؤال الي ماعرفتي له في جبت وخليه يقول لك وش أسم القاعده\n\nتدرب على الريدنق برتفوليوا  اعتقد كذا اسمه \nوالقرامر الملخص الموجود هنا في القروب مع الفورمز \nالفوكاب ترجم الكلمات بنفسك وحل الكورس حقهم حق الفوكاب","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/309204","user":"kfupm_11","ts":1764788356000,"mid":309204,"mids":[309204,365688]}}', 1764788356000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p311513-engl101', 'tg-u1348775952', 'ENGL 101', 'info', '{"desc":"حسب السؤال\nكمان لمن مرات مايكون فيه بس انت تحاول تقنع فئه معينة\nمثلا تتكلم عن انه الحضور يكون اختياري لطلاب الجامعة\nانت هنا تتكلم عن طلاب الجامعة لكنك ماتقنعهم هم، انت تحاول تقنع مين؟ المسؤول الي حط قواعد الحضور او رئيس الجامعة او زي كذا\n\nتدرب لين ربي يفرجها\nأفهم القرامرز و الفوكاب كويس و لمن تحل حاول تقول انت بالضبط ليش حليته كذا وليش مو ذي الاجابة مو بس بالاحساس\nالريدنق في طرق واشياء تكلمو عنها هنا بس حاول تقرا البورتفوليو عشان تاخذ فكرة عن الموضوع حق الاختبار","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/311513","user":"","ts":1765380089000,"mid":311513,"mids":[311513,311854]}}', 1765380089000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
