INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p323767-engl101', 'tg-u1920647858', 'ENGL 101', 'info', '{"desc":"انا سكبت والصدق الإيجابيات عديدة أهمها اني خلصت مادتين ثقال في الاوريا وطلعت بقريد وارتحت منهم وغير ان دوام الانقلش مهلك جدا \nالسلبيات اللي واجهتني ان التوفل شفته حيل حيل سهل فهمي للغة ممتاز لكن ماعمري كتبت شي زي الخلق فيوم جيت الجبل حتى الثيسست ماكنت اعرف وش هي واعتقد هالشي ينشرح بالاوريا ويكونو كاتبين اشياء اكاديمية قبل لا يجو الجبل","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/323767","user":"","ts":1766511410000,"mid":323767}}', 1766511410000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
