INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p338431-engl101', 'tg-cist_177', 'ENGL 101', 'info', '{"desc":"نصيحتي لكم حاولوا تحلون الريدينق بكامل طاقتكم ولا تغلطون فيه ابد \nالقرامر سهالات تراه، نفس الامثلة اللي عطوكم \nالريدينق ثم الريدينق.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/338431","user":"cist_177","ts":1772560088000,"mid":338431}}', 1772560088000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p340043-engl101', 'tg-m74sm', 'ENGL 101', 'info', '{"desc":"دكتوري يقول الروبرك الجديد تغير فيه عدد الكلمات \nاقل من ٢٠٠ F \nلكن إذا تحت ٢٥٠ مش شرط تأخذ F تقدر تجيب D لو كانت كتابتك كويسه","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/340043","user":"M74sm","ts":1772701236000,"mid":340043}}', 1772701236000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p341092-engl101', 'tg-booooooooooooooooooooooo_1', 'ENGL 101', 'info', '{"desc":"Dear Students,\n\nNow that you have completed the midterm exam, I know many of you are anticipating the release of both your Writing Task 1 (WT1) grades and your midterm exam results in the coming days. Midterm exam results will be released on BlackBoard as Reading, Vocabulary, Grammar and Overall Letter Grade, in that order (e.g. A A A =A). WT1 results will be released as per the rubric (from Response to Question, to Language Use, plus an Overall summative letter grade; e.g. A A A A =A). Whenever grades are released, questions naturally follow. As you know, the English Language Department Policies and Procedures document was shared with you on Blackboard on the first day of the course, and you were asked to read it carefully. Some of the questions students raise at this stage are already addressed in that document. Nevertheless, this message clarifies two specific areas that I expect will generate the most questions: course/section averages and the type of feedback provided on assessments.\n\nFirst, many students are curious about how they performed in relation to their peers and what the class average might be. I recently raised this question in a meeting, and I was informed that the policy remains that averages are not shared with students. The only information provided is that overall class performance for ENGL101 at the end of the semester is expected to fall within the C to C+ range. Beyond that, no further details about averages will be released. While it is natural to compare yourself with others, what is more productive is to consider whether you are satisfied with your own grade. If you are satisfied, then your current level of preparation is appropriate. If you are not satisfied, that is a clear indication that greater effort or adjustment is needed to be done by you outside of class before the next writing task or the final exam. Please understand that there will be no additional information provided regarding class averages.\n\nSecond, many students understandably request detailed, individual feedback on summative assessments. It is important to distinguish between formative and summative assessment. A formative assessment is designed to form and improve your understanding; it provides feedback intended to guide development before a final evaluation. In contrast, a summative assessment represents the sum of your performance at a specific point in time and results in a grade. As stated in the ELD Policies and Procedures (Section 1.2.9, p. 4), “Midterm and final exams are secure and, therefore, not shown to students. The practice essays are formative.  The exams are for summative assessment, not formative” . This distinction explains why detailed, individualized feedback is not provided for these assessments. However, for WT1 you do receive four separate letter grades corresponding to the rubric categories. These letters align with published descriptors. For example, if you received a D in Language Use, you can review the D-level box and identify the grammatical and vocabulary characteristics described there. Similarly, if you earned a B in Structure and Organization, you can compare your work against the B-level expectations. In this way, the WT1 rubric functions as a self-diagnostic tool. If you would like clarification about a specific descriptor, you are welcome to bring focused questions to office hours. Additionally, before future assessments, you will again have further opportunities for formative feedback. To strengthen grammar and vocabulary in particular, please review the materials available on Blackboard Ultra, including the links to our custom GPT tools, which are designed to provide targeted practice and feedback.\n\nIn conclusion, class averages and specific feedback will not be provided for the MTE or WT1. I strongly encourage you to consult the Policies and Procedures document if you have questions about assessment policies and procedures.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/341092","user":"booooooooooooooooooooooo_1","ts":1772963320000,"mid":341092}}', 1772963320000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p342874-engl101', 'tg-adeebe', 'ENGL 101', 'info', '{"desc":"اتوفل اذا مره ميح بعد ما تعرف كيف تحل القطعه وعندك الاشياء البيسك روح البورتفوليو عشان تتعود على صعوبة الريدنق حقنا ولغة","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/342874","user":"adeebe","ts":1773134699000,"mid":342874}}', 1773134699000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p348719-engl101', 'tg-ennpa', 'ENGL 101', 'info', '{"desc":"As long as you have no absences for deductions, you are still eligible for an upgrade. That means you can have a maximum of 4 unexcused absences. If you have 5 unexcused absences, you lose 1% and you are no longer able to get an upgrade","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/348719","user":"Ennpa","ts":1778243367000,"mid":348719}}', 1778243367000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p349300-engl101', 'tg-lam_0o0', 'ENGL 101', 'info', '{"desc":"يا جماعة ،أنا جربت طريقة في الكتابة خلتني اكتب بسرعة و حسنت مستواي و بقي عندي وقت في النهاية كمان، بإختصار خدوا وقتكم في التخطيط و اكتبوا كل الأفكار و النقاط الي رح تكتبوها بالتفصيل و بالترتيب  (عادي لو اخد التخطيط ١٣ دقيقة)يصير بعدها ما يحتاج تفكروا ،بس تكتبوا،بذي الطريقة تقدروا ركزوا على القواعد و الإملاء و هذي الأمور.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/349300","user":"lam_0o0","ts":1778365384000,"mid":349300}}', 1778365384000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p349402-engl101', 'tg-i426_3', 'ENGL 101', 'info', '{"desc":"الريدنق بس اخر ٤\n\n\nالرايتنق بتجي ثلاث مواضيع تختاري منهم\n\nواحد من المواضيع بيكون مقتبس من ال٨ قطع","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/349402","user":"i426_3","ts":1778407817000,"mid":349402}}', 1778407817000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p356003-engl101', 'tg-frot91', 'ENGL 101', 'info', '{"desc":"الميد قطعتين و الفاينل قطعه وحده\nالوقت هو نفسه حق الاختبار كله يعني قسم وقتك انت بين الفوكاب و القرامر","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/356003","user":"frot91","ts":1779277857000,"mid":356003}}', 1779277857000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p357732-engl101', 'tg-inlo5', 'ENGL 101', 'info', '{"desc":"ENGL 101 252\ninstructor: تايلور\ngrade A\nwt1 : A\nwt2: C+\nwt3:A+\nMIDTERM MCQ: A\nFINAL MCQ:A+\n\nتجربتي غريبه جدا ومختلفه عن اغلب تجارب الطلاب الي جايبين قريدات عاليه\n\nاولا مستواي اساسا في الانقلش قوي جدا وجاي من 05 و صار اقوى\n\nبالنسبه لقسم الرايتينق كلها الثلاثه ما عطيتها حقها ولا بذلت مجهود قوي\nشفت كلام التجارب السابقه الي يقلك تبي قريد عالي وتتطور طارد الدكتور وخله يقيمك عشان يعرف انك مهتم وكذا؟ ما سويت ولا شيء منه حتى شات جبت نادر ما كنت اخليه يقيمني ولو قيمني غالبا ما اتعلم من اخطائي. فقط الي كنت اسويه افهم الستركشر كامل هذا اهم شيء لو تبي تضمن قريد مقبول. اول رايتينق تدربت عليه شوي وعطيته حقه مقارنه بالبقيه\nالثاني تدربت شوي بس اقل بكثير من الاول ممكن كتبت ٤ مقالات\nالثالث  الرايتيتق الوحيد الي ما تدربت عليه ابدا حرفيا مره وحده وفي الكلاس في التدريب فقط !! ومع ذلك A+ بس كنت فاهم الستركشر جدا لاني اركز مع تايلور شرحه ممتاز برايي\n\nشيء لاحظته في الرايتينق الاول والثالث هو اني كتبت مثالين كان لها علاقه مباشره جدا جدا مع الموضوع. اول رايتينق مثلا موضوعي كان هل الافضل للطلاب يتابعون رياضات وكوره وكذا في الملعب او على الشاشه؟ انا قلت الافضل في الشاشه عشان توفير وقت وفلوس و الايجنت حقي كان طلاب البترول. وذكرت مثال ان طلاب البترول يمديهم يتابعون مباريات في شاشه المول وما يحتاج يروحون الملعب. هذا المثال جدا جدا مباشر ومرتبط بموضوعي و واقعي بالفعل تقدر تشوفه اذا رحت المول فيه ناس تتابع و احس انه رفع قريدي بشكل قوي\nبالنسبه للرايتيق الثالث اخترت موضوع ان الجامعات لازم تركز على تطوير المهارات الناعمه للطلاب واتفقت مع الراي ذا. وقلت من ضمن الاسباب ان الطلاب اذا تعلموا مهارات ناعمه يقدرون يتنقلون بين المناصب و الوظائف وذكرت مثال مهاره الاداره.وذكرت مثال على ذا الشيء الدكتور غازي القصيبي رحمه الله كمثال على شخص تنوع بين الوظائف والمناصب بسبب مهارته في الاداره. مثال مباشر جدا جدا ومرتبط بالموضوع وقدرت اربطه بشكل جميل جدا مع الراي.\n\nقد يكون سبب قريدي العالي في الرايتيق الاول والثالث هو هذا الشيء وعلى عكس الثاني تماما ما سويت كذا.\n\nبالنسبه للمد والفاينل Mcq ذاكرتهم في يومين الى ٤ ايام اعتمدت بشكل كامل جدا على مستواي بسبب التوفل اغلب القرامر كانت منه فما تعبت معه\n\nما عندي كلام كثير في تجربتي لاني اعتمدت على لغتي بشكل عام","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/357732","user":"inlo5","ts":1779313762000,"mid":357732}}', 1779313762000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p359214-engl101', 'tg-dwtby', 'ENGL 101', 'info', '{"desc":"Term: 241 \nGrade: A \nالدكتور: Lance King \n\nبالنسبة للدكتور:\n\nاسلوب: من أفضل أساتذة انقلش١٠١، طريقة شرحه ممتازة لدرجة كان يقترح تعديلات عالسلايدات عالكورد و يعدلها عشان يستفيدون طلاب الكورس الباقي، \nالكلاس عنده خفيف ماتحسو بالوقت، بشوش و خلوق أهم شيء.  \n\nفيدباك: كنت أروح له بالايسايز حقتي في الاوفيس الاور و يعطي فيدباك من قلب و ما يقصر أبد، بس ما يعطي قريد على شغلك بحكم انه ممنوع.  \n\nدرجات: ما أعرف بس أظن إنه عطاني حقي.  \n\nتحضير: يحط الباركود عاللاب عالمكتب لين يطفى لحاله، أحيانًا كنت أتأخر و أعتذر و يحضرني نهاية الكلاس و أحيانًا كان يحطني ليت بس كان متفهم أغلب الوقت. \n\nيستاهل تخربون جداولكم و تضحون عشان تنزلون عنده 👍🏻\n\nبالنسبة لتجربتي في الكورس:\n\nرايتنق ١ ما شديت حيلي فيه كثير للأمانة بحكم بداية الكورس و الضياع، لكني شديت بالميد و رايتنق ٢ و الحمدلله عدلت درجاتي، بالفاينل شديتها مرة و جبت A+ بكل السكاشن و درجة عالية بالرايتنق كذلك. \n\nالرايتنق: \nساعدني بالكورس دكتوري و كان له دور كبير إني أفهم وش المطلوب مني بكل تيست،\n\nقبل كل رايتنق تيست كان فيه تيست تجريبي، نكتب بالكلاس كأنه الـ real test \nبعدها نرفعه عالبلاكبورد خلال وقت معين قبل الديدلاين. \nكنت أشد حيلي بهذا و أكتب كل اللي وصّانا عليه الدكتور أثناء الكلاسات. \nبعدها يعطي كل شخص فيدباك و ينزله عالبلاك، ثم يسوي كلاس يعرض فيه أخطاءنا و ينبهنا على أخطاء بعض \nو كان يمدح بعض الايسايز و ايش المميز فيها و ايش ممكن يرفعني درجات و أنا كنت أسجل نوتات عليها. \nبعدها قبل الـ real test أكتب ايساي و أعطي الدكتور بالاوفيس الاور، بعدها أراجع أخطائي مرة ثانية و أكتب ايساي ثاني و أوريه كمان، و كذا لين أحس إني مستواي تمام و ماعليه ملاحظات أو أخطاء.\n\nشغلي بكل رايتنق تيست أخليه محفوظ في ملف بحيث إني قبل الإختبار أفتح الملف و أراجع كل أخطائي و كل ملاحظات الدكتور اللي قالها سواء لي شخصيًا أو خلال الكلاس، كذلك كنت أسجل بعض الفوكاب اللي يفيدني بالنوع ذاته من الرايتنق. \n \n  الريدنق: \nالحمدلله كل الاختبارين الميد و الفاينل كانت كويسة بالنسبة لي بحكم إني ذاكرته كويس، كنت أقرأ الريدنق بورتفوليو و أي كلمة جديدة علي أفهمها و أي معلومة معقدة أطلب من chat gpt يشرحها لي بالتفصيل، أحرص ما أخلص القطعة إلا و أنا فاهمة كل حرف فيها. و الـMCQs اللي تحت كل ريدنق مهمة مرة مرة. في مرات كانت فيه إجابتين صح لكن فيه إجابة تكون أصح من الثانية فالموضوع يحتاج تدريب. \n\nالفوكاب: \nقسم بسيط لكن من الأخطاء اللي سهل إن الواحد يقع فيها إنه يعرف الكلمة و معناها و خلاص، و هذا مو كافي لأن في الاختبار تحتاج تعرف كيف و متى تستخدم هذه الكلمة لأنه بيطلب منك تختار الكلمة الأنسب لجملة معينة \nلذلك كنت أطلب من chat gpt يعطيني جملة بسيطة أقدر من خلالها أفهم كيف و متى تستخدم هذه الكلمة.\n\nالقرامر: \nمشيت على السلايدات و في الشرح إستعنت  باليوتيوب، بعدها حليت التدريبات اللي موجودة بالقناة هنا، مهمة مرة لأنها تتكرر و تجي مثلها بالإختبار بنسبة كبيرة. \nفي الميد سويت غلطة غبية و هي إني نسيت إن فيه خيار E (معناته إن الجملة صحيحة و ما فيها أخطاء من ناحية القرامر) و هذا الشيء نزّل درجتي فيه. \n\n\nكم نصيحة أخيرة: \n- تعرفوا على الفورملا حقت الإختبارات و كيف تجي بالضبط أسئلة كل قسم \n- لا تغيبون و تفرطون بالأبقريد \n\n\n\nختامًا، المادة مو تعجيزية لكن تحتاج تسمع و تسأل طلاب أكبر منك و تتفادى أخطاءهم.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/359214","user":"DWTBY","ts":1781361204000,"mid":359214}}', 1781361204000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p360504-engl101', 'tg-poqlle', 'ENGL 101', 'info', '{"desc":"يمدي بس اذا اعترضت يقيمون بدقة عاليه يعني لو كان فيه كم شغله دكتورك متجاهلها ومانقصك عليها بيرجعون ينقصونك \nبس مايعني انه ممكن ماتزيد","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/360504","user":"Poqlle","ts":1783948547000,"mid":360504}}', 1783948547000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p361556-engl101', 'tg-hkhkllll', 'ENGL 101', 'info', '{"desc":"هو انت كذا ولا كذا بتحفظ ستركتشر لكل انواع ال essays يمديك تحفظ الطريقة الي تكتب فيها بس انك تحفظ وش بتقول غالبا طريقة سيئة\n\nENGL 101 253\nInstructor: stephen watts\nGrade: A\nالسلام عليكم معكم هاشم واليوم بتكلم عن تجربتي مع هذا الكورس وللمعلومية انا درست انجلش الاوريا يعني لغتي كانت اقل من عادية في البداية. \n\nطبعا الكورس مهب صعب تجيب فيه قريد زي مايقولون لك الاغلب ولا يحتاج انك تذاكر له كثير السالفة كلها انك تحتاج تكون عارف الكورس مبني على وش ووش يمديك تجيب قريداته بسهوله ووش الي يحتاج تتعب عليه. \n\n\n1-Writing tasks\nاولا بتكلم عن التاسكات الصدق البداية المهمة والحقيقة الي بتعرفك على مستواك تكون بأول تاسك (Compare-contrast) هو أكثر تاسك اشتغلت فيه مع انه اقل تاسك جبت فيه قريد الستركتشر فيه كريه شوي فيه اشياء كثير لازم تسويها غصبا عنك وغالبا أفكارها تكون قليلة عموما كتبت لهذا التاسك ٣ مقالات كنت اروح للدكتور واخليه يقيم ويعطيني ملاحظاته بس نصيحتي لاتعطي ملاحظاته كامله اهتمام حاول تحسن الي يمديك تحسنه بمستواك انت لانه الدكتور بالنهاية يعطيك نصايح تحسن الرايتينق واذا حسنتها بيعطيك غيرها وغيرها ف بختصار مستحيل يوقف ويقولك خلاص انت ختمت دائما بكون فيه ملاحظات ف انصح انكم تستخدمون شات جبت الجامعة ارسله الروبريك ويقيمك تقييم واقعي بناء عليه\n\nبالنسبة للتاسك ٢ (causes and effects) \n كتبت له مرتين والصدق الستركتشر حقه كان جدا سهل ممكن تفهمه وتعرف تطبقه بدون حتى ماتكتب اول رايتينق لك فيه تاسك جميل مو معقد فكرته وتوجهه واضح الاغلب عرف يطبق الستركتشر بس بالنهاية الفكرة حقتك وتطويرها ومنطقيتها هو الي بيخليك \nتختلف عن الباقي وتأخذ قريدات أعلى\n\n2-Final writing\n\nالفاينل فيه احتمالية درجات أعلى بسبب انه الوقت بيكون أكثر بتقريبا ٢٥ دقيقة مع زيادة عدد كلمات قليل مقارنة بالوقت ف يمديك تطور وتفكر بافكار أفضل الصدق اخر رايتينق ماكتبت عنه شي لكن فهمت الستركتشر حقه شرح دكتوري فيه كان واضح وأخذت فيه افضل قريد في رايتينق السالفة كلها بالباراغراف ال 5 الجديد وهو ال counterargument حاول تفهم فكرته مره كويس عشان اذا نقصت بارت منه يضر تقييم كثير. \n\n3-ME-FE\nهذا اهم بارت تذاكر له لأنه أكثر درجات تقدر تأخذها بجهدك اولا الريدينق في الميد بيكون قطعتين وحده منهم بتجي  من مواضيع اول ٤ ريدينق بورتيفيلو ف انصحك تقرأ وتفهم القطعه الأسئلة اغلبها مقالي انا كنت احل الخياري فقط كنت اشوف الخياري مضيعه للوقت بينما غيري يشوفها مفيدة ف انت وطريقتك اما بالفاينل بيكون فيه قطعه وحده بتكون من احد مواضيع ريدينق ٥ إلى ٨ ف بتكون عارف عنها من البداية ف هي فرصة ماتعووض مهم جدا انك تحل الأسئلة وتفهم القطع\n\nبالنسبة للفوكاب مافيه شي مميز اول بارت بيكون تكمل الفراغ البارت الثاني المختلف شوي بتكون قطعه وفيها فراغات تختار الكلمة المناسبة فيه - احفظ المعاني وتدرب على أسئلة البلاكبورد ولو يمديك روح لشات جبت يعطيك قطعه زي الاختبار واختبر نفسك\n\nالستركتشر الصدق ماقدر اعطيكم فيه ذيك النصايح لاني ماذاكرت له لاميد ولا فاينل بس كنت احل بخبرة التوفل لا أكثر ولا أقل وكنت احسه سهل مع انه درجات فيه مب أفضل شي للاغلب ف ممكن تسأل دكتورك عن أفضل طريقه تفيدك في هذا القسم\n\n\nبالنهاية عليكم بالميد والفاينل mcq درجات بيدك لاتضيعها انا ضيعت كثير بالميد لاني ماذاكرت قريت الفوكاب بس بعدها تعلمت من غلطي في الفاينل ف لاتطيحوا بنفس الأخطاء هذي.\n\nماتحتاج تقسيمة مادة ستاندر يعني\n+95 - A+\n+90 - A\nوالى آخره اللهم المادة فيها ابقريد وافرج\n\nشوف هو يعتمد اذا قريدك بالسي وتحت يزيدك وحده إذا بي وفوق يزيدك ثنتين وفي أفرج يزيد بعض الطلاب ف بالاخير الاغلب يزيد قريد في ناس بأخر درجة بالقريد ف تسلك ويزيد قريدين في الي بالبداية ويبقون كما هم وللمعلومية ماحد يعرف النسبة حقته\n\nالتاسكين كلهم 50 د \nوالفاينل ساعة وربع\nاول تاسك أقل شي 250\nثاني تاسك 270\nالفاينل تقريبا 300 طبعا بيزيد باراغراف ووقت أكثر ف بتوصل الكلمات بالراحة.\n\nانا اشوف انك تبدأ ب المضمون والي يخليك تحمي للريدينق - فوكاب وقرامر أكثر شي تذاكر له ف تبدأ بهم عشان لاتنسى المعلومات وتكون توها فرش\n\nوحدة من القطع بتجيك نفس التوبك ثانية اول مره تشوفها مستوى الكلمات بيكون متقارب الأسئلة نفس الأسئلة الي تعرفها من الاوريا وش العبارة الخاطئة وش الصحيحة وش معنى الكلمة بالسياق واسئلة شوي ديب في باراغراف معين لازم تقراه بفهم","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/361556","user":"HKHKllll","ts":1786124074000,"mid":361556,"mids":[361556,361831,362638,366066,367572,378312,378348]}}', 1786124074000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p362258-engl101', 'tg-ahm3ed268', 'ENGL 101', 'info', '{"desc":"بس لو تبدع مد و فاينل mcq تقدر تطلع ب قريد لا باس فيه حتى لو الرايتنقز حقونك زفت\n\nالريدنق هو البورتفيلو \n\nالفوكاب في 6 awl \nاول ثلاثة للمد و آخر ثلاثة للفاينل\nAWL = Academic Word list اظن\n\nأنا عن نفسي\nاقرا السؤال و بعدين اقرا البرقراف الين ما احصل المعلومة و بعدها اختار الاجابة \n\n( إذا تقصد الريدنق الي في البلاك )\nأنا قريت نصين في الكلاس بطلب من الدكتور\nالكلمات الي كنت ما افهمها احاول افهمها من السياق و الاسئلة الي غلطت فيهم صورتهم على اساس برجع اليهم","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/362258","user":"Ahm3ed268","ts":1786832294000,"mid":362258,"mids":[362258,364816,388062]}}', 1786832294000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p362688-engl101', 'tg-u963331699', 'ENGL 101', 'info', '{"desc":"مو صعبه بس تعتمد على تصحيح الدكتور للرايتنق\nإذا شديت في الميد والفاينل يمديك تطلع بقريد","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/362688","user":"","ts":1787081792000,"mid":362688}}', 1787081792000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p362859-engl101', 'tg-u2027083288', 'ENGL 101', 'info', '{"desc":"في reading portfolio يقولوا اللي يسويه يجيب عالي في الreading بس ماعليه درجات ومايصير شي اذا ماسويته","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/362859","user":"","ts":1787131393000,"mid":362859}}', 1787131393000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p363428-engl101', 'tg-csrcsc', 'ENGL 101', 'info', '{"desc":"اذا بنصحك بشيء استفد من الساعات المكتبية والفيدباك اللي يقدمه دكتورك \n\nلان نفسه اللي بيعطيك فيدباك هو اللي بيصحح لك الرايتنق الفعلي","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/363428","user":"csrcsc","ts":1787171556000,"mid":363428}}', 1787171556000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p365898-engl101', 'tg-u2111065114', 'ENGL 101', 'info', '{"desc":"ما تستاهل بشكل يومي المادة\nاهم شي لا تراكم الفوكاب و تدرب للميد بدري شوي و احضر براكتس الرايتنق و تعلم من فيدباك الدكتور","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/365898","user":"","ts":1787764523000,"mid":365898}}', 1787764523000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p367384-engl101', 'tg-lay3o5', 'ENGL 101', 'info', '{"desc":"فيه ثلاث رايتنق اثنين راح يكون بالكلاس و واحد بالفاينل و فيه ميد قرامر و فوكاب ريدنق","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/367384","user":"Lay3o5","ts":1788461449000,"mid":367384}}', 1788461449000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p370179-engl101', 'tg-eren989973', 'ENGL 101', 'info', '{"desc":"السلام عليكم ورحمة الله وبركاته \nللي ضايع انجلش او ما له خلق يبحث بختصر الي فهمته كله\nالميد عبارة عن ٣ اقسام \nقرمر وستركشتر\nفوكاب\nريدنق\n\n١-الفوكاب:\nفيه لستة في البلاكبورد ١-٣ للميد ذاكرهم وبعدها فيه تدريبات واجد في البلاكبورد روابط وكويزات وغيرها طريقته كانه قطعة ريدنق ناقص منه ٨ كلمات وحط الكلمة الي تناسب\nوالجزء الثاني جملة حط فيها الكلمة المناسبة\n\n\n٢- ريدنق: \nعبارة عن ٢٠ سؤال وعليه ٥٠٪؜ الظاهر من الاختبار فاهم قسم بالنسبة ليي\nبتجي قطعة ذاكرتها من قبل بغير في القطعة شوي والاسئلة بغيرها بعد فبتكون عارف غالبا تتكلم عن وشي بس لازم تقرا من جديد لان بغير معلومات ويمكن يعكس شوي\nوالقطعة الثانية جديدة ما شفتها عليها ١٠ اسئلة\n\n\n٣- قرمر و ستركشتر:\nتقريبا ٢٥ سؤال يختبر فهمك للقواعد\nالجزء الاول editing  بكون\nجملة كاملة بحط خط على ٤ خيارات وشوف الغلط اذا ما فيها غلط تختار e الي هو كل شي صح\n\nالجزء الثاني\nقرمر عادي على اغلب القواعد الي درستها اوريا موضحة بالتفصيل في البلاكبورد القواعد الي تتضمنها وفيه تدريبات واجد على ذا القسم\n\n\nوموجود اختبار تجريبي كامل  في البلاكبورد مفيد جدا.","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/370179","user":"EREN989973","ts":1790703577000,"mid":370179}}', 1790703577000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p370234-engl101', 'tg-iamloum', 'ENGL 101', 'info', '{"desc":"اي من عندك تجيبه ، في طريقين تذكر فيها الايجنت\nيا انك تقوله من المقدمه و تمشي على ذا الاساس و بالخاتمه تعطي توصيه يعني ذا الشيء يناسب اكثر للعميل \nاو انك تخلي قطعتك كلها بدون عميل بس بالخاتمه تذكر عميلك و وش الاقضل له","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/370234","user":"iamloum","ts":1790713426000,"mid":370234}}', 1790713426000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p374580-engl101', 'tg-kfu_pm', 'ENGL 101', 'info', '{"desc":"نقاط للتوضيح:\n- الفوكاب منawl-1 الى awl-3\n- القرامر كلها G1-G8\n- الريدنق من text-1 الى text-4 \n- الوقت ٩٠ دقيقة تقسمها زي ما تبي. المهم تخلص كل شي في هذا الوقت\n- انواع الاسئلة وطبيعتها موجود في البلاكبورد ميد براكتس نفسه بالضبط \n- الاختبار ورقي مو بالكمبيوتر","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/374580","user":"KFU_PM","ts":1791551729000,"mid":374580}}', 1791551729000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p375426-engl101', 'tg-u1172956080', 'ENGL 101', 'info', '{"desc":"ذاكر الفوكاب والقرامر تقدر ترسلهم لشات جبت وتقوله يعطيك اسئلة بنفس طريقة الاختبار عشان تتدرب \nحل الفورمز الموجوده بالبلاك بورد والسامبل \nإذا عندك وقت اقرأ الريدنق بورتفليو او أرسلها لشات يلخصهم\n\nلانه وحده من الريدينق بيجي عن نفس الموضوع اللي بالبرتفوليو بس مو شرط نفسها بالضبط \nمثلا أنا اخذته بالصيف جتنا عن lab grown meet \nفي البورتفوليو كان كله يتكلم عن ايجابيات الموضوع اما اللي بالاختبار كان كله سلبيات \nالزبده ماحس فادني اني قاريه الموضوع من قبل 😭","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/375426","user":"","ts":1791651264000,"mid":375426,"mids":[375426,375455]}}', 1791651264000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p375472-engl101', 'tg-kinan_alnasser', 'ENGL 101', 'info', '{"desc":"الاختبار كامل ساعة ونص \nعندك قسم القرامر ٢٥ سؤال \nعندك قسم الفوكاب ٢٥ سؤال \nعندك قطعتين ريدنق ٢٠ سؤال\n\nالفوكاب عندك اللسته مع الدفنشن ضروري تقرا الدفنشن\nالريدنق والقرامر الي موجودين في بلاك بورد \nوعندك حاطين براكتس \nMid-term \n261\n\nأنا الصراحة ما راجعت القرامر من ملفات او شي بس شفت هالفورمز والاختبار ما طلع منهم وبالعكس كان اسهل بعد\n\nاحس ب اختصار الي فهمته \nالمقدمة تبدأ ب Background ثم Significance ثم Thesis وتذكر فيها الAgent والسببين أو الأثرين اللي بتناقشهم بعدها كل Body تبدأ بـ Topic Sentence فيها الـ Agent والنقطة ثم تشرح Why/How وتعطي مثال وكذا وتوضح النتيجة. أهم شي كل فقرة تركز على سبب أو أثر واحد ويكون شرحك منطقي واذا بتحط مثال ركز على انه يخدم فكرتك. وأخر شي الخاتمة تعيد صياغة الفكرة الرئيسية وتلخص النقطتين وتنهي بنتيجة أو recommendation مناسب. ولا تنسى تذكر ال Agent بشكل واضح، ولا تخلط بين ال Causes وال Effects\n\nان شاء  الله فهمت💀\n\nالريدنق غلطة وحده تطير A+ من قسم الريدنق \nالقرامر والفوكاب يمكن كل غلطين بقريد كذا \n\nوف النهاية \nتوتال القريدز لكل قسم هو توتل الميد حقك\n\nالاهم يعني مو اكثر من اربع غيابات \nوتسليم درافت لكل تاسك","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/375472","user":"Kinan_Alnasser","ts":1791651990000,"mid":375472,"mids":[375472,376054,381956,385821,387768,394429]}}', 1791651990000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p375607-engl101', 'tg-humaanc', 'ENGL 101', 'info', '{"desc":"تعلم تكتب رايتنق كويس ب ٥٠ دقيقه حسب الستركشر\nراجع قرامر التوفل وطريقة حله\nوالفوكاب ينحفظ مايبي له بعضه مكرر وبعضه جديد بس مقدور عليه\nوريدنق\nاطلع على عليه\n\nترا الرايتنق مايتطلب فوكاب واو ( حسب كلام دكتوري، يمكن يختلف من دكتور لثاني ) قال أهم شيء قرامر نظيف وشرح واضح وكافي لكل بدي\nوستركشر وتوبك وثيست والخ موجوده.\nاساسًا بالرايتنق زنقه وقت فا لو عندك خيارين تكتب كلمه صعبه ويمكن تغلط فيها، او كلمه سهله بنفس المعنى\nبختار الثاني","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/375607","user":"humaanc","ts":1791653979000,"mid":375607,"mids":[375607,375620]}}', 1791653979000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p375755-engl101', 'tg-lu84ke', 'ENGL 101', 'info', '{"desc":"شفت الملفات الي بالبلاكبورد؟ ارسلها للشات وخليه يشرحها لك بالتفصيل ويدربك على اسئلة ثم رح تدرب على اسئلة البلاكبورد... (تقدر تمر على السريع على قواعد التوفل لو تحس انه اساسك ضعيف غير هيك ما احس يحتاج)\n\nمن البلاكبورد ذاكر ملفات القرامر وReading Portfolio والفوكاب من (ENGL101 AWL In Action Course) وحل اسئلة..\n\nحل اسئلة كورس AWL للفوكاب، اقرأ الريدينق الي بالبلاكبورد، شف ملفات القرامر وحل اسئلة الفورمز","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/375755","user":"LU84KE","ts":1791657956000,"mid":375755,"mids":[375755,377359,391212]}}', 1791657956000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p376899-engl101', 'tg-u1354913638', 'ENGL 101', 'info', '{"desc":"الكورد اليوم قالت لنا إذا مالقيتوا إجابة سؤال ريدنق في النَّص ممكن تلقونها في الجرافز","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/376899","user":"","ts":1791809558000,"mid":376899}}', 1791809558000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p377362-engl101', 'tg-h8mra', 'ENGL 101', 'info', '{"desc":"كويز ولا كويزين تدريب وبعد ما تخلص الريدينق والفوكاب أبدا حل الmidterm exam A \nغالباً بتلقى الانستركتر منزل اختبار ولا اثنين تدريب للميدتيرم","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/377362","user":"h8mra","ts":1791828289000,"mid":377362}}', 1791828289000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p380948-engl101', 'tg-yazo_12', 'ENGL 101', 'info', '{"desc":"اسمع مني\nافهم الستركتشر صح وانت تكتب تذكر وش المطلوب وتجنب اي شي يخليك تاخذ F وباذن الله ما بتنزل عن C","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/380948","user":"Yazo_12","ts":1792195665000,"mid":380948}}', 1792195665000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p388214-engl101', 'tg-pastinfinity', 'ENGL 101', 'info', '{"desc":"عندك أسبوع يمديك ان شاءالله \nذاكر الريدنق حق الريدنق بورتفوليو\n\nو لست الفوكاب ذاكرها و ذاكر السننمز ثم تدرّب\nو آخر شي تدرّب للقرامر","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/388214","user":"PastInfinity","ts":1792722049000,"mid":388214}}', 1792722049000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p390187-engl101', 'tg-u2021193268', 'ENGL 101', 'info', '{"desc":"100 point\nreading = 50 point (2,5 each)\nvocab = 25 point (1 each)\ngrammar = 25 (1 each)","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/390187","user":"","ts":1793380716000,"mid":390187}}', 1793380716000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p390873-engl101', 'tg-u1363600058', 'ENGL 101', 'info', '{"desc":"الي ما أمداه يتدرب على الفوكاب \nترا لو تفتحو الكورس في آخر كل ملف في رابط او رابطين فيه تدريب على الفوكاب الي يجي نص. و اختياري مرهههه مفيد و حسيته كافي تدريب \nو مكتوب تحتهم انه بنفس طريقه الميد","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/390873","user":"","ts":1793388318000,"mid":390873}}', 1793388318000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p397501-engl101', 'tg-cll418', 'ENGL 101', 'info', '{"desc":"الرايتنق لو تحاول تتدرب قبلها بفترة وتفهم الستركتشر زين بتقدر تأدي بشكل افضل يعني بس حاول تتدرب قبلها بفترة مو تجي قبل الرايتنق بيومين تتدرب وتستغرب ليش درجتك افرج او اقل","type":"","rel":0,"lang":"","book":"","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/397501","user":"Cll418","ts":1793891027000,"mid":397501}}', 1793891027000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p38206-engl101', 'tg-noudf', 'ENGL 101', 'srcU', '{"html":"For time\u003cbr\u003e\u003cbr\u003eOn : with days and dates \u003cbr\u003e\u003cbr\u003eAt : for a specific time \u003cbr\u003e\u003cbr\u003eIn : ( months and years )\u003cbr\u003e\u003cbr\u003eFor places \u003cbr\u003eOn for surfaces or a specific location ( on the chair) \u003cbr\u003e\u003cbr\u003eIn : surrounded by our encircled by ( if u r surrounded by the location you are “in”the location) like in my pocket or in my room ( it also works with cities and countries) \u003cbr\u003e\u003cbr\u003eAt / At means general location . If the place that you are talking about is big, like an airport, hotel or even your house (with many rooms and locations) then you should use at","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/38206","user":"NOUDF","ts":1678560186000,"mid":38206}}', 1678560186000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p38334-engl101', 'tg-idcistg', 'ENGL 101', 'srcU', '{"html":"ملاحظة: هذه الطريقة حتفيدكم بشكل عام وليس للمادة بشكل خاص\u003cbr\u003eال reading:\u003cbr\u003eفي موقع جدا حلو اسمه read theory اول ما تدخل بقيس مستواك بكم سؤال بعدين على اساسه ببدأ يعطيك قطع \u003cbr\u003ehttps://readtheory.org/\u003cbr\u003eوانت بتقرأ مش ضروري تفهم كل شي مكتوب اهم شي توصلك الفكرة\u003cbr\u003eبخصوص الكلمات الجديدة برضو خلي ببالك انه بعض الجمل فيها context clue يعني كلمة بسيطة(او عبارة) بتوضحلك معنى الكلمة الجديدة يلي بالنص.\u003cbr\u003e ودايما تعمق بالنص وحاول فكر ايش كانت مشاعر الكاتب هون طيب ليه الكاتب استخدم هالجملة هون بدل جملة ثانية هالشي بفيييدك كثيير بأسئلة الريدنغ\u003cbr\u003eطبعا الموقع هذا حلو بشكل عام وليس بشكل اكاديمي لو ودك تطور بالقراءة الاكاديمية انصحك بكتب التوفل\u003cbr\u003e………………..\u003cbr\u003eال grammar وال vocabulary وال listening:\u003cbr\u003eاكتر موقع بنصح فيه هو:\u003cbr\u003ehttps://learnenglish.britishcouncil.org/\u003cbr\u003eاول ما تدخل برضو اعمل تحديد مستوى\u003cbr\u003e(رابط تحديد المستوى: https://learnenglish.britishcouncil.org/english-levels/online-english-level-test) \u003cbr\u003eوشوف مستواك ايش وعلى اساسه شوف قسم القرامر خاص بمستواك لحد ما تخلصه كله وانتقل ل يلي بعده\u003cbr\u003eنفس الشي للفوكاب واللسننغ\u003cbr\u003eبحب نوه انه اللسننغ يلي فيه مواضيعه متنوعة وقريبة من الاختبارات الدولية بتاع الانقلش\u003cbr\u003e…………..\u003cbr\u003e\u003cbr\u003e* لو انت بتحب المواضيع العلمية شوف tedx\u003cbr\u003e* لو انت بتحب تدرس ادرس من مصادر انجليزية زي خان اكاديمي او هذا الرهيب\u003cbr\u003eTheOrganicChemistryTutor\u003cbr\u003eوفي هذا برضو للماث https://youtube.com/c/Freemathvideos\u003cbr\u003eوهذا برضو للكيم https://youtube.com/c/wbreslyn\u003cbr\u003eوفي هذا https://youtube.com/c/ProfessorDaveExplains\u003cbr\u003eوعادي شوف اي حد بشرح انجليزي مش ضروري هالقنوات بس هدول المفضلين عندي\u003cbr\u003e*لو بتحب مواضيع الصحة النفسية في هي القناة https://youtube.com/c/Psych2go\u003cbr\u003eصوتها يجيب النوم لكن حلوة \u003cbr\u003e*كمعجم الكويس نصيحة شوف هذا https://www.merriam-webster.com/\u003cbr\u003eوبرضو https://www.wordhippo.com/\u003cbr\u003eوأيضا https://www.thesaurus.com/\u003cbr\u003e*لو بتحب تسمع بودكاست شوف هي(بقولك من الان عليها سوالف عبيطة ومرات تسب😭) https://podcasts.apple.com/sa/podcast/anything-goes-with-emma-chamberlain/id1458568923\u003cbr\u003eوهي عن تطوير الذات واتخاذ القرار الوظيفي الصح وهيك امور https://podcasts.apple.com/sa/podcast/you-turn-podcast-w-ashley-stahl/id1382321276\u003cbr\u003eوفي بودكاستس bbc و british council لو حابين\u003cbr\u003e………………..\u003cbr\u003eكورس حلو فتح قبل فترة ومجاني:\u003cbr\u003e\u003cbr\u003ehttps://www.edraak.org/programs/course-v1:BritishCouncil+Eng100+T3-2018/\u003cbr\u003eفي منه اجزاء ٢و٣ بعد ما تخلصوا ١\u003cbr\u003e\u003cbr\u003eانك تضلي تعيدي نفس الكلام مثلا خلينا نقول قاعدين نتكلم عن اثار تيك توك\u003cbr\u003eTikTok causes students to procrastinate and pile up their leading to low grades. Therefore, TikTok lead to low GPA because it makes students delay their work. TikTok must be banned because it can possibly lead to poor academic performance.","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/38334","user":"idcistg","ts":1678563225000,"mid":38334,"mids":[38334,45107]}}', 1678563225000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p69101-engl101', 'tg-u6446463813', 'ENGL 101', 'srcU', '{"html":"غطي الrelative clause بيدك \u003cbr\u003eاقرأي الجملة بدونه \u003cbr\u003eاذا المعنى حسيته ناقص او مو مكتمل فهذا يكون defining \u003cbr\u003e\u003cbr\u003eاذا  حسيت المعنى مكتمل بدون الرلتف كلوس وشفت انه قاعد يعطيك بسextra information فهذا non defining","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/69101","user":"","ts":1697033253000,"mid":69101}}', 1697033253000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p73765-engl101', 'tg-welpll', 'ENGL 101', 'srcU', '{"html":"https://youtu.be/Ljjiw9mC_Cg?si=WEvIpAcizxylK9gC\u003cbr\u003eهالمقطع مفيد ملخص فيه كل التنسز","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/73765","user":"welpll","ts":1697387091000,"mid":73765}}', 1697387091000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p74491-engl101', 'tg-u846435662', 'ENGL 101', 'srcU', '{"html":"هنا اتوقع دكتورنا ذيك السنة شرحها بهالشكل:\u003cbr\u003eقال لنا ان must يعني شي متشدد بزيادة\u003cbr\u003eمثلا \u003cbr\u003eNow, you must sleep because you look so tired!!!\u003cbr\u003eاو مثلا\u003cbr\u003eYou must take your ID in the exam or you will fail \u003cbr\u003e\u003cbr\u003eف شي extremely important \u003cbr\u003e\u003cbr\u003eHave to \u003cbr\u003eاستخدامها ف شي واجب عليك لكن مو اذا ماسويته بتموت \u003cbr\u003eيعني مثلا \u003cbr\u003eYou have to wake up early because the class begins 8 A.M\u003cbr\u003eصج شي لازم تسويه لكن مو اذا ماسويته بتموت","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/74491","user":"","ts":1697404662000,"mid":74491}}', 1697404662000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
