INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p87253-engl101', 'tg-u825588525', 'ENGL 101', 'srcU', '{"html":".الاختبار عبارة عن كتابة ✍️ 4 فقرات :\u003cbr\u003e-انترودكشن(مقدمة):-\u003cbr\u003e١-نبدأ بشيء مرة عام ثم نبدأ نفصل فيه. \u003cbr\u003e٢-نوضح ليش هذا الموضوع مهم. \u003cbr\u003e٣-الثيسيز=نذكر وش الأشياء الي بنكتب عنها يا إما كوزس(الأسباب)ويكون السؤال عنها ب why أو ايفيكتس(التأثيرات أو العواقب). \u003cbr\u003e-بودي برجراف ١:-\u003cbr\u003eتوبيك سنتس \u003cbr\u003eOne major cause \u003cbr\u003eOne major effect \u003cbr\u003eعلى حسب ايش اخترنا \u003cbr\u003eشرح \u003cbr\u003eمثال\u003cbr\u003eIf conditions\u003cbr\u003e-بودي برجراف ٢:-\u003cbr\u003e \u003cbr\u003eتوبيك سنتس \u003cbr\u003eOne major cause \u003cbr\u003eOne major effect \u003cbr\u003eعلى حسب ايش اخترنا \u003cbr\u003eشرح \u003cbr\u003eمثال\u003cbr\u003eIf conditions\u003cbr\u003e\u003cbr\u003e-الخاتمة\u003cbr\u003eIn conclusion, إعادة صياغة\u003cbr\u003eSummary للبودي برجرافس\u003cbr\u003eFuture expectations توقع مستقبلي","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/87253","user":"","ts":1699475512000,"mid":87253}}', 1699475512000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
