INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p157420-engl101', 'tg-ice_ninja', 'ENGL 101', 'srcU', '{"html":"https://www.youtube.com/watch?v=B0aRsKTImvE\u003cbr\u003e\u003cbr\u003eبتفيدكم ان شاء الله عشان ما تخطؤون في الفواصل بالكتابة\u003cbr\u003e\u003cbr\u003e🔻Grammar Summaries🔻\u003cbr\u003e(Majid 2024|https://t.me/KFUPM_ENG101/161648)\u003cbr\u003e(I. 2023|https://t.me/KFUPM_ENG101/96939)\u003cbr\u003e\u003cbr\u003eمصادر آيس❄️ لـEnglish101:\u003cbr\u003ehttps://kfupmedusa-my.sharepoint.com/:f:/g/personal/s202437440_kfupm_edu_sa/EnRb44DFeDROvQOgPPfgYgsBsQn0KP9DmRBqOe_kMX2gPQ?e=o4X4tc\u003cbr\u003e\u003cbr\u003eشروحاتي باليوتيوب:\u003cbr\u003ehttps://youtube.com/playlist?list=PL6-spf144Pxpj7HvteoL2kYjjkkrs4lLr\u0026amp;si=J9f-XnkP8VFnYH0n \u003cbr\u003e\u003cbr\u003eجمعت في الـOneDrive المصادر الي بعتمد عليهم عشان ما اتشتت وبوفرها لكم عشان تتسهل لكم:\u003cbr\u003eسلايدات الرايتنج\u003cbr\u003eسويت ملف Ice Structure لأول رايتنج تاسك وبسوي زيه بعدين للثاني (طريقة كتابتي للـEssay) \u003cbr\u003eكل ما يخص الميد\u003cbr\u003eالـSyllabus ونحو ذلك\u003cbr\u003eبالتوفيق ودعواتكم🫡🙂\u003cbr\u003e\u003cbr\u003eملف Ice WT2 Structure فيها مثل الملخص للسلايدات وكيف تكتب مقالك\u003cbr\u003ehttps://kfupmedusa-my.sharepoint.com/:b:/g/personal/s202437440_kfupm_edu_sa/EWKogKj8FlJKoDx_chU-3pABERd3DOhEzr1v8AGybkuJqg?e=Bwit6o\u003cbr\u003e\u003cbr\u003eبالتوفيق للجميع🤍\u003cbr\u003e\u003cbr\u003eحياكم الله، سيشن بسيط ما راح أطول لأني أبي أنام، 20 دقيقة كذا أشوفها كافية\u003cbr\u003eبشرح الملف\u003cbr\u003eوللعلم مادة الانجليزي اكثر مادة غير متوقعة درجاتها، دوري فقط أسهل لكم المعلومة ومشيت على سلايدات الدكتور والروبرك لكن أخطأت فمن نفسي والشيطان\u003cbr\u003e\u003cbr\u003eخلصت السشن، رابط تسجيل السشن: https://youtu.be/osWnqMFrLSA\u003cbr\u003e\u003cbr\u003eبالنسبة للي يسألني عن القريدات لما تحسبها بالموقع حقي: https://mibnrashid.github.io/English101/\u003cbr\u003e\u003cbr\u003eبعطيكم مثال:\u003cbr\u003eالمينيمم كان 82\u003cbr\u003eالماكس كان 87\u003cbr\u003e\u003cbr\u003eمستحيل تآخذ أقل من B لأن أقل درجة 82 \u003cbr\u003eغالبا بتآخذ ان شاء الله B+ مع الأفرج\u003cbr\u003eوفيه احتمالية بسيطة جدا اذا عندك أبقريد تآخذ A والله أعلم\u003cbr\u003e\u003cbr\u003eهذا فقط مثال ومب شرط يصير، قاعد أنقل لكم بناء على ملاحظاتي على قريدات الطلاب بشكل عام\u003cbr\u003e\u003cbr\u003eتسجيل الهيلب سيشن 👇👀\u003cbr\u003ehttps://www.youtube.com/watch?v=k6j98j5kI7k\u0026amp;list=PL6-spf144Pxpj7HvteoL2kYjjkkrs4lLr","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/157420","user":"Ice_Ninja","ts":1728295600000,"mid":157420,"mids":[157420,162563,183519,185427,185516,248841,300875]}}', 1728295600000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p158938-engl101', 'tg-wexr01', 'ENGL 101', 'srcU', '{"html":"Intro:\u003cbr\u003e\u003cbr\u003e1) Background: In recent years, __.\u003cbr\u003e\u003cbr\u003e2) Show the importance، and it is important for who?\u003cbr\u003e\u003cbr\u003e3) Represent the two _.\u003cbr\u003e4) set a context to make the factors needed and reasonable (تمهيد وسياق داعم للفاكتورز)\u003cbr\u003e\u003cbr\u003e5) To determine whether ___ or  ___ are better suited for , it is important to evaluate factors such as   and .\u003cbr\u003e\u003cbr\u003e\u003cbr\u003eBody 1:\u003cbr\u003e\u003cbr\u003e1)   is one key aspect for  to take into account when deciding between   and  .\u003cbr\u003e2) Talk generally [Cotrast \u0026amp; Explain the consequences]\u003cbr\u003e3) As a result,  are generally more convenient for   due to their __.\u003cbr\u003e\u003cbr\u003eBody 2:\u003cbr\u003e\u003cbr\u003e1) Another fundamental factor to consider when choosing between   and  is __ .\u003cbr\u003e2) On the one hand, .\u003cbr\u003e3) On the other hand, __.\u003cbr\u003e4) Therefore,  are typically better than   due to their __.\u003cbr\u003e\u003cbr\u003eConclusion:\u003cbr\u003e\u003cbr\u003e1) In conclusion, when evaluating the two  __ for  __it is evident thay there are notable differences between  and \u003cbr\u003e3) As a result,  _ are generally more convenient for  _ and__.\u003cbr\u003e2) [Summary of BP1’s points].\u003cbr\u003e3) Therefore, for ,  would be a better option.\u003cbr\u003e\u003cbr\u003eIntro:\u003cbr\u003e1) Background (from general to specific)\u003cbr\u003e2) Set a context with more details, moving into the main topic\u003cbr\u003e3) Provide two effects if your thesis about causes والعكس بالعكس\u003cbr\u003e4) Thesis\u003cbr\u003e\u003cbr\u003eBody:\u003cbr\u003e1) Topic sentence\u003cbr\u003e2) Explain - given that.. , due to..\u003cbr\u003e3) Examples - for instance.. , especially..\u003cbr\u003e4) Elaborating\u003cbr\u003e5) Implication - This means that.. , In other words..\u003cbr\u003e\u003cbr\u003eConclusion:\u003cbr\u003e1) In conclusion, (then rephrase thesis)\u003cbr\u003e2) sum up the bodys (one sentence for each at least)\u003cbr\u003e3) Closing sentence (Future possiblities, or provide a recommedition)","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/158938","user":"wexr01","ts":1728376357000,"mid":158938,"mids":[158938,187261]}}', 1728376357000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
