INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p167787-engl101', 'tg-maeba_k', 'ENGL 101', 'srcU', '{"html":"هنا الجملة قائمة على الامثلة (الامثلة معلومات اساسية)\u003cbr\u003eف ما تحط فاصلة قبل for example\u003cbr\u003e\u003cbr\u003eولاكن اذا كان المعلومة غير اساسية \u003cbr\u003eتحط فاصلة قبل وبعد\u003cbr\u003e\u003cbr\u003eواذا كانت جملة مكتملة والمثال جملة مكتملة تحط نقطة او semicolon","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/167787","user":"Maeba_k","ts":1728968462000,"mid":167787}}', 1728968462000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p168924-engl101', 'tg-she_will_win', 'ENGL 101', 'srcU', '{"html":"اسمعي لما تكون السبجتك شي محدد مافيه منه كثير الاضافه تكون بين فاصلتين لأنه خلاص معروف لكن لما مثلا يكون من السبجكت اكثر من واحد لازم ما تحطين فاصلتين لأنها معلومه مهمه تبين أي واحد تقصدين مثلا \u003cbr\u003eThe man who is playing football is my father \u003cbr\u003eهنا كم فيه رجل بالعالم كثييييييير \u003cbr\u003eFahad , who is playing football , is my father \u003cbr\u003eنفترض أبوك اسمه فهد هل معقوله يكون لك اكثر من أب ؟\u003cbr\u003eأن شاءالله قدرت أساعدك","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/168924","user":"she_will_win","ts":1728994577000,"mid":168924}}', 1728994577000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p184791-engl101', 'tg-gha477', 'ENGL 101', 'srcU', '{"html":"هالمقطع شفته امس و كان الشرح كويس و واضح \u003cbr\u003e\u003cbr\u003ehttps://m.youtube.com/watch?v=GJZzAaexLd4\u0026amp;t=335s\u0026amp;pp=ygUbZnJhZ21lbnRzIGFuZCBydW4gb24g2LTYsdit","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/184791","user":"Gha477","ts":1730294780000,"mid":184791}}', 1730294780000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p193603-engl101', 'tg-wfag530', 'ENGL 101', 'srcU', '{"html":"الرايتنق بيعطيك 3 prompts اختار/ي واحد منهم مثلًا :-\u003cbr\u003e\u003cbr\u003e1- Saudi Arabia should ban Tiktok\u003cbr\u003e2- KFUPM should allow VPN-free for students\u003cbr\u003e3- KFUPM should allow all students in housing at campus\u003cbr\u003eامثلة بس\u003cbr\u003e\u003cbr\u003eالمطلوب منك تكتبـ/ين 5 بارقرافات :\u003cbr\u003e1- Introduction\u003cbr\u003e2- Body Paragraph 1\u003cbr\u003e3- Body Paragraph 2\u003cbr\u003e4- Counter argument\u003cbr\u003e5- Conclusion\u003cbr\u003e\u003cbr\u003e1- Introduction \u003cbr\u003eفي هالبراقراف تقريبًا بيكون الوضع نفس اللي سويناه قبل Giving a background ممكن نجيب Recent situation فيه أكثر من طريقة نقدر نبدأ فيها موجودة في سلايدات cause and effect. بعد ما نخلص ونتكلم بشكل عام رح نذكر أهمية الموضوع وليش لازم نناقشه. آخر شيء الThesis حقتنا لازم يكون فيها \u003cbr\u003e- The topic ( Must be rephrased ) يعني مُعادة صياغته \u003cbr\u003e- The two reasons السببين اللي بتتكلم/ين عنهم في البودي\u003cbr\u003e- The agent ( Already in the prompt )\u003cbr\u003eمثال للthesis:\u003cbr\u003ePsycological support and studying environment are two imperative reasons that in-campus housing should be permitted for all KFUPM students.\u003cbr\u003eلاحظوا صياغتي مختلفة عن الprompt ف مهمة هالخطوة\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e2- Body Paragraph 1\u003cbr\u003eفي هذا البراقراف رح نبدأ نفصل السبب الأول حقنا ونشرح أكثر عنه ، ورح نبدأ بالTopic sentence ضرورية طبعًا وهنا ما يحتاج تسوون rephrase للتوبك ممكن تكتبونها زي ما هي بالانترو حقتكم بس اذا حبيتوا عادي\u003cbr\u003eبعد كذا رح نبدأ الelaboration حقنا وعندنا أكثر من طريقة ونقدر نستخدم كل اللي تعلمناه بالتاسكات الاولى نقدر : Giving definitions (Explanation), Condition, Causes,Implecation,Comparasions هذه وغيرها طبعًا وتشرحون مع اهمية أنه كل مرتبط بالتوبك حقكم وبالthesis تحديدًا لا تطلعون برا الموضوع \u003cbr\u003e\u003cbr\u003e3- Body Paragraph 2 \u003cbr\u003e\u003cbr\u003eSAME AS BP1🔺🔺\u003cbr\u003e\u003cbr\u003e4- Counter argument\u003cbr\u003eفي هذا البارت احنا رح نوضّح وجهة النظر المختلفة عن رأينا ، بمعنى لو كنت مع الموضوع فأنا هنا رح أجيب العكس. \u003cbr\u003eعندنا طريقتين للCounter argument:-\u003cbr\u003e🔸Text-Based \u003cbr\u003e🔸Imaginative\u003cbr\u003e\u003cbr\u003eبالنسبة للاولى هذه رح تختارين واحد من أسبابك الاثنين وتوضحين وجهة النظر المعاكسة \u003cbr\u003eمثلًا احنا كتبنا Psycological support as a purpose \u003cbr\u003eبيقومون المعارضين يقولون طيب ممكن الطالب يتلقى الدعم من أهله والمحيط الخارجي \u003cbr\u003eفهنا انت/ي اخترت/ي احد الاسباب ووضحتي كيف يفكر الشخص المعارض فيها \u003cbr\u003e\u003cbr\u003eالثاني مختلف : رح تجيب/ن سبب خارجي ماهو موجود أبد باللي كتبتيه وهو بيكون رأي المعارضين \u003cbr\u003eمثلًا : Limited budgets for students \u003cbr\u003eهذا سبب خارجي ماله دخل أقصد أنه المكافأة محدودة فالطالب بيفضل المسافة البعيدة على أنه يدفع \u003cbr\u003e\u003cbr\u003eنجي الحين للستركتشر حق هذا البارقراف\u003cbr\u003e▫️ Sentence 1 : The opposite view ( Against and only one sentence )\u003cbr\u003e▫️ Sentence 2 : Rebuttal : بمعنى رح ترجعين علطول لرأيك وتوضحين ليش هو الصحيح وكيف أنه السبب اللي كتبه الشخص المعارض خطأ \u003cbr\u003eبالتالي ممكن تعطين اقتراحات ، حلول كيف نقدر نتخلص من هالسبب كونه يعتبر غير كافي لرفض الفكرة اللي هي موضوعنا\u003cbr\u003eالRebuttal المفترض كحد أدنى 3 جمل \u003cbr\u003e\u003cbr\u003e5- Conclusion \u003cbr\u003eهنا تقريبًا نفس الفكرة رح نسوي اعادة صياغة للمرة الثانية للThesis حقتنا\u003cbr\u003eبعدين رح نكتب Summary للبودي 1 و 2 واختياري للكاونتر بس مو اجباري\u003cbr\u003eاخر شيء تختمين إما ب Strong statement, Recommendation, Or future possibility\u003cbr\u003e\u003cbr\u003eوعليكم السلام والرحمة\u003cbr\u003eبالنسبة للانترو المفترض انه محتوياتها كالتالي:\u003cbr\u003e1- أولًا الفكرة العامة من موضوعك General Background تتكلم بشكل عام عن الموضوع وعندك أكثر من طريقة مختلفة تقدر تستخدمها بهالبارت مثلًا ممكن تجيب ظاهرة حديثة لها علاقة بالموضوع زي مثلًا مثلًا خلينا نقول موضوعنا عن التعليم عن بعد أو التعليم الحضوري فكّر فيها ايش ابرز حادثة صارت لها علاقة بالموضوع؟ كورونا صح فبتربط الموضوع بالحادثة هذه. ممكن تبدأ بdefinition يعني لو كان مثلًا عندك موضوع عن Saudization هذا قد كتبنا عنه ممكن نوضح هالمفهوم اللي يعني السعودة فهمت علي\u003cbr\u003e\u003cbr\u003e2- بارت 2 هو الreason اللي انت تقصده. هذا البارت لازم توضح فيه ليش احنا قاعدين نتكلم عن الموضوع من الاساس، ليش قاعدين نقارن بين حاجتين أو ليش قاعدين نقنع القارئ بهالموضوع، اذكر اهمية الموضوع سواء هالوقت او بالمستقبل زي مثلًا نرجع لموضوع السعودة ممكن تذكر اهمية الاحتياج لتوظيف السعوديين وانه لازم نسلط الضوء على هالقضية من هالكلام يعني لازم تبيّن للقارئ أنه موضوعك له اهمية\u003cbr\u003e\u003cbr\u003e3- البارت الاخير اللي هو اهم بارت بيكون الThesis statement وهذه من اسمها statement يعني جملة وحدة بتحتوي على : الموضوع نفسه، السببين أو المحورين اللي بتتكلم عنهم، وتوجهك عن الموضوع","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/193603","user":"wfag530","ts":1733402989000,"mid":193603,"mids":[193603,268282]}}', 1733402989000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p196377-engl101', 'tg-quvni1', 'ENGL 101', 'srcU', '{"html":"ملخص الجرامر الي بالقروب هذا والاختبارات الي فيه اشوفها مرة كويسة https://t.me/PHC_OM_ENGL101","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/196377","user":"quvni1","ts":1734104209000,"mid":196377}}', 1734104209000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p229463-engl101', 'tg-thewiiise', 'ENGL 101', 'srcU', '{"html":"Could have:\u003cbr\u003e-when something was possible in the past, or you had the ability to do something in the past, but you didn\u0027t do it\u003cbr\u003e-when something wasn\u0027t possible in the past, even if you had wanted to do it\u003cbr\u003e-when making a guess about something that happened in the past (guessing\u003cbr\u003ewhat maybe happened)\u003cbr\u003e\u003cbr\u003eShould have:\u003cbr\u003e-indicate a good idea that did not happen in the past (late advice)\u003cbr\u003e-something you assume has already happened if everything is ok (used with “by now”)\u003cbr\u003e-to talk about something that you expected to happen if everything was fine, but it\u003cbr\u003edid not happened\u003cbr\u003e\u003cbr\u003eWould have:\u003cbr\u003e-you wanted to do something in the past but you were not able to (used with “but”)\u003cbr\u003e-describes an action or activity that did not take place, but would definitely would have happened if the right condition had occurred first","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/229463","user":"Thewiiise","ts":1741094611000,"mid":229463}}', 1741094611000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p243202-engl101', 'tg-y_7iq0', 'ENGL 101', 'srcU', '{"html":"عندنا \u003cbr\u003ewho —\u0026gt; للعاقل\u003cbr\u003ewhich —\u0026gt; لغير العاقل\u003cbr\u003ethat —\u0026gt; للاثنين \u003cbr\u003e\u003cbr\u003eمثلاً\u003cbr\u003e\u003cbr\u003eThe students who were delayed by the accident were given an extra time.\u003cbr\u003e\u003cbr\u003eThe students, who were delayed by the accident, were given an extra time. \u003cbr\u003e\u003cbr\u003eعشان نحدد نحط فاصلة أو لا نشوف لو حذفنا ال clause اللي في النص اللي هي who were delayed…. هل بتتأثر الجملة؟ \u003cbr\u003e\u003cbr\u003eلو قلنا \u003cbr\u003eThe students were given an extra time \u003cbr\u003e\u003cbr\u003eهنا المعنى اختلف صار كل الطلاب بتم إعطائهم هذا يعني إن العبارة كانت defining clause يعني ما نحط لها فواصل \u003cbr\u003e\u003cbr\u003eبس لو قلت مثلا \u003cbr\u003e\u003cbr\u003eKFUPM which is the best university In Saudi Arabia is located in Dhahran.\u003cbr\u003e\u003cbr\u003eKFUPM, which is the best university in Saudi Arabia, is located in Dhahran.\u003cbr\u003e\u003cbr\u003eهنا عشان نشوف هل هذي العبارة هي مجرد extra information أو لا نحذفها و نقرأ الجملة\u003cbr\u003e\u003cbr\u003eKFUPM is located in Dhahran.\u003cbr\u003eنلاحظ إن المعنى ما تأثر و العبارة ما أثرت على الجملة لما انحذفت يعني الكل يعرف KFUPM فالعبارة نسميها \u003cbr\u003eNon-defining clause \u003cbr\u003e\u003cbr\u003eملاحظة بسيطة في ال non-defining \u003cbr\u003eما نستخدم that \u003cbr\u003eيعني لو كان فيه \u003cbr\u003e…….., that……, …… \u003cbr\u003eعلطول يُستبعد الخيار \u003cbr\u003eتُستخدم فقط في ال defining","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/243202","user":"y_7iq0","ts":1747081962000,"mid":243202}}', 1747081962000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p245796-engl101', 'tg-le8h0', 'ENGL 101', 'srcU', '{"html":"مثال البرومبت حقك \u003cbr\u003eKFUPM should enforce students to have PE classes\u003cbr\u003eوانت مع البرومبت والثيسس حقتك وحده منها \u003cbr\u003eTo Facilitate an active lifestyle \u003cbr\u003eفالكاونتر تكتب\u003cbr\u003eSome may argue that students wouldn’t be more physically active. They mention that regardless of the benefits of the PE class, many students are not interested and would spend the time in the PE classes sitting on their phone.\u003cbr\u003eمثال بسيط وبعدها تكمل بس فكرتها اني قاعد اقول عكس كلام الثيسس حقي وطبعاً فكر في سناريو واقعي زي هذا ان الطلاب اغلبهم على الجوال وقت الpe وماراح يتحركون فهذا جالس يناقض الثيسس حقي وهنا يجي دورك تنفي الكاونتر","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/245796","user":"le8h0","ts":1747205533000,"mid":245796}}', 1747205533000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p261096-engl101', 'tg-it6eer', 'ENGL 101', 'srcU', '{"html":"https://chatgpt.com/g/g-684c02e56388819197ae94abfb4059e6-english-101-compare-and-contrast-essay-guide","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/261096","user":"it6eer","ts":1758211415000,"mid":261096}}', 1758211415000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p268859-engl101', 'tg-jsjiw91', 'ENGL 101', 'srcU', '{"html":"🧭 ملخّص كتابة Essay المقارنة (Compare \u0026amp; Contrast) – WT1\u003cbr\u003e\u003cbr\u003e⏮}🌟}\u0026gt;\u0026gt;\u0026gt;._.._._._..{☆}^-~~~~ ؛)\u003cbr\u003e\u003cbr\u003e🟦 المقدمة (Introduction)\u003cbr\u003e\u003cbr\u003eالمقدمة لازم تكون من 3 إلى 4 جمل فقط، وتحتوي على:\u003cbr\u003e\u003cbr\u003e1. جملة خلفية عامة: تعرّف بالموضوع أو المشكلة بشكل عام.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e2. جملة توضح أهمية الموضوع: تشرح لماذا هذا الموضوع مهم للناس أو كيف يؤثر في حياتهم.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e3. جملة مقارنة عامة: توضّح أن الخيارين متشابهين في الهدف لكن بينهم فروقات.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e4. جملة الأطروحة (Thesis Statement): تذكر فيها النقطتين الرئيسيتين اللي راح تقارن بينهم (Focus Points).\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e\u0026gt; مثال: التكلفة – التواصل، أو المرونة – البيئة الاجتماعية.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e  ☆~...~...~...~....~...~...~....~....~....~....☆\u003cbr\u003e\u003cbr\u003e🟨 الفقرة الأولى (Body Paragraph 1)\u003cbr\u003e\u003cbr\u003eتركّز على أول نقطة مقارنة (Focus Point 1) وتشمل:\u003cbr\u003e\u003cbr\u003e1. Topic Sentence: جملة تبدأ بها الفقرة وتوضح الفكرة الأساسية.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e2. شرح ودعم: توضح كيف يختلف الخيار الأول عن الثاني في هذه النقطة.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e3. أمثلة أو مواقف واقعية: مثال بسيط يوضّح الفرق.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e4. جملة ختامية صغيرة: تربط الفكرة بالاختيار أو الغرض من المقارنة.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e🔹 المطلوب: المقارنة الحقيقية بين الخيارين، مو مجرد ذكر المميزات فقط.\u003cbr\u003e\u003cbr\u003e  ☆~...~...~...~....~...~...~....~....~....~....☆\u003cbr\u003e\u003cbr\u003e🟩 الفقرة الثانية (Body Paragraph 2)\u003cbr\u003e\u003cbr\u003eتتحدث عن ثاني نقطة مقارنة (Focus Point 2) وتشمل:\u003cbr\u003e\u003cbr\u003e1. Topic Sentence جديدة: تبدأ بجملة انتقالية مثل ““Secondly …”.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e2. شرح واضح: تشرح جانب القوة أو الضعف في كل خيار.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e3. أمثلة أو تبريرات: توضح التأثير أو السبب وراء الفرق.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e4. جملة ختامية تربط الفكرة بالاختيار.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e🔹 المطلوب: توازن في المقارنة بين الجانبين، ما تميل لأحدهما فقط.\u003cbr\u003e\u003cbr\u003e  ☆~...~...~...~....~...~...~....~....~....~....☆\u003cbr\u003e\u003cbr\u003e🟥 الخاتمة (Conclusion)\u003cbr\u003e\u003cbr\u003eالخاتمة تتكوّن من 3 جمل فقط، وتشمل:\u003cbr\u003e\u003cbr\u003e1. إعادة صياغة للأطروحة (Restated Thesis): تعيد الفكرة الأساسية بكلمات مختلفة.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e2. ملخص سريع لأفكار الفقرتين: تذكّر القارئ بنقطتي المقارنة.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e3. جملة توصية (Recommendation): توضح أي خيار يناسب نوعًا معينًا من الأشخاص، أو متى يكون كل خيار مفيدًا أكثر.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e🔹 المطلوب: تكون الخاتمة بسيطة وواضحة، بدون أفكار جديدة أو أمثلة إضافية.\u003cbr\u003e\u003cbr\u003e\u003cbr\u003e  ☆~...~...~...~....~...~...~....~....~....~....☆\u003cbr\u003e\u003cbr\u003e⚙️ نصائح عامة للـ :)\u003cbr\u003e\u003cbr\u003eاكتب 4 فقرات فقط (مقدمة، فقرتين، خاتمة).\u003cbr\u003e\u003cbr\u003eاستخدم كلمات ربط للمقارنة مثل: whereas, however, in contrast, while, on the other hand.\u003cbr\u003e\u003cbr\u003eلا تستخدم “I / you. ”.\u003cbr\u003e\u003cbr\u003eاستخدم لغة أكاديمية بسيطة وواضحة.\u003cbr\u003e\u003cbr\u003eكل فقرة تتكلم عن فكرة واحدة فقط.\u003cbr\u003e\u003cbr\u003eالجمل قصيرة وواضحة بدون تكرار.","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/268859","user":"Jsjiw91","ts":1759985619000,"mid":268859}}', 1759985619000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p280075-engl101', 'tg-uqkm7', 'ENGL 101', 'srcU', '{"html":"يعني فيه حالتين ل that :\u003cbr\u003e\u003cbr\u003eيا انها تكون موجوده لربط جملتين فقط (نقدر نحط فاصله قبلها)\u003cbr\u003e\u003cbr\u003eاو انها تكون موجوده لإضافة معلومه\u003cbr\u003e(ما نحط فاصله قبلها)\u003cbr\u003e\u003cbr\u003eمثال عشان توضح لك الصوره\u003cbr\u003e\u003cbr\u003eThe coach told the players that they should sleep early, that they should not eat too much, and that they should do some warm-up exercises before the game.\u003cbr\u003e\u003cbr\u003eالجملة صحيحه و توضح لك متى ما تستخدم الفاصله","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/280075","user":"uqkm7","ts":1760380311000,"mid":280075}}', 1760380311000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
