INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p298609-engl101', 'tg-baylasanmd', 'ENGL 101', 'srcU', '{"html":"اكتب اسم القاعدة عاليوتيوب وشوف الشرح\u003cbr\u003eفي هاد الموقع كمان فيه شرح\u003cbr\u003e\u003cbr\u003ehttp://www.roadtogrammar.com/\u003cbr\u003e\u003cbr\u003eوبعدين حل اسئلة وتدرب كتير\u003cbr\u003e\u003cbr\u003eFragments معناها جزء\u003cbr\u003eالجمل بالعادة بتتكون من فعل واسم ولازم تعطينا شي مفيد نفهمه\u003cbr\u003eال Fragments بكون ناقصها شي من هدول \u003cbr\u003eمثلا eat in the garden\u003cbr\u003eناقصها فعل .. الخ\u003cbr\u003e\u003cbr\u003eال run on sentences من اسمها جمل تركض\u003cbr\u003eالجمل كاملة وفيها الاشياء الأساسية بس فيه أكثر من فعل واسم وما ربطوهم بالطريقة الصحيحة \u003cbr\u003eفلتلقى جملة ورا جملة ومو عارف بالضبط كل جملة لوحدها","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/298609","user":"BaylasanMd","ts":1761419435000,"mid":298609,"mids":[298609,337296]}}', 1761419435000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
