INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p93832-engl101', 'tg-khalidsfather', 'ENGL 101', 'srcP', '{"html":"Domestic -  عائلي وأُسَري\u003cbr\u003eImplicate - اتهام بجريمة، تعريض (كلام فيه سب او اتهام غير مباشر) \u003cbr\u003eOccupy - يحتلّ\u003cbr\u003eParallel - موازي\u003cbr\u003eStatus - الحالة (كالحالة الاجتماعية والحالة الوظيفية) \u003cbr\u003eSum - مجموع\u003cbr\u003eAmendment- (إضافة إلى عقد أو ملفّ، مثلًا: إضافة قانون إلى لائحة القوانين) \u003cbr\u003eDiscretion - العدل، الحكم بحكمة وموضوعية. \u003cbr\u003eEntities - طرف أو جهة سواءً كان شخص او مجموعة\u003cbr\u003eExposure - انكشاف \u003cbr\u003eOrientation- تحضير وتجهيز (اوريا)\u003cbr\u003ePrime - ذروة\u003cbr\u003eSymbolic - رمزي\u003cbr\u003e(Symbolic crying is this emoji 😭)\u003cbr\u003eFederal- وطني\u003cbr\u003eOverseas - عابر للمحيطات\u003cbr\u003e\u003cbr\u003e\u003cbr\u003eهذي معاني الكلمات اللي عليها علامة الانفنتي ومتاكد منها","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/93832","user":"KhalidsFather","ts":1701800135000,"mid":93832}}', 1701800135000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
