INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p183552-engl101', 'tg-ice_ninja', 'ENGL 101', 'srcP', '{"html":"مواضيع الرايتنج اليوم الي جات (اذا عندك زيادة رد على هالرسالة اضيفه)\u003cbr\u003eرايتنج تاسك 2\u003cbr\u003e\u003cbr\u003etraffic accidents in saudi arabia\u003cbr\u003estudying abroad\u003cbr\u003e\u003cbr\u003e-Causes or effects of working while attending university \u003cbr\u003e-Causes or effects of aggression or anger in children\u003cbr\u003e\u003cbr\u003ePoor mental health among students \u003cbr\u003eBullying between children\u003cbr\u003e\u003cbr\u003eDescribe the causes or effects of traffic congestion in large cities.\u003cbr\u003eDescribe the causes or effects of poor diet and nutrition in university students\u003cbr\u003e\u003cbr\u003eThe causes or effects of decreasing family size (fewer children)\u003cbr\u003eThe causes or effects of gender bias in STEM jobs (men/women should/should not...)\u003cbr\u003e\u003cbr\u003efamilies having fewer children\u003cbr\u003egrowing popularity of netflix\u003cbr\u003e\u003cbr\u003eAI in industry\u003cbr\u003ebullying among high school students\u003cbr\u003e\u003cbr\u003ehttps://t.me/KFUPM_ENG101/183604?thread=183552\u003cbr\u003ehttps://t.me/KFUPM_ENG101/183626?thread=183552\u003cbr\u003ehttps://t.me/KFUPM_ENG101/183627?thread=183552\u003cbr\u003ehttps://t.me/KFUPM_ENG101/183705?thread=183552\u003cbr\u003ehttps://t.me/KFUPM_ENG101/183740?thread=183552\u003cbr\u003e\u003cbr\u003eReading Portfolio prompts for Final Writing\u003cbr\u003e(ديبارتمنت الانجلش كاتبين أنه وحدة من ال3 برومتس للرايتنج بتكون مرتبطة بالريدينج بورتفوليو (مرتبطة يعني موضوع قريب مو نفس الموضوع)\u003cbr\u003eAre you in favor or against :\u003cbr\u003e\u003cbr\u003eShould solar power replace fossil fuels as the primary source of energy.\u003cbr\u003e\u003cbr\u003eNuclear energy should be the main power source in KSA\u003cbr\u003e\u003cbr\u003eShould industries adopt AI and robotic technologies ?\u003cbr\u003e\u003