INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-p302031-engl101', 'tg-e299e', 'ENGL 101', 'srcP', '{"html":"For many children, school is the first environment where they learn to build social relationships and interact with different personalities. Unfortunately, one of the most common issues in schools is bullying. Some children harm others through violence or hateful language. Two major effects of bullying among children are lack of confidence and the development of aggressive behaviors.\u003cbr\u003e\u003cbr\u003eOne major effect of bullying among children is a lack of confidence. Bullying can deeply affect a child\u0027s life because children are more emotionally vulnerable than adults. For example, saying harmful words about a child\u0027s body can make them feel ashamed, which may lead them to become shy and introverted. Also, bullying through physical violence can affect their confidence due to the inability to protect themselves. As a result, they may feel weak compared to other children. This feeling of weakness will also decrease their confidence. Overall, both physical and verbal bullying can lead to a serious loss of confidence in children.\u003cbr\u003e\u003cbr\u003eAnother fundamental outcome of bullying among children is the development of aggressive behaviors. Experiencing repeated violence may lead a child to act out aggressively toward others. This aggressive behavior may appear both at home with family and in public with strangers. They may struggle to behave as calmly and respectfully as their peers. They will have behaviors similar to those they experienced, either swearing at people or physically attacking others. To express their anger or pain, some children may begin to bully others in the future, to take revenge for the bullying they experienced. They lived as victims, so they may seek to feel a sense of power or control.\u003cbr\u003e\u003cbr\u003e Bullying among children can lead to two serious consequences: low self-confidence and aggressive behavior. Children who are bullied often withdraw from others and may struggle to feel good about themselves. Others may begin to act aggressively toward family members or strangers. To reduce these effects, teachers and caregivers should carefully monitor children’s interactions and create a safe, respectful environment for everyone.","files":{},"imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/302031","user":"e299e","ts":1763015952000,"mid":302031}}', 1763015952000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
