INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-tbinz-engl101', 'tg-tbinz', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-gazdar","n":"Mahir Gazdar","en":"","img":"","e":"","bld":"","room":"","d":"الشرح : ما تفهم شي \nالتصحيح : أشوفه كويس \nالتحضير : متساهل جدا في التحضير ما يأخذ التحضير إلا بعد بداية الحصة بعشرين دقيقة أو نص ساعة وفيه طلاب يجون قبل نهاية الحصة بعشر دقايق ويحضرهم \nالواجبات : مافيه اي واجبات ولا يلزمك بأي شيء \nالخلاصة : إذا أنت بتذاكر بنفسك وتبي ترتاح من ناحية التحضير والواجبات نزل عنده ، أما إذا تبي شرح شوف غيره .","hours":[],"teach":0,"grade":0,"pid":"tg-p5097-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/5097","user":"TbinZ","ts":1668325630000,"mid":5097}}]}', 1668325630000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-idcistg-engl101', 'tg-idcistg', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-taiseer","n":"Taiseer","en":"","img":"","e":"","bld":"","room":"","d":"شفت فيدباك تيسير؟ صراحة حلو بالعكس بطللل\nتخيلي بتحكي لهم ايش يسووا بالزبط\nاحنا بتقول good-revise ومن هالكلام يلي ما بتعرفي كيف تعدلي بعده\nاول كم essay عطت فيدباك رهيبين بعدين صارت ردود زي الروبوت ما عمري فهمت كيف اعدل 😭😭\n\nانقلش ١٠١-٢٢٢\nاسم الدكتوره: تيسير \n اسلوب:\nجدًا لطيفه ومحترمه وعسل بالاسلوب بس بالتحطيم فنانه \n \n\nفيدباك:\nتعطي فيدباك بالاوفس اور وتعطيك على الرايتنق اللي كتبتيه بالبيت ، الرايتنق اللي تسوونه قبل اختبار الرايتنق تخليكم اسبوع تصصحونه مع صديقاتكم بعدين معها اخر شي .\n\nدرجات:\nتخسف بالدرجات وفعليًا ماتعطي ال A , A+ بسهوله ابدًا لازم تنشبون لها بالاوفس اور وتكتبون كلمات جديد وصعبه عشان تعطي قريد عالي . \n\nتحضير:\nالتحضير مو من البورتال هي عندها زيي الاكسل فيها اسامينا وكل يوم تحضر منه بس ماتبين لنا يعني ماتعرف الا بعدين اذا دخلت البلاك بورد وفتحت الاكسل يوضح لك ، التأخير ماقد حسبت . \n\nبورتفليو:\nتتعب بشكل فضييييع يعني ما انسى اول بورتفوليو نقصتني عطتني A واقولها ليه تقول ال A+ للناس البيرفكت 😃","hours":[],"teach":0,"grade":0,"pid":"tg-p11948-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/11948","user":"idcistg","ts":1671910845000,"mid":11948}},{"id":"tg-dr-pamela","n":"Pamela","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢١\nاسم الدكتور:باميلا\n اسلوب:\nهي moody جد … ايام تيجي رايقة وحلوة وايام منكدة بسبب المواصلات ومنفسة وتصير تهاوش😭 مرات تحفزك وتشجعك وتحسسك انك شكسبير ومرات تقولك ياها بشكل صريح \"كثير زيك وجابوا F\" ما عمري فهمت مودها او جوها بس بشكل عام مودها السيء ما كان كثير يأثر علي..اتنرفز شوي بعدين اسحب \nعموما الريسورس بتاعها حلوين وشرحها مش سيء اعتبره حلو ولو جد سألتيها بتفهمي منها\n \n\nفيدباك:\nتعطي فيدباك على كامل ال essay عدا آخر واحد صارت تعطي على كل جزء من essay وصراحة كانت حركة سيئة ما لحقت آخذ منها اي فيدباك على آخر واحد\nبرضو الفيدباك بتاعها اول الترم كان حلو وكانت تنصحك ايش تسوي\nعلى آخر كم فيدباك شكلها ما عاد لحقت فصارت بس تكتب good ولا bad ولا مقبول الخ يعني بس ملاحظات عامة. عموما لو جيتوها بالاوفيس اور تسألوها كيف اطور البراجراف بتاعي ما بتقول لا👍🏻\nلو كنت طالبة حريصة مستحيل ما ترحب فيك بالاوفس اور وكثير مرات كنت ارسل لها خارج اوقات الاوفس اور عالتيمز وستل ترد علي\nكثر ما تهتمي بمادتها كثر ما تعطيك هي بدورها اهتمام بالاوفس اور\n\nدرجات:\nبالتست الاول والثاني كانت تعطي بشكل حلو يعني يلي تستاهله تاخده 👍🏻\nالثالث حسيتها خسفتنا شوي يعني نزلة قوية\nبالنهاية جبت معها A كتوتال قريد\n\nتحضير:\nاول الترم ما كانت تهتم كثير ل يلي يتأخر يا حاضر يا غايب بعدين لما شافت البنات زودوها بالتأخير صارت تاخذ التأخير\nولو انت مو من عادتك تتأخري وحصل يوم تأخرت شوي يمكن تمشيها لك وياحبذا لو كلمتيها من قبل انو ترا بتأخر\n\nبورتفليو:\nعطتني عقد حقي وكنت امشي عتعليماتها بالزبط وبالحذافير\nكل ما شكيت بشي سألتها ايش اسوي وايش اعمل\nيهمها انك فعلا توري تطور بالرايتنغ بورتفوليو سواء فوكاب ولا سبيلنغ ولا ستركشر ولا قرامر تراها تقرأ ولو شوي \nاما بالنسبة للريدنغ بتحب انك تحطي نوتات كتيرة وتكتبي وتعبري عن رأيك يعني عادي لو شي ما عجبني كنت اكتب نوت بالصفحة ما عجبني واحط ساد فيس😭كنت عامله كأنه رواية حرفيا والأسئلة احاول اهبد اي شي من فهمي بالنهاية هي عارفة اني حاولت ويكفيها انك توريها انك بذلتي جهد وانت بتحلي\nاخذت فيهم الاثنين A+","hours":[],"teach":0,"grade":0,"pid":"tg-p16487-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/16487","user":"idcistg","ts":1672919599000,"mid":16487}},{"id":"tg-dr-hampson","n":"Timothy Hampson","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢٢\nاسم الدكتور: Timothy Hampson \n\nاسلوب: الدكتور صراحة ممتاز ولكن يعيبه انه لكنته بريطانية بزيادة فبالبداية بتحسه دلوع 😂\nI know that it is looks so weird\nولكن بتتماشى مع الوضع حبة حبة وللمعلومية هو اول ترم يدرس اللي هو ترم 222 وكمان درس 102 وفي ناس درسوا عنده ودرجاتهم ما شاء الله جميلة \nالدكتور طبعا ما بيدرس 101 لا صيف ولا بالترم الاول لسنة 23 انا سألته وقال لي عن هالشيء\nالدكتور بدأ يتعلم عربي ويحب الفلافل هههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههههه ههههههههههههههه ازعجنا من يوم ما تعلم الكلمة وكل ما يعطينا مثال يقول فلافل ونهاية الترم فجأة شطح بكلمة \"ممتاز\" وأبهرنا وصدمنا مرة 😂\nالدكتور يقول نادوني تيم تحسه خويك ويقول اسألوني أي شيء بالايميل \nويقعد يقول تعالو الأوفيس لكن اتوقع محد عبره \nانا رحت له قبل اول رايتينج ثلاث مرات يمكن بعدين ما رحت له من جديد بس يحب مرة انك تجيه الاوفيس واشوفه يقرأ كتب كثير لو تبي تتكلم معه عن الكتب بيتكلم ويطقطق معك \nالشرح عادي مافي اي شيء مميز يعطيك اللي بالسلايدات ويمشي عليها وممكن يعطيك كم شيء هو يفضله بالرايتينج وانا الصراحة على طول اعتمدها بال essays تبعي\nمثال: قال لنا مرة انه يحب To conclude بالخاتمة وانا من يومها اعتمدتها بس ما اتوقع انه بينقص اذا استخدمت شيء ثاني هو بس يقول انه هذا الشيء يعجبه \n\nفيدباك: نزل عنده وبتاخذ درجات عالية بإذن الله بس اهم شيء حاول تبهره وتمشي عالروبرك والسلايدات \nانا انسان انجليزيتي جدا عادية ولكن حسيت انه بالاختبارات امشي على نفس التعليمات اللي يعطوها بالكلاسات والحمد لله درجاتي كانت كويسة، طبعا فيه ناس اخذت درجات سيئة وبعضهم اخذوا F وهو قالها لكن عموما انت اشتغل على نفسك والدكتور قريداته مقارنة بالثانيين مررة كويسة \nانا كنت اسوي skeleton or template قبل كل رايتيج واشوف الكلمات واللغة اللي ممكن استخدمها في نوع الايساي\nسلبيات الدكتور: اول شيء اذا بتسأله عن فقرة وهذا الشيء كان يصير معي ما ادري كيفه مع باقي الطلاب بيقول لك \"ahhh, it\u0027s ok or it\u0027s nice\" احسه كان يسلك ولكن اذا بتسأله عن قرامر بيصحح لك او كلمات وهكذا \nثاني شيء الدرجات حقتنا كانت مررررة تتأخر خصوصا اخر رايتينج واخر ريدينج ورايتينج بورتفوليو \nهو تعب واتوقع التعب اثر عليه انه يتأخر بس انه مرة مرة تأخر في تنزيل الدرجات \nدرجات: \nWT1: A+ A A A = A\nWT2: A A A A = A \nWT3: A B+ B+ A = B+ \nResponse the question\nVocabulary\nGrammar\nLanguage use\nRPs: All of them A+ except the first one, I got a B+\nWPs: All of them A+\n\n\nتحضير: يحضر من أول ثانية ودقيق مرة واحيانا تفلت معه كم كلاس ويحضر بعد خمس دقايق تقريبا ولكن نادرا ما تصير \nواللي يجون من مباني بعيدة حطهم ليت وقال انه بيشيلها نهاية الترم من عندهم \n\nبورتفليو: نصيحتي اللي بينزل عنده يسوي بالبورتفوليو \"Colour Coding\" واللي هو انك تبين لك مثلا كل لون بالهايلات يعني شيء معين \nمثلا انا كنت حاط \nالاحمر: شيء انا ودي اعرف عنه زيادة \nالاصفر: شيء مهم\nالاخضر: شيء أثار إعجابي \"interesting\"\nالسماوي: الكلمات اللي ما اعرف معناها \nطبعا كل واحد وطريقته لكن هذي كانت تبعي \nاول واحد ما سويتها ولقمت B+\nالباقيين كلهم خذيت فيهم A+ \nوكمان الرايتينج بورتفوليو خذيت فيهم A+ ولله الحمد \nطبعا الرايتينج كان اول درافت احاول اخليه مرة سيء واعدل تدريجي بالثاني والثالث والرابع واكتب له مليون تعليق واشطب مليون تشطيب عشان ابين له مدى التطور حقي ووريته بالكلاس مرة قبل كمية تعليقاتي وقال واضح انه متعوب عليه واحسه جدا فرح انه شاف هالتعب. \nباختصار الدكتور ممتاز انت بس اشتغل على نفسك معه وحاول تعدل اخطائك وبالنسبة للشرح فالكورس ما يحتاج شرح \nحصة الانجلش كنت اعتبرها بريك \nواسأله عن أي شيء وأمورك بتمشي معه بإذن الله وبتطلع بأحسن قريدات والله يوفقكم","hours":[],"teach":0,"grade":0,"pid":"tg-p53164-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53164","user":"idcistg","ts":1686129124000,"mid":53164}}]}', 1671910845000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-blank_01-engl101', 'tg-blank_01', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adil","n":"Adil Mahmood","en":"","img":"","e":"","bld":"","room":"","d":"وعليكم السلام، انا كنت عنده واشوفه عادي يعني مب سيئ، بس كثير من الي في شعبتي قالو ما راح ينزلو عنده ١٠٢، بس يمكن قالو كذا عشان زعلانين من درجتهم 🤣. الزبده هو مب افضل واحد لكن يسوي الي عليه ومرن جدا بالتحضير والoffice hours","hours":[],"teach":0,"grade":0,"pid":"tg-p15397-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/15397","user":"Blank_01","ts":1672745385000,"mid":15397}}]}', 1672745385000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-rrriim-engl101', 'tg-rrriim', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-taiseer","n":"Taiseer","en":"","img":"","e":"","bld":"","room":"","d":"مس تيسير انقلش ١٠١ /٢٢١\nالاسلوب:\nاسلوبها مرا حلو ومحترمه \nوبالاوفيس اور ترحب بالطالب وعادي تطولين عندها وتجاوبك كويس وتشرح \nالدرجات:\n في بنات بالتاسك الاول اخذو درجات عاليه \nماعرف عن باقي التاسكات \nبس كثير يقولون انهم انخسفوا منها ويقولون باقي الدكتورات افضل بالدرجات \nبالنسبه لي بعد ما شفت درجتي بالفاينل(الفاينل يصححه دكتور ثاني) كانت تقريبا نفس درجاتي معها ف اتوقع انه تعطي على مستوى الشخص\n\nشوفي هي دقيقه وتمشي بالضبطط على الروبريك يعني غلطه بسيطه بالستركتشتر تخسسسف مرررراا\n\nبس بالنهايه اذا لغتك كويسه و مشيتي بالضبط زي ما تبي ممكن ان شاء الله تجيبين قريد عالي\n\nالبورتفليو:\nخسسسسفت كثييير بنات مع انه واجب مفروض تعطي الاغلب A+\nبس بعد في بنات اخذو A \nواذا بتنزلين عندها نصيحه روحي الاوفيس اورز اساليها لان شكلها اعطت A بالبورتلفيو للبنات الي يجونها ومجتهدين طول الترم \n\nالفيدباك:\nبالفتره الي تكون تشرح الايساي احيانا تخلينا نكتب برقراف وتعطينا عليه فيدباك بعدها نكتب كونكلوجن وتعطينا فيد باك يعني الفيدباك حقها الي قبل الاختبار ما يكون على ايساي كامل يكون متقطع \nالفيدباك على الايساي كامل تعطينا هو بعد الاختبار….\nبالنسبه لي اشوفها نقطه سلبيه يعني حسافه اشوف الفيدباك بعد الاختبار \nف ممكن تقولون لها من بداية الترم ان الفيدباك الكامل نبيه قبل الاختبار وان شاء الله ترضا\n\nهل اذا رحت لها الاوفيس اور تعطيني فيدباك؟لا من بداية السنه قالت لنا لحد يجي يقول لي عطيني فيدباك بالاوفيس اور ما اعطي\nلللكن ممكن تروحين لها تسالينها عن شي معين مثلا الثيسس حقتي صح؟ او مثلا كيف elaboration حقي؟ ف هي بتضطر تقرا البرقراف كامل وتعطيك كومنتات على كم شي وتستفيدين\nوجهة نظر شخصيه","hours":[],"teach":0,"grade":0,"pid":"tg-p15852-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/15852","user":"RRRIIm","ts":1672846159000,"mid":15852}},{"id":"tg-dr-megan","n":"Megan","en":"","img":"","e":"","bld":"","room":"","d":"مس ميقن انقلش١٠١ -٢٢١\nاسلوب:\nمحترمه مره و لطيفه تحببك بالكلاس و تحاول قد ما تقدر توضح لك الفكره \n\nفيد باك:\nبالبراكتس تست تفتح بالبلاك بورد فيد باك صح تعطيه بعد ما يخلص التست يعني شوي ماله فايده للتست بس مره تريحك للرايتنق برتفوليو ف يصير اوريدي عندك اكثر من ثلاثه فيد باك منها \n\nدرجات:\nما تعطي اكثر ابدا تاخذين على قد مستواك تمشي على الريبوك بالضبط \n\nتحضير:\nحريصه و تاخذ الحضور بالدقيقه احرصو تشوفون كم حاطه لكم لان عادي تحطك غياب على التأخير بدون ما تقول لك \n\nبورتفليو:\nاللي كانو يسألونها اول بأول و ان ايش ابي بالضبط عطتهم زين اما اللي ما سألوها مره نزلتهم\nوجهة نظر شخصيه","hours":[],"teach":0,"grade":0,"pid":"tg-p15881-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/15881","user":"RRRIIm","ts":1672847276000,"mid":15881}},{"id":"tg-dr-pamela","n":"Pamela","en":"","img":"","e":"","bld":"","room":"","d":"مس باميلا انقلش ١٠١-٢٢١\n اسلوب:\n تفصل احيانا بس اذا كنتي محترمه معها تبادلك نفس الاحترام انا كنت الساعه ٨ يعني اول كلاس ف كانت الاخلاق يا دوبك بس ما قد هاوشت شخص واحد يعني كذا تتحلطم بشكل عام و احس انها كانت كويسه يعني ما قد جادلتها ف ما قد سوت لي شي \n\nفيدباك:\nاشوفها مو كويسه فيه يعني مرتين بس عطتني فيدباك و اغلبه كان good point و ان غيري هذي النقطه مو من قلب يعني بس كم كومنت\n\nدرجات:\nباول تست كانت حلوه القريدات بعدين بدت تنزل بعد كل تست \n\nتحضير:\nالين نص الترم و هي ما تاخذ غياب بعد نص الترم صارت تاخذ التاخير بعد ١٠ دقايق\n\nبورتفليو:\nمشيت على الي تبيه بالضبط و عطتني الي استحقه\nوجهة نظر شخصيه","hours":[],"teach":0,"grade":0,"pid":"tg-p15888-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/15888","user":"RRRIIm","ts":1672847318000,"mid":15888}},{"id":"tg-dr-owen","n":"Jonathan Owen","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٣١\nاسم الدكتور:JONATHAN OWEN \n اسلوب: اسلوبه لطيف و دايم مبتسم\nفيدباك: آخر فيد باك بس اللي استفدت منه اللي قبل يعطيني سطرين خرابيط\nو إذا سألته كيف ممكن تحط باك قراوند بالرايتنق عادي يسولف لك ساعة كاملة عن التاريخ و يخرج من الموضوع و ما تستفيد شي (لأن البكالوريوس حقه تاريخ)\n\nدرجات:الرايتنق تاسك حق الفاينل حقي اعلى بقريدين من اللي يعطيني إياه \n\nتحضير: متعاون حتى لو جيت متأخر شوي يحطك برزنت\n\nبورتفليو: الريدنق بورتفوليو كنت ارويه شغلي و كان يقول أعطيك A+ بالراحة بس بالنهاية عطاني B\n\nبشكل عام مو سيء لكن لو حصل لك تنزل عند غيره يكون افضل","hours":[],"teach":0,"grade":0,"pid":"tg-p114416-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/114416","user":"RRRIIm","ts":1704322713000,"mid":114416}}]}', 1672846159000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-atheerhani-engl101', 'tg-atheerhani', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-pamela","n":"Pamela","en":"","img":"","e":"","bld":"","room":"","d":"وحدة الريدي كتبت بس قلت اكتب عشان تشوفين وجهات نظر مختلفة \n\nمس باميلا انقلش ١٠١ /٢٢١\nالاسلوب:\nاكيد سمعتي واجد يذمون اسلوبها بس ترا لما تكون not in the mood تهزىء شوي في البدايه بعدين تكمل طبيعي و فجأة ترجع تهزىء و ترجع تشرح فما اشوف انه هالشي يأثر حيل في اختيار الدكتور. بعد لو انتي زينه معاها هي تصير زينه معاك، يعني انا في كل مره اكلمها ترد بأسلوب لطيف و لو سألتها سؤال تجاوبني عدل حيل و تعطيني اجابه كامله و نصايح. بإختصار صيري زينه و تعاملك زين\n  \nالدرجات:\nبالنسبه لي حسيتها تعطي الواحد جد على مستواه، يعني مستحيل تنقص بدون سبب و حتى احيانًا تزيد،اللي يقولون انها بعد التاسك الاول نزلت درجة كم بنت هو الروبرك نفسهم يشددون عليه و يزيد التدقيق بحكم انه احنا في تطور فلازم نوصل لمستوى اعلى في كل واحد جاي. في الكلاسز تقط كم كلمة انه سووا كذا و لا تسوون كذا و اذا منجد مشيتي على اللي تقوله بتلاحظين انها جد تعطي درجة زينه.   \n\n\nالبورتفليوز:\nفيه كم بنت خسفتهم و صراحة i can see why  بس كأنها زادت شوي في الخسف، عن نفسي مشيت على الguidlines اللي حطتهم لنا بالضبط و ركزت على اهم النقاط اللي تقيّم عليهم و خذيت في ثنيناهم A+  \n\nالفيدباك:\nصراحه ما كنت اهتم لموضوع الفيدباكس ( شي غلط ) فما جربت منها الا مرتين كان لازم اخذهم عشان احطهم في البورتفوليو. المره الاولى كان حق اول ايساي كتبناه و احس الفيدباك اللي عطتني اياه ما كان حيل متعمق يعني كانت اشياء بسيطه. The second feedback i got from her was really good, she even told me what to exactly write instead of the mistakes she corrected, كان زين لأني كنت احتاجه للبورتفوليو و صار الوقت حده حده فساعدتني. \n\nالoffice hours: \n ما مره جربت اروح عندها بس من كلام البنات، تستجيب لسؤالك و تساعدك زين بس ما اظن لو رحتي و قلتي لها عطيني فيدباك بتعطيك ( مو متأكده فتأكدي احسن ).\n\nبناء على الكلام اللي سمعته لباقي الدكاتره، اشوف باميلا هي الافضل بينهم ( وجهة نظر و ممكن تختلف على حسب كل وحده ) بس اشوف للي محتارين بينها و بين ميقن يروحون لباميلا لان ميقن توها جديده بينما باميلا عنده خبرة سنوات.","hours":[],"teach":0,"grade":0,"pid":"tg-p16340-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/16340","user":"AtheerHani","ts":1672871015000,"mid":16340}}]}', 1672871015000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-n2n2n2n2-engl101', 'tg-n2n2n2n2', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adamkhan","n":"Adam Khan","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢١\nاسم الدكتور: ادم خان\n اسلوب: جميل جدا ومتعاون واخلاقه حلوه \n \n\nفيدباك: ماجربت الا مره ، وكان جدي وفعلاً يبيك تستفيد\n\nدرجات: الa+ شبه مستحيل ، ولكنه بشكل عام بيعطيك قريدات ترضيك وفوق حقك ولا حقك بالضبط\n\nتحضير: ١٠ دقايق ثم يحضر في الغالب ، ومتساهل مره مره\n\nبورتفليو: على قد ماتشتغل على قد ماتحصل\n\nسلبيات: الكلاس كانه احلام العصر ادارته للكلاس سيئه جداً ، متساهل مره مع الطلاب ولا يسكتهم ، وشرحه مب ذاك الزود وسوالفه واجد\n\nاجابيات: مايكرفك نهائي ، الكورس معه كانك مب منزله من الاساس","hours":[],"teach":0,"grade":0,"pid":"tg-p16454-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/16454","user":"N2N2N2N2","ts":1672916847000,"mid":16454}}]}', 1672916847000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-the_wolf1r-engl101', 'tg-the_wolf1r', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adamkhan","n":"Adam Khan","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢١\nاسم الدكتور: ادم خان \n اسلوب:ممتاز  وحبيب صراحة ف الكلاس موب من النوع الي عصبي ويهاوش مره سهالات معه الوضع  لكن يقلب جدّي وقت الشرح.\n \n\nفيدباك: جلاد 😂 عطاني ثلاث مرات فييد باك كلها سلخني .. الصراحة انا اغلاطي غبية بس الصدق انه يقيّمك بالحذافير يعني مايتهاون بأي شيء فحاول تجيب له شيء يرضيه.\n\nدرجات: هممم .. الاغلب C-C+ وفيه F يجيك طالبين كل مره كنا نسأله يقولنا كذا .الB-B+ حوالي ٥ الى ٦ طلاب .الA كان يعطي طالب واحد بس ودايم مثبت على هالطالب ..والA+كان يقولنا بنفسه ان محد بياخذها ف مهب مره سيء ولاهوب مره كويس عادي مره وممكن تلقى خيارات واجد افضل منه من ناحية القريدات .\nطبعاً نسبة تقديرية لاننا كنا نسأله وكان يعلمنا .\n\n\nتحضير: متهاااااون ويحضر بعد ١٠ دقايق ومرات ينسى .. لكن لو جيت بعد ١٠ دقايق يعطيك ليت .بعد ٢٠ دقيقة تاخذ غياب.\n\nبورتفليو: عطاني شيء معقول يعني توقعته . حاول تجيه تورّيه شغلك وبيضبطك اذا عجبه . حاول بس توريه انك مهتم لان ٩٠٪؜ من الطلاب يبدون فيه متاخر ف لو تجيه من بدري وتوريه شغل محترم بيرفعك وهذا الي صار معي.\n\nاضافات : \nمثل ماذكر اخوي N2 بضبط فوق الدكتور يشطح عن الكلاس مرات وللامانه ماعنده هيبه قوية تخلي الطلاب يسكتون مره وقت الكلاس يعني صراحة الكلاس كان سواليف كثير .. وانا بنسبة لي اشوفه ممتع 😅بس البعض يشوفها سلبية \nمعليش طولت ☠️☠️☠️","hours":[],"teach":0,"grade":0,"pid":"tg-p17347-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/17347","user":"THE_WOLF1R","ts":1673281016000,"mid":17347}}]}', 1673281016000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ahuman18-engl101', 'tg-ahuman18', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-owen","n":"Jonathan Owen","en":"","img":"","e":"","bld":"","room":"","d":"Owen انا منزل عنده الصدق احس ان شرحة وسط لكن حصته فيها محتوى شوي ويطلع عن الدرس كثير\nالفيد باك حقه فيه انفصام وقت البراكتس يكون طيب تروح المكتب يمسح فيك الارض على كل كلمة\nالرجال قلت له اني ممكن اجيب B+ في ثاني رايتنق تاسك ضحك وكذا ف اتصور انه يبني نظرة اولية لقريد الطلاب الكويسين البقية هبد","hours":[],"teach":0,"grade":0,"pid":"tg-p40679-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/40679","user":"Ahuman18","ts":1679596049000,"mid":40679}}]}', 1679596049000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-someone_che-engl101', 'tg-someone_che', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-gazdar","n":"Mahir Gazdar","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢٢\nاسم الدكتور: \nMAHIR GAZDAR\n اسلوب:\n أهدأ دكتور وأكثرهم أخلاقًا مر علي بالجامعة، إنسان طيب وحبيب، بس يعيبه الشرح حقه تحس نفسك بتنام وسط الكلاس إلا إذا بتتفاعل معه صدق. \n\nفيدباك:\nالقريدات حقته رهيبة لو عطيت ال essay حقه، وهو إنسان مساعد ولو رحت له الأوفيس أور بيساعدك مرة متأكد. لكن حاول بشكل عام أنك تنتبه لكلماتك وخل ال essay حقك منظم وأيضًا ال reading و writing portfolio حاول بقدر الإمكان أنك stick to their rules.\nدرجات:\nيعطي B,B+ لو اجتهدت معه وحتى يمديك بال A و A+ لو كنت كويس مرة بالإنجلش\nتحضير:\nيحضر بداية كل كلاس ينادي بالأسامي\nبورتفليو:\nتكلمت عنه فوق\n\nالسلام عليكم.. \nلكثرة الاستفسارات الي جاتني عن الدكتور MAHIR GAZDAR ليش\nأني كتبت عنه كلام جيد نوعًا ما بالنسبة للي يسمعوه من باقي الطلاب.\nالدكتور هذا أولًا لا هو سيء جدًا ولا هو جيد وكريم بالدرجات، يعني الي يسوي الي يقوله الدكتور بالضبط ويعرف كيف يبني الجمل والفواصل بينهم ما بينزل تحت C+.\nونصيحة لأي أحد بياخذ إنجليزي، لو تبي درجات من دكتورك اعرف أغلاطك واسأل الدكتور ليش عطيتني ذا القريد وسوي الي يقوله لك بالحرف الواحد ولا تتفلسف.\nتعلم ودور عن كلمات أكاديمية أكثر قوقل واليوتيوب مليانين ولو تبي قريد اكتب كثير حتى لو ما طلب منك الدكتور ولو كان الدكتور يرضى توريه فخير وبركة ولا فيه برامج تسوي لك evaluation لكتابتك مثل grammarly وغيره.\nأنا كنت ي تاسكاتي آخذ D و D+ لكن يوم عرفت أغلاطي وصلحتها صرت آخذ B و B+.\nواستغل الميد والفاينل لأنهم سهلين وخذ فيهم قريد ممتاز عساس يرتفع قريدك في المادة أكثر فعشان مذا ذاكر له ولا تهمله.\nوبس بالتوفيق للجميع","hours":[],"teach":0,"grade":0,"pid":"tg-p53119-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53119","user":"someone_CHE","ts":1686087469000,"mid":53119}}]}', 1686087469000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-someone_i4-engl101', 'tg-someone_i4', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-cameron","n":"Joseph Mark Cameron","en":"","img":"","e":"","bld":"","room":"","d":"انقلش 101 - 221\n\nاسم الدكتور: Joseph Mark Cameron\n\n اسلوب: \nماتوقع بتشوف دكتور يونس زيه بهالقسم, يمزح طول الكلاس و يصير مهرج احيانا ومع ذلك شرحه جدا ممتاز ويوصل لك المعلومه بكل وضوح ويفهمك وش المطلوب منك لو تركز معه بالكلاس, يستقبل اي سؤال ويجاوبه من قلب ويعطيك حقك بالاجابه. التصحيح بهالكورس يكون مبني على راي الدكتور ف غالبا بيعطيك كلام تقدر تمشي عليه وقت الاختبار. يوضح لك الاشياء اللي يفضلها والاشياء اللي ماتعجبه , بشكل عام كلاسه عسل و 10/10, يمر بدون ماتحس فيه\nبالاوفس ماهو مره مهرج, يكون كل تركيزه انه يخدمك ويساعدك ويعلمك ب اغلاطك عشان تتجنبها ويرمي لك نصايح تفيدك \nمن الاشياء اللي مره عجبتني فيه انه حفظ اغلب الطلاب واسماءهم من اول يوم, وللحين يتذكرنا ودايم يجي يسولف اذا قابلنا\n \n\nفيدباك:\n الفيدباك حقه جدا رهيب, يعلمك اغلاطك بوضوح وبدون لف ودوران, مو دايم يعلمك كيف تصلحها لكن مرات يقول لك كيف تصحح الاغلاط. مرات يقترح عليك اضافات عالنص عشان يصير احسن و مرات يقول لك لو تغير الشي ذا بيتحسن النص كثير و و . باختصار بيعلمك اغلاطك وبيعطيك نصايح تطور كتابتك. قريداتي كانت بارتفاع طول الترم ومع كل فيدباك كانت تتحسن\n\nدرجات: \nبالاول بيعطيك حقك, بعدين اذا عرفكم وتعود عليكم ممكن يبدا يتساعد معكم ويدفكم شوي شوي. خصوصا الطلاب اللي يعرف اهتمامهم بالماده . مب يبخل عليكم ابدا حسب تجربتي. \n\nتحضير: 10 دقايق بعدها ليت, 20 دقيقه بعدها غياب. يسمح بالميك اب ومتساعد كثير بالترم اللي درست عنده عالاقل\n\nبورتفليو: انا عطاني A+  فيهم كلهم, ماادري عن باقي الطلاب صراحة بس اذكر ان الكل كان راضي عن درجته من سكشننا ف واضح انه عطاهم حقهم ولا ظلمهم\n\nتقييم:  high 9","hours":[],"teach":0,"grade":0,"pid":"tg-p53122-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53122","user":"someone_I4","ts":1686088045000,"mid":53122}}]}', 1686088045000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ear8700-engl101', 'tg-ear8700', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-mclaren","n":"Peter McLaren","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢٢\nاسم الدكتور:Peter McLaren\n اسلوب: ممتاز جدًا ولطيف ويحب يسولف وخفيف دم ومتعاون مرة كثير الذبات على سواقة السعوديين والانقليز لانه اسكتلندي(: وصراحة الكورس معه خفيف ومن الطف الكلاسات في اليوم كلاسه\nكشرح يشرح المطلوب ويستقبل الاسئلة بصدر رحب وتحسه يحبك تسأله\n\n \n\nفيدباك:\nجيد بس صراحة كان يمديه يتوسع اكثر اظن لو رحت له المكتب يزبطك\n\nدرجات:\nيعطيك حقك وأكثر من حقك بس روح له الاوفس وشوف شاللي يبي وشاللي مايبي ودايم يلمح على انه اذا عرف ان الطالب مجتهد بيمشي بعض اغلاطه وبيتساهل معاه ( فهمي الشخصي لكلامه)\n\nتحضير:\nيحضر كل يوم أول الايام شديد في التأخير  وكان يسجل حضور اول الكلاس وبعدين شوي شوي يتساهل وصار مايسجله الا اخر الكلاس ، تقريبًا انا كل يوم اتأخر دقيقتين ثلاث وعادي \n\nبورتفليو:\nضبطنا صراحة ومدد الديدلاين اكثر من مرة كان يؤكد على ان الفكرة من البورتفوليو انك تورينا انك اديت جهد \n\nفي الرايتنق بورتفوليو تساهل معنا جدًا ماطلبت منا تأشير ولا حاجة وكان يقول بس عدل الي عطيتك عليه فيد باك وفعلاً صدق\n\nكأفرج في البورتفوليو اخذت A بمجهود عادي \n\n\n\nتقييمه 9/10 ولو اقدر انزل عنده 102 لفعلت وللأسف انه بيدرس التحضيري الترم الجاي 😞","hours":[],"teach":0,"grade":0,"pid":"tg-p53133-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53133","user":"EAR8700","ts":1686090355000,"mid":53133}}]}', 1686090355000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-wrlkp-engl101', 'tg-wrlkp', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adil","n":"Adil Mahmood","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢٢\nاسم الدكتور: Adil Mahmood \n\nاسلوب: الدكتور كتعامل وأخلاق جداً ممتاز، دائماً متعاون ويستقبل الأسئلة بصدر رحب. طول الوقت تشوفه مبتسم يحب يسولف وينكت بالكلاس وأحياناً يضحك. بالنسبة لشرحه اعتبره توب صراحة، وهو اكثر شي إيجابي عنده. نقطة إضافية برضو ما كان يقول شي اذا فتحت جوالك أو اشتغلت على شي ثاني وقت الكلاس كان يطنش طول الوقت، وهذا شي حلو. \n\n\nفيدباك: كنت مطنش المادة شوي فما اخذت ولا فيدباك من عنده بالاوفيس ومرة وحدة عطاني فيدباك بالبلاكبورد. فما عندي خبرة كثيرة بأسلوبه بالفيدباك\n\nدرجات: بغض النظر عن انه 90 بالمية من اللي كانوا منزلين معه يذموه من ناحية الدرجات. انا شخصياً كان يعطيني حقي وأشوف درجاتي اللي اخذتها بالWTs جداً منطقية وتناسب المستوى تبعي بالكتابة\n\nتحضير: ملتزم بالتحضير اغلب الوقت يمشي على النظام، مرتين غيبني لاني بس تأخرت اكثر من 5 دقايق. أحياناً يمشي وأحياناً لا على المزاج، وبرمضان كان متعاون شوي من هالناحية\n\nبورتفليو: الريدنق بورتفوليو تصحيحه مزاجي ما تعرف ايش يبغى بالضبط بس عالعموم جبت متوسط A فيهم وما كنت اتعب عليهم كثير. اما الرايتنق بورتفوليو يعطي كل واحد حقه\n\n\nالتقييم النهائي: 8/10 لو لقيته مرة ثانية بنزل عنده","hours":[],"teach":0,"grade":0,"pid":"tg-p53134-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53134","user":"wrlkp","ts":1686090556000,"mid":53134}}]}', 1686090556000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-aaaa77118-engl101', 'tg-aaaa77118', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-pamela","n":"Pamela","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢٢\nاسم الدكتور:Pamela \n اسلوب: الصدق اسلوبها مره كويس وحسيت كلاساتها خفيفه بس مرات تفصل على كم بنت لكن الكلاس الي بعده تنسى الموضوع باختصار مو حقانيه. تشرح من سلايدات الدبارتمنت والصراحه حلو شرحها اول مره افهم الرايتنق وتعلمك هي ايش تبي بالضبط.\n \nفيدباك: طبعا تعطي فيدباك واحد على كل نوع من الاسي ممكن هذا الفيدباك يكون قبل الرايتنق تيست ويمكن يكون بعد الرايتنق تيست يعتمد هل هي مشغوله ولا وهذا الشي مره كويس لاني اشوف بعض الدكتورات مايعطون فرصه قبل الرايتنق تيست. تعطي فيدباك بالكلاس بعد اشوفه مره حلو وواضح وتبين هي ايش تبي وايش الاشياء الي ممكن تنقصين عشانها.\n\nدرجات:البورتفوليو حلوه قريداتها عطتني A+ فيه اما الرايتنق تيست نوعت لي بالقريدات الصدق و رايتنق الفانيل طلع في نفس الرينج حق درجاتي فهذا دليل انها تعطيك حقك بالضبط.\n\nتحضير:اول كم اسبوع كانت شديده شوي لكن بعدها بفتره صارت تاخذ الحضور والي يتاخرون تحطهم حضور بعد.\n\nبورتفليو: زي ما قلت فوق القريدات في البورتفوليو كويسه اذا عبيتي لها الصفحه الوان وكلام وحاولوا تعبون boxes with long answers لان اذا شافت شي سطر او سطرين تنقص \n\nباختصار اي احد يقول الكورس ما يعتمد على الدكتور اعارضه وبقوه. كل شي يعتمد على دكتورك حرفيا حاولوا تختارون الدكتور الكويس وحتى اذا طحتوا بدكتور شوي شديد افهموا هو ايش يبي بالضبط وامورك بتمشي ان شاء الله \n\nبالنهايه هذا الكورس كل طلاب الجامعه يعانون منه حتى وان طلعتوا بقريد مو راضين فيه عندكم فرصه بالكورسات الجايه \nالله يوفقكم ويرزقكم A+\n\nتقيمي لها 8/10","hours":[],"teach":0,"grade":0,"pid":"tg-p53157-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53157","user":"aaaa77118","ts":1686126371000,"mid":53157}}]}', 1686126371000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-frmarhoon-engl101', 'tg-frmarhoon', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-taiseer","n":"Taiseer","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٢٢\nاسم الدكتورة: تيسير\n اسلوب:\n لطيفة وعسل تمزح احيانا بس محترمة يعني، يعني مو ذيك الفلة ولا ذيك النفسية ان شاء الله بترتاحي لها\n\nفيدباك:\nروحي لها اوفيس اور تشرح لك الفيدباك اذا ما فهمتيه، هي كذا ما تعطيك وش تبغا بالضبط يعني تقول جرامر، أو كلمة ناقصة، عاد انتي حاولي تعرفي وش هي او روحي لها.\n\nدرجات:\nالمعروف انها تخسف في الدرجات لكن لاحظت ان مستوايي كان يتحسن مع كل مرة، فأشوف أنك تتدربي واجد على الكتابة ووقت الكلاس اكتبي وش الكلمات والعبارات الي تعجبها بتلاحظي أن عندها تفضيلات معينة سوي زي ما تبغا هي وان شاء الله قريد حلو \n\nتحضير:\nتحضر في الاكسل موجود بالبلاك بورد شيكي عليه باستمرار، عادي جدا تتأخري وما تحط شي، متعاونة في هذي النقطة \n\nبورتفليو:\nاسأليها وش تبغا، لا تسلمي الا شيكتي عندها في الاوفيس اور أن كل شي تمام خاصة اول مرة، اذا فيه سؤال ما عرفتيه خليها تشرحه لك، تعطيك نصايح وكذا اهم شي سوي زي ما تبغا هي","hours":[],"teach":0,"grade":0,"pid":"tg-p53181-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/53181","user":"FRMarhoon","ts":1686134536000,"mid":53181}}]}', 1686134536000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-rand_142-engl101', 'tg-rand_142', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-gazdar","n":"Mahir Gazdar","en":"","img":"","e":"","bld":"","room":"","d":"غريبه مع ان هذا الي شفته فوق\nانقلش ١٠١-٢٢٢\nاسم الدكتور: \nMAHIR GAZDAR\n اسلوب:\n أهدأ دكتور وأكثرهم أخلاقًا مر علي بالجامعة، إنسان طيب وحبيب، بس يعيبه الشرح حقه تحس نفسك بتنام وسط الكلاس إلا إذا بتتفاعل معه صدق. \n\nفيدباك:\nالقريدات حقته رهيبة لو عطيت ال essay حقه، وهو إنسان مساعد ولو رحت له الأوفيس أور بيساعدك مرة متأكد. لكن حاول بشكل عام أنك تنتبه لكلماتك وخل ال essay حقك منظم وأيضًا ال reading و writing portfolio حاول بقدر الإمكان أنك stick to their rules.\nدرجات:\nيعطي B,B+ لو اجتهدت معه وحتى يمديك بال A و A+ لو كنت كويس مرة بالإنجلش\nتحضير:\nيحضر بداية كل كلاس ينادي بالأسامي\nبورتفليو:\nتكلمت عنه فوق","hours":[],"teach":0,"grade":0,"pid":"tg-p55058-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/55058","user":"rand_142","ts":1692707146000,"mid":55058}}]}', 1692707146000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-gresh_77-engl101', 'tg-gresh_77', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-lees","n":"Steven Lees","en":"","img":"","e":"","bld":"","room":"","d":"لا احد ينزل عند Steven less والله يانه خسف فيني خسف","hours":[],"teach":0,"grade":0,"pid":"tg-p84431-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/84431","user":"gresh_77","ts":1697786287000,"mid":84431}}]}', 1697786287000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-yazdoo-engl101', 'tg-yazdoo', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-loftus","n":"John Loftus","en":"","img":"","e":"","bld":"","room":"","d":"ما شاء الله ياحظك بلوفتس والله\nرهيب شخصية وأدبا واخلاقا\nوما ينساك ابد\nلو اجيه يجي يبادر يسلم علي حتى لو ما رحت له، غير انه فخخم احسه ينفع ممثل افلام وربي اسطوره هالدكتور ليتني سجلت عنده ولا ترددت","hours":[],"teach":0,"grade":0,"pid":"tg-p84483-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/84483","user":"YazDoo","ts":1697799660000,"mid":84483}}]}', 1697799660000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-anoymous55-engl101', 'tg-anoymous55', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-loftus","n":"John Loftus","en":"","img":"","e":"","bld":"","room":"","d":"قريدات سكشني مع لوفتس كانت حلوه \nبس للامانه سكشني دوافير وانقليزيتهم كويسه + شرح الدكتور ممتاز","hours":[],"teach":0,"grade":0,"pid":"tg-p89972-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/89972","user":"anoymous55","ts":1700143814000,"mid":89972}}]}', 1700143814000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-u1373296493-engl101', 'tg-u1373296493', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adamkhan","n":"Adam Khan","en":"","img":"","e":"","bld":"","room":"","d":"Adam khan \nدكتوري الترم هذا \nكشرح ممكن يكون فيه افضل منه بس انه ما يقصر يجاوب كل الاسئله ويساعد قد ما يقدر \nبالنسبه للتصحيح والدرجات اشوفه كويس من تجربتي ويعطيك حقك اذا مب زود \nوتعامله رهيب جدا مع الطلاب ووسيع صدر فالكلاس","hours":[],"teach":0,"grade":0,"pid":"tg-p92741-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/92741","user":"","ts":1701451966000,"mid":92741}}]}', 1701451966000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-sirotb-engl101', 'tg-sirotb', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-cameron","n":"Joseph Mark Cameron","en":"","img":"","e":"","bld":"","room":"","d":"الآدمي يشرح زين ويوضحلك بالضبط وش يبي منك بالكورس + رهييب وخفيف دم طول الكلاس يذب ويطقطق رههيييب رهيييب. \n\nتصحيحه بيناسبك اذا انت كويس بالرايتنق؛ لأن اذا انت ممتاز ماعنده مشكلة يعطيك قريد عاالي واذا انت سيء بيخسفك. \n\nعكس الدكاترة الثانية بعضهم يتغاضى شوي عن السيئين ومايعطي قريدات عالية للكويسين ويخلي الكل قريبين من بعض فالقريد ( يكون الرينج عنده C-B ) لكن كاميرون الرينج عنده حرفيًا ( A+ الى F ) \n\nانا عن نفسي مستواي بالرايتنق متوسط وقاعد اخذ قريدات مُرضيه مع كاميرون للأمانة.","hours":[],"teach":0,"grade":0,"pid":"tg-p109918-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/109918","user":"SirOTB","ts":1704015148000,"mid":109918}}]}', 1704015148000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-op0j0-engl101', 'tg-op0j0', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-harrison","n":"Samuel Harrison","en":"","img":"","e":"","bld":"","room":"","d":"اول ترم له ذا بشكل عام الدكتور عسل اسلوب وتعامل ويهتم للطلاب كثير \nولكن موضوع تصحيح انا اشوفه عادي زي اي دكتور ثاني","hours":[],"teach":0,"grade":0,"pid":"tg-p112372-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/112372","user":"op0j0","ts":1704104506000,"mid":112372}}]}', 1704104506000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-xxuqv-engl101', 'tg-xxuqv', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-taiseer","n":"Taiseer","en":"","img":"","e":"","bld":"","room":"","d":"اخلاق عاليه وتعاون واضح بالأوفيس اور وجدا دقيقه بالدرجات وتعطيك حقك إذا مشيتي على كلامها وعلى الروبرك وتوضح لك كل شي ما تحسين نفسك تايهه والفيدباك حقها زين","hours":[],"teach":0,"grade":0,"pid":"tg-p112532-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/112532","user":"xxuqv","ts":1704110418000,"mid":112532}}]}', 1704110418000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-mm51_m-engl101', 'tg-mm51_m', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-taiseer","n":"Taiseer","en":"","img":"","e":"","bld":"","room":"","d":"تيسير حقانيه ماتعطيك اكثر ماتستحقين ولا تظلمك بالدرجات فصراحه اشوفها افضل السيئين لكن لو في احد احسن روحيله","hours":[],"teach":0,"grade":0,"pid":"tg-p113192-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/113192","user":"mm51_m","ts":1704121417000,"mid":113192}}]}', 1704121417000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-mjforever_7292-engl101', 'tg-mjforever_7292', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adamkhan","n":"Adam Khan","en":"","img":"","e":"","bld":"","room":"","d":"اشوفه يعطيك حقك وزياده \nالريدنق بورتوفوليو الثالث والرابع سلمته وهو فاضي ما كتبت إلا شوي فيه واعطاني قريد مرضي \nيقول ايش يبغا منك الدكتور واضح حتى في الفيد باك \nومن ناحيه التعامل فهو اسطوري ويحب ينكت في وسط الكلاس وانا استلمته 😂","hours":[],"teach":0,"grade":0,"pid":"tg-p114001-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/114001","user":"Mjforever_7292","ts":1704164858000,"mid":114001}}]}', 1704164858000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-deena012-engl101', 'tg-deena012', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-loftus","n":"John Loftus","en":"","img":"","e":"","bld":"","room":"","d":"John Loftus \nما انصحك صراحه فيه فرق كبير بين درجتي في الرايتنق تيست والفاينل رايتنق وما يوضح ايش يبي بالضبط","hours":[],"teach":0,"grade":0,"pid":"tg-p114009-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/114009","user":"Deena012","ts":1704177300000,"mid":114009}}]}', 1704177300000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-abo3mar_albkhyt-engl101', 'tg-abo3mar_albkhyt', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-hampson","n":"Timothy Hampson","en":"","img":"","e":"","bld":"","room":"","d":"درسني ١٠١ وصح اني ما احب شخصه لكن دكتور محترم ويرحب بالأسألة وإذا مشيت على كلامه بالكلاس والستركشر اللي يعطيك اياه تقدر تضمن قريد كويس بالرايتنق تاسك\nالحقيقة لعدم معرفتي بالدكاترة الثانيين وكيف تصحيحهم وتدقيقهم ودي انزل عنده مرة ثانية حسيت بالأمان معه","hours":[],"teach":0,"grade":0,"pid":"tg-p114090-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/114090","user":"Abo3mar_albkhyt","ts":1704200960000,"mid":114090}}]}', 1704200960000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-rayan_ah20-engl101', 'tg-rayan_ah20', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-vernon","n":"Sam Douglas Vernon","en":"","img":"","e":"","bld":"","room":"","d":"الدكتور شرحه كويس ، تعامله مره كويس ، يرد على الايميلات بسرعه ، لكن ما يعطي قريدات","hours":[],"teach":0,"grade":0,"pid":"tg-p114746-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/114746","user":"Rayan_ah20","ts":1704627395000,"mid":114746}}]}', 1704627395000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-q1une-engl101', 'tg-q1une', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-loftus","n":"John Loftus","en":"","img":"","e":"","bld":"","room":"","d":"مستواي اعتبره تقريباً سيء واول رايتنق هبدت فيه وعطاني B\nوثاني رايتنق طلعت وانا ابكي كنت ضامنه اني بجيب F وبالاخير عطاني C+ \nوالريدنق بورتفوليو ابدعت فيه وعطاني A\nوالرايتنق بورتفوليو حرفياً سويته برجلي وتقريبا باربع ساعات وعطاني A\nباختصار اعطاني اكثر من مستواي وجهدي بكثيررررررررر وانصح الكل فيه","hours":[],"teach":0,"grade":0,"pid":"tg-p115271-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/115271","user":"q1une","ts":1704905339000,"mid":115271}}]}', 1704905339000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-u1980849955-engl101', 'tg-u1980849955', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-megan","n":"Megan","en":"","img":"","e":"","bld":"","room":"","d":"انا الي بعرفها هي ميقن وشرحها كويس مع انو اخر السنة مو مرة ومشكلتها في الميد والفاينل ما تعرف تساعدك لان شرحها في الجرامر سيء الصراحة. جريداتها تعطيكي الي على مستواكي وبيكون acceptable يعني","hours":[],"teach":0,"grade":0,"pid":"tg-p115554-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/115554","user":"","ts":1704929393000,"mid":115554}}]}', 1704929393000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-iamlatifa-engl101', 'tg-iamlatifa', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-gazdar","n":"Mahir Gazdar","en":"","img":"","e":"","bld":"","room":"","d":"من ناحية قريدات كلنا بالبداية اعطانا قريدات سيئه وكلاساته جدًا مملة وما تعرفين هو وش يبغى واذا قلت له وشلون اسوي كذا يقولك ask yourself why بس بطريقه ان يبغاك تعبرين اكثر \nهو اخلاق صراحه اخلاقه جدًا عالية وتستحين من اخلاقه يعني مره محترم وكلاسي كان فوضى ف ماكان يقول شي يستحي مره، بس لو تفاعلتي معاه بالكلاس وجلستي قدام ممكن يجيب نتيجة الموضوع\nمن ناحية تحضير اول مره اشوف دكتور مره متساهل بالتحضير يعني لو جيتي متاخره ربع ساعه يحط حضور او ليت حتى لو جيتي بنص الكلاس وكنت اشوف بنات يحضرون بالبداية ويطلعون ومو على طول ياخذ الحضور بداية الكلاس\nقريداته بعدين شوي تحسنت لكن اشوفه ظلمني بالريدينق برتفوليو  والفيد باك حقه اشوفه اسوء شي بالعالم يحدد لك مليون سطر ويكتب عليه كلمه ما تعرفين بالضبط وش يبغى \nلو بيمديك تغيرين غيري ولو عندك وقت للانقلش وبتشدين حيلك اقعدي معه لان الوضع يبغى له كذا","hours":[],"teach":0,"grade":0,"pid":"tg-p115898-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/115898","user":"iamlatifa","ts":1705094621000,"mid":115898}}]}', 1705094621000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-icjzj-engl101', 'tg-icjzj', 'ENGL 101', 'doc', '{"docs":[{"id":"stk-dr-en115421","n":"Mr. Keith Pearson","en":"","img":"","e":"","bld":"","room":"","d":"Keith Pearson \nهذا كوردنيتر المادة ، تعليمه رهيب مره ويعطيك كافة المصادر والتسهيلات للمادة ، تصحيحه دقيق شوي ولكن دايم ياخذ نماذج من رايتنق الطلاب ويصححه ويعطيك نقاط ضعفك وقوتك","hours":[],"teach":0,"grade":0,"pid":"tg-p143288-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/143288","user":"icjzj","ts":1717228463000,"mid":143288}}]}', 1717228463000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-im_the_neon-engl101', 'tg-im_the_neon', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adil","n":"Adil Mahmood","en":"","img":"","e":"","bld":"","room":"","d":"الترم 232\nالدكتور: عادل محمود \nالقريد: A+\nالدكتور بالبداية شرحه ما ناسبني بعدين لما مشينا بالكورس شرحه تعدل وصار وافضل \nمتعاون جدا ويستمع لاراءنا ويطبقها \nالفيد باك حقه كان كافي بالنسبه لي مااحتجت اروح له بالاوفيس اور كثير  ولكن الافضل تروح لهم طبعا \nالدكتور لو ركزت معاه بيوضح لك وش يبغى بالضبط منك \nبالكلاس يخلينا نكتب بعد مايشرح ويقولنا اللي يبي يوريني ويعطينا رأيه وايش نعدل\n\nيحب اللي يشارك معاه بالكلاس ويتفاعل معاه\n\nتصحيحه يعطيك حقك بالضبط واحيانا اشوف انه يعطي زيادة كمان\nاما بالنسبة للماده بشكل عام طريقتي كانت :\n●.للرايتينق كنت اركز مع الدكتور بالكلاس واكتب نوتات هو وش يبي ووش يحذر منه واكتب معاه لما يطلب منا \n●.الواجبات اسلمها له باحسن نسخه اقدر عليها علشان يطلع لي الاخطاء اللي فعلا ممكن اغفل عنها \n●.قبل الرايتينق تاسك كان على الاقل عندي ثلاثة فيد باك منه .. قبل الاختبار بيوم افتح ستركتشر الرايتينق الموجود هنا بالردود واراجعه واراجع فيد باك الدكتور واراجع الروبريك \n●.بالنسبة للميد\nالريدينق البروتوفوليوز لو تدربت عليها صح زي ما نصحونا باذن الله يمديك على القريد وهو اهم حاجه بالميد لانه وزنه الاثقل \n●.الفوكاب اللسته سهلة جدا بس مهم التعاريف بالانجلش تقرأها وتفهمها وتفهم مكان توظيفها \n●.القرامر بالميد خبصت فيه لانه ما تدربت عليه كاسئلة ..بالفاينل بعد ماراجعت فتحت الكويزات اللي نزلها دكتوري عليه وحليت كم واحد وارتفعت قريدين فيه \nالقرامر في له مصادر عدة \nاما سلايدات القسم او الروابط الي بيعطونكم اياها \nعن نفسي اعتمدت الروابط والملخصات بالتلجرام بعدين الكويزات اللي منزلها دكتوري يالبلاك بورد \n●.الفاينل نفس الميد من ناحية القرامر والفوكاب والريدينق \nونفس التجهيز للرايتينق \nووفقكم الله","hours":[],"teach":0,"grade":0,"pid":"tg-p144852-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/144852","user":"im_the_neon","ts":1717515253000,"mid":144852}}]}', 1717515253000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-re_99s-engl101', 'tg-re_99s', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-watts","n":"Stephen Watts","en":"","img":"","e":"","bld":"","room":"","d":"السلام عليكم ورحمة الله وبركاته \nانقل لكم تجربتي مع مادة انجليزي 101\nTerm: 232\nInstructor: Stephen watts\n\nالتحضير: اول الكلاس وصارم جدا في التحضير لذلك احسب حسابك.\nالشرح: يفتح سلايدات القسم ويقرأها وما في شي مميز في شغله. بس انه يكتب ملف فيه نصايح للاستعداد للميد والفاينل + عيّنة ايساي لكل نوع.\nالفوكاب ما يعطيه وجه، القرامر بس جزئية وحدة. يمشي مع خطة الكلاسات اللي حاطها القسم.\nاضافات: متعاون جدا في وقت الساعات المكتبية وفي التصحيح يحاول يلقى اي شي سويته في الرايتنق حقك عشان يرفعك قريد بناء على الروبرك. إذا لقى عطاك واذا ما لقى خلاك.\n\nطريقة المذاكرة:\n\n1-الفوكاب: \nطبعا أكثر الفوكاب كان مألوف وسهل تعرف معناه واللي ما اعرفه كنت اجيب له مرادف او احفظ معناه ثم انتقل للتمارين واحلها.\n\n2- القرامر: أقل جزئية أخذت مني وقت لاني كنت في انجليزي الاوريا أركز عليه هو والتوفل\n\n3- الريدنق: كان أكثر شي اركز عليه لأنه يساعد كثير في الرايتتق، كنت افهم وش يصير في القطعة جملة بجملة واستخدم بعض العبارات اللي تساعدني في الكتابة، وهذا طوّر الكتابة بشكل ملحوظ عندي. كنت احرص في الاوفيس ازوره عشان الريدنق قبل الرايتنق\n\n4- الرايتنق\nنهاية الأسبوع اختار موضوع مرتبط بالريدنق (بعد ما اخلص الريدنق)  واحط التايمر 50 دقيقة واحاول اتبع الروبرك والنمط اللي مسويه الدكتور في العينات في كل باراقراف اكتبه واستخدم الفوكاب اللي تعلمته.","hours":[],"teach":0,"grade":0,"pid":"tg-p144901-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/144901","user":"Re_99s","ts":1717517448000,"mid":144901}}]}', 1717517448000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ice_ninja-engl101', 'tg-ice_ninja', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-lees","n":"Steven Lees","en":"","img":"","e":"","bld":"","room":"","d":"Steven Lees\nشريح\nمتعاون\nادب\nكلاساته حلوة\nيديك راحتك نوعا ما\nوتصحيح الرايتنج بالنسبة لي كانت حلوة","hours":[],"teach":0,"grade":0,"pid":"tg-p207045-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/207045","user":"Ice_Ninja","ts":1734897743000,"mid":207045}}]}', 1734897743000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-wherethisisgoing-engl101', 'tg-wherethisisgoing', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-saddia","n":"Saddia","en":"","img":"","e":"","bld":"","room":"","d":"Saddia  \nخلص الترم وما أعرف إذا اسمها ساديا أو سعدية \n\nبس عموماً الكورس معاها كان جيد\nأول ترم لها على طول دخلت بالجو تعطي فيد باك حلو للرايتنق وتركز بالشرح على السكيلز الي تنقصنا","hours":[],"teach":0,"grade":0,"pid":"tg-p207091-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/207091","user":"wherethisisgoing","ts":1734906124000,"mid":207091}}]}', 1734906124000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-aboatb2005-engl101', 'tg-aboatb2005', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-cameron","n":"Joseph Mark Cameron","en":"","img":"","e":"","bld":"","room":"","d":"في دكتور اسمه جوزيف ماكرون يدرس بنات وعيال\nالدكتور زين كشرح واهتمام ويوضح كل نقطة\nلكن سلبياته تصحيحه مو ظالم لكن مو متساهل. مثلا ما في طالب بسكشنا جاب A","hours":[],"teach":0,"grade":0,"pid":"tg-p207106-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/207106","user":"Aboatb2005","ts":1734908295000,"mid":207106}}]}', 1734908295000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-kxqx0-engl101', 'tg-kxqx0', 'ENGL 101', 'doc', '{"docs":[{"id":"stk-dr-en96633","n":"Mr. Lance King","en":"","img":"","e":"","bld":"","room":"","d":"لانس كنق مرا كويس ، يحاول يرفع البنات اكثر شيء ممكن الرايتنق الثاني ما أعطى f ولا d الكل c و فوق","hours":[],"teach":0,"grade":0,"pid":"tg-p207162-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/207162","user":"kxqx0","ts":1734950977000,"mid":207162}}]}', 1734950977000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-iamabdullah0-engl101', 'tg-iamabdullah0', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-jamesjoseph","n":"James Joseph","en":"","img":"","e":"","bld":"","room":"","d":"جيمس جوزيف\nحبيب ، اخلاق ، شرررررررررررررريح ، الرايتنق اول ضبطنا بالدرجات بس الثاني خسفنا ، عمومًا رهيب انصح","hours":[],"teach":0,"grade":0,"pid":"tg-p212303-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/212303","user":"iamabdullah0","ts":1735059002000,"mid":212303}}]}', 1735059002000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-aj0ad-engl101', 'tg-aj0ad', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-cook","n":"Austin Cook","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-241\nاسم الدكتور: اوستن كوك Austin Cook\n اسلوب: اسطوري ، في البداية شرحه كان مش ولابد بس في بعد الرايتنق الاولى عرف الخلطة وبدا يشرح كويس ، ويمزح في نص الكلاس .\n \n\nفيدباك: في البداية ما كان يدري وين الله حاطه لانه جديد بس بعدين حط اوفيس اور كل يوم ساعتين ويجتهد في الفيدباك يقيمك على الروبرك والسلايدات ويعلمك كم القريد اللي ممكن تاخذه لو كتبت زيها في الاختبار.\n\nدرجات: كان زي اللي ناخذه في الفيدباك فكان واضح المعايير واغلب القريدات حقتنا ارتفعت من بعد الرايتنق الاول.\n\n\nتحضير: بالضبط ممكن راعيك شوي بس غالبا بالضبط.\nنزل عنده لو تخرب جدولك لعيونه","hours":[],"teach":0,"grade":0,"pid":"tg-p214050-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/214050","user":"aj0ad","ts":1735129368000,"mid":214050}}]}', 1735129368000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-sko0onx-engl101', 'tg-sko0onx', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-cameron","n":"Joseph Mark Cameron","en":"","img":"","e":"","bld":"","room":"","d":"انا درسني جوزيف كاميرون كويس \nشرحه حلو ويعطي ملاحظات عن الرايتنق والي يشوفه غلط في كل مره يصحح للطلاب ينبه الكل عنه عشان مايسووه بالرايتنق الفعلي ويعطي فيدباك مضبوط","hours":[],"teach":0,"grade":0,"pid":"tg-p215111-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/215111","user":"Sko0onx","ts":1735486293000,"mid":215111}}]}', 1735486293000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-if6amr-engl101', 'tg-if6amr', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-gazdar","n":"Mahir Gazdar","en":"","img":"","e":"","bld":"","room":"","d":"Term 241 \nGrade : A \nاسم الدكتور: ماهر قازدار\n\n\nاسلوب: طيب مرره بس ممل ،غالبا بس يحب يقول مواقف او قصص صارت له عشان يغير جو الكلاس، كشرح مااشوف استفدت منه كثير، اقرأ السلايدات بنفسي واحاول اكتب نفس الي فيها او مشابه له + اخلي شات جبت يقيم/يصحح كتابتي ويطور الفوكاب حقي او طريقه كتابتي او حتى يعطيني افكار، اسباب، ارقومنتس ممكن استخدمها كل هذي فادتني وتطورت\n\nفيدباك: يعطي فيدباك جيد على البراكتس تست بس لمن اسئله باوقات ثانيه او اطلب فيدباك مو دايما يعطي \n\nدرجات: يعطيك حقك بالدرجات وغالبا لو كتبت بالرايتنق الثاني نفس مستوى الاول او اقوى شوي يعطيك اعلى بقريد\n\nتحضير: لو جيت متاخر اقل من ٥ دقايق غالبا مايحط ليت بس لو اكثر احيان يحط ليت","hours":[],"teach":0,"grade":0,"pid":"tg-p215578-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/215578","user":"if6amr","ts":1736171886000,"mid":215578}}]}', 1736171886000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-u7321281131-engl101', 'tg-u7321281131', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-cook","n":"Austin Cook","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٤١\nاسم الدكتور: أوستن كوك\n \nاسلوب: أسلوب الدكتور لا يُعلى عليه كل يوم يجي الكلاس و نفسيته حلوه ، يسولف و يمزح مع الطلاب عادي و أسلوبه في الشرح كان واضح ، يشرح السلايد كامل بعدها يسأل الطلاب إذا عندهم اي استفسار و كذا \n \n\nفيدباك: يعطيك وقته كامل في الاوفس اور و ما عنده مشكلة يقعد معك ساعة كاملة عشان بس يفصل في الرايتنق حقك ، ايام الفاينل كان يقعد حتى ساعات بعد ما ينتهي وقت الاوفس حقه الأصلي بس عشان يساعدنا \n\nدرجات: يعطي كل شخص و حقه و ممكن زيادة حتى إذا شافك مهتم و تتابع معه في الاوفس اورز و تطبق نصايحه \n\nتحضير: يحضر اول ٥ دقايق و إذا جيت \nمتاخر شوي لازم ترسل له تيمز انك بتتاخر او غيره انه بيحطك ليت\n\nاوفرل تقييم أعطيه A","hours":[],"teach":0,"grade":0,"pid":"tg-p215894-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/215894","user":"","ts":1736505222000,"mid":215894}}]}', 1736505222000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-d_s335-engl101', 'tg-d_s335', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-gazdar","n":"Mahir Gazdar","en":"","img":"","e":"","bld":"","room":"","d":"انقلش ١٠١-٢٤١\nاسم الدكتور: Mahir gazdar\n اسلوب: الدكتور محترم جدا واخلاقه عالية، يحب بالكلاس يسولف ويقول قصص صارت له بس مو يعني انو كل الكلاس سوالف بس الكلاس ممل\nمشكلة الدكتور انو شرحه مش ولابد وما يفيدك كثير صراحة، فكان الكلاس غالبا غير مفيد\n \n\nفيدباك:  يعطي على ال writing practice فيدباك كويس، اعطانا بداية السمستر اكسل شيت يظهر فيها الرقم الجامعي بس عشان نحط فيها اي شي نكتبه او حتى الاسايمنتس وقال بيعطينا فيد باك هناك، ما حبيتها لانو الفيد باك حقه عليها كان بسيط وما حسيته شامل\n\nبالعادة قبل الرايتنق تاسك بكم يوم كنت اكتب واروح عنده بالاوفيس اورز عشان يعطيني فيد باك، كان يعطيني كم ملاحظة بس وما اجلس اكثر من ٥-١٠ دقايق، ما كان يفصفص النص يعني\nوكل ما رحت عنده كان يقولي بشيكه بسرعة لانو مافي وقت(مع انو ما يكون في احد ينتظر برا) بشكل عام هالانسان دايما مستعجل😭 حتى بعد الكلاس دايما يخرج مستعجل وما تقدر تكلمه \nعموما الفيد باك حقه ما كان ذاك الزود، وكنت غالبا استعين بصحباتي عشان يعطوني هم فيد باك وكان مفيد اكثر :)\n\nدرجات: الحق يُقال يعطي كل شخص حقه واكثر، ولو شاف انك مهتم وانو مستواك تطور من الرايتنق الاول للثاني بيرفعك\n\nتحضير: بالعادة اول ٥ دقايق ما يحط ليت اما بعدها ليت\nلفترة طويلة بالبداية كان يحط الباركود وكان الباركود من دقيقة تاخير ليت فكنا نعاني صراحة وكلمناه عشان يكلم الديبارتمنت ويشيل الليتس الي عندنا وشالهم بالنهاية، وصار هو يحضر يدوي (افضل بكثير)\n\nبورتفليو: ما جربت تقييمه على البورتفوليو لاني ما سبق ان حليته وارسلته، كنت بس اقراه واحله قبل الميد او الفاينل وقت الحاجة","hours":[],"teach":0,"grade":0,"pid":"tg-p215895-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/215895","user":"d_s335","ts":1736505722000,"mid":215895}}]}', 1736505722000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ln7_1-engl101', 'tg-ln7_1', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-adamkhan","n":"Adam Khan","en":"","img":"","e":"","bld":"","room":"","d":"ENGLISH 101 \nGRADE: A+\n\n\nقريد : A+\nاسم الدكتور: ادم خان \n اسلوب: متعاون وسلس بالتعامل  \n \n\nفيدباك: يعطي تفاصيل كثيرة ويدقق ويفضل تلتزم باللي يقول لأن تصحيحه يشبه تصحيح الكورد ف بيفيدك بالفاينل لو مشيت على النقاط اللي يقولها وركزت بالمتطلبات والروبريك\n\nيفضل تستفيد من أغلب التسليمات وتروح له اوفيس اور اذا قدرت بيفيدك\n\nدرجات: يعطيك حقك ويوضح لك ليش وكيف اخذت الدرجة\nال A+ مهو مستحيل حسب قول البعض لحد يخوفكم\n\nتحضير: نظامي الى حد ما(؟) احيان يمشي لو تأخرت بس لا تزودها","hours":[],"teach":0,"grade":0,"pid":"tg-p217347-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/217347","user":"ln7_1","ts":1736931615000,"mid":217347}}]}', 1736931615000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ss123xj-engl101', 'tg-ss123xj', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-watts","n":"Stephen Watts","en":"","img":"","e":"","bld":"","room":"","d":"يدرسني الحين \nمجتهد \nيهتم للطالب \n( ترسله essays بالتيمز يعطيك فيد باك )\nتصحيحه : عادي مو كريم مرا  بس يعطيك على قدك \nاوفس اور دايماً\nباختصار الدكتور مجتهد جدا انه يوصل المعلومة للطالب الباقي عليك انت يا طالب \nالتحضير ؛ في البداية بيكون صارم و كذا  بعدين عادي ( مو عادي طبعاً لكن يمشي التاخير بعض الاحيان )","hours":[],"teach":0,"grade":0,"pid":"tg-p240533-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/240533","user":"ss123xj","ts":1745860295000,"mid":240533}}]}', 1745860295000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-abdulrhmanqarni-engl101', 'tg-abdulrhmanqarni', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-watts","n":"Stephen Watts","en":"","img":"","e":"","bld":"","room":"","d":"دكتوري الترم هذا وكان ممتاز الفيدباك على الرايتنق الي ترسله له يكون اطول من الرايتنق من كثر التفاصيل الي بيقولها لك، شرحه كويس  الاكسنت بريطاني  بحت بس يمشي الحال تصحيحه الصدق شوي شديد بس على العموم ممتاز","hours":[],"teach":0,"grade":0,"pid":"tg-p246837-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/246837","user":"AbdulrhmanQarni","ts":1747500094000,"mid":246837}}]}', 1747500094000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ririee7-engl101', 'tg-ririee7', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-ross","n":"Ross Martin","en":"","img":"","e":"","bld":"","room":"","d":"دكتوري كان كويس الصراحه وعطاني حقي بالرايتنق وطيروه مدري هج هو سافر \nRoss","hours":[],"teach":0,"grade":0,"pid":"tg-p301337-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/301337","user":"ririee7","ts":1762960490000,"mid":301337}}]}', 1762960490000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-s_lq3-engl101', 'tg-s_lq3', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-tylor","n":"Tylor","en":"","img":"","e":"","bld":"","room":"","d":"ما اتوقع فيه احد محدد ولكن الكورس بنفسه يبغاله شغل انا درسني واحد جديد اسمه Tylor كان جيد اشوف انه نقصني شوي الرايتنق الثاني بس كمجمل يمشي الحال","hours":[],"teach":0,"grade":0,"pid":"tg-p323626-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/323626","user":"s_lq3","ts":1766508351000,"mid":323626}}]}', 1766508351000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-hessafm-engl101', 'tg-hessafm', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-flores","n":"David Flores","en":"","img":"","e":"","bld":"","room":"","d":"ديفيد فلورس؟ تصحيح كويس مره لكن كشرح مو مره لانه جديد\nوترا ب١٠٢ ماله علاقه دكتورك بالتصحيح","hours":[],"teach":0,"grade":0,"pid":"tg-p324791-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/324791","user":"HessaFM","ts":1766560190000,"mid":324791}}]}', 1766560190000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-ahm3ed268-engl101', 'tg-ahm3ed268', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-kirkwood","n":"Kristian Kirkwood","en":"","img":"","e":"","bld":"","room":"","d":"حضرت عنده كلاس \nالدكتور يحب يسولف واجد\nواضح ان طيب و سمعت عليه مدح من ناس درسوا عنده 102 الترم الماضي\n\nعنده عيب ان اول مرة يدرس الكورس لان هو أصلا جديد في الجامعة ( بدأ تدريس في 251 )","hours":[],"teach":0,"grade":0,"pid":"tg-p364738-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/364738","user":"Ahm3ed268","ts":1787393441000,"mid":364738}}]}', 1787393441000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('tg-doc-pastinfinity-engl101', 'tg-pastinfinity', 'ENGL 101', 'doc', '{"docs":[{"id":"tg-dr-abri","n":"العبري","en":"","img":"","e":"","bld":"","room":"","d":"العبري بتدمن كلاساته \nحتى بالشرح ما يعترف بالسلايدات يقعد يسولف و يقص قصص و بعدين يعطينا العبره منها و يربطها بالمنهج","hours":[],"teach":0,"grade":0,"pid":"tg-p381570-engl101","imp":{"src":"telegram","url":"https://t.me/KFUPM_ENG101/381570","user":"PastInfinity","ts":1792197765000,"mid":381570}}]}', 1792197765000, 1794334702, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
